window.HB_TR["2-chronicles"]["ks"]=["1. تہٕ داؤد سُند نیچو سلیمان گۆو پننہِ بادشٲہی مَنٛز مضبوط، تہٕ خداوند تٔمۍ سُند خدا اوس أمِس سٍتـ̡ سٍتـ̡ تہٕ کورُن أمِس سٍتـ̡ س�\n2. اَمہِ پَتہٕ کٔر سُلیمانَن سارِنٕے اِسرٲیلِس سٍتـ̡ ، ساسہٕ بٔدۍ تہٕ ہتہٕ ہتہٕ بٔدۍ ہٕندِس کپتانَن تہٕ قاضن سٍتـ̡ تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ باپَن ہٕندِس سردارس سٍتـ̡ کتھ کرنہٕ۔\n3.\\tیێلہِ سُلیمان تہٕ أمِس سٍتـ̡ سٲری جماعت گٔیہِ تتھ تھدِ مقامس پیٹھ یُس {اوس} گِبیونس مَنٛز۔ تِکیازِ اَتہِ اوس خدایہِ سٕنزِ جماعتُک خیمہ یُس موسیٰ سٕندِ خادم اوس بیابانس مَنٛز بنوومُت۔\n4.\\tمگر خدایہ سُند صندوق اوس داؤد کِرجاتجیریم پیٹھٕ تتھ جایہ تُلمت یُس داؤد امہِ خٲطرٕ تیار کورمُت اوس، تکیازِ تٔمۍ اوس یروشلمس مَنٛز امہِ خٲطرٕ اکھ خیمہ لگٲومُت۔\n5. امہِ علاوٕ یُس برازِل قربان گاہ یُس حُور سُند نیچو یُس بٔزلیل اوس بنوومُت، تٔمۍ تھوو خداوند سٕندِس خیمہ برونہہ کُن، تہٕ سُلیمان تہٕ جماعت کٔر أمِس کُن یژھان۔ {تٔمۍ تھوو: یا، اوسا تتہِ}\n6. تہٕ سُلیمان ووت تتہِ خداوند سٕندِس برونہہ کُن بریسن قربان گاہس پیٹھ، یُس جماعت کِس خیمہ خانس مَنٛز اوس، تہٕ اَتھ پیٹھ کٔرٕن ساس زٲلِتھ نذرانہ پیش کرنہٕ۔\n7. اَمہِ رٲژ آو خدا سُلیمانس نِش ظٲہر تہٕ وونُن زِ بہٕ کیا دِیہٕ ژے دِنہٕ۔\n8. تہٕ سُلیمانن ووٚن خدایس زِ ژے کٔر میٲنِس مٲلِس داؤدس سٍتـ̡ سٮ۪ٹھاہ رحمت، تہٕ بنووُن مے تٔمۍ سٕندِ بدلہٕ بادشاہی۔\n9.\\tاے خدایہ، پننِس مٲلِس داؤدس سٍتـ̡ چُھہ پنُن وعدٕ پورٕ سپُدمُت، تکیازِ ژے بنوو میہ أکِس لُکن ہُند بادشاہ یُس بٔڈِتھ زمینہِ ہٕندِس میژِ ہٕندۍ پٲٹھۍ۔ {یِتھ کٔنۍ...: ہیب۔ یوتاہ زٔمیٖنٕچ گردِ ہٕندۍ پٲٹھۍ}\n10.\\tمیہ دِژ وۅنۍ حکمت تہٕ عٔلِم، یُتھ بہٕ نیرِتھ یِمن لُکن برونہہ کُن یِتھ، کیازِ کُس ہیکہِ پننِس لوکَس سٍتـ̡ انصاف کٔرِتھ، یُس بٔڈ چُھہ؟\n11. تہٕ خداین ووٚن سُلیمانس زِ یہِ چُھہ تُہٕندِس دِلس مَنٛز، تہٕ ژے چُھکھ نہٕ دولت، دولت، یا عزت، تہٕ دُشمن ہٕنزِ زُوٕ، تہٕ نہ چُھکھ وُنیُک تام زیچھر وٲنسہٕ منگمُت۔ مگر کورُن پننہِ خٲطرٕ حکمت تہٕ علم، یُتھ ژٕ میانین لوکن ہُند فیصلہ کٔرِتھ، یِمن پیٹھ مے ژے بادشاہ بنوو۔\n12. حکمت تہٕ علم چُھ ژے عطا کرنہٕ آمُت۔ تہٕ بہٕ دِیہ ژے دولت، دولت، تہٕ عزت، یُتھ زن نہٕ بادشاہن منز کٲنسہ تہِ آسہِ یُس ژے برونہہ آسہِ، تہٕ نہ آسہِ تۅہہِ پتہٕ یِتھُے کانہہ تہِ۔\n13.\\tپَتہٕ آو سُلیمان تتھ تھدِ مقامس پیٹھ یُس گبیونس مَنٛز یروشلم کُن اوس، یُس جماعت کِس خیمہ برونہہ کُن اوس، تہٕ کورُن اسرائیلس پیٹھ حکومت۔\n14. تہٕ سُلیمانن کٔر رتھٕ تہٕ گُرۍ سوارِ جمع تہٕ أمِس نِش ٲسۍ اکھ ساس ژور ہتھ رتھ تہٕ باہ ساس گُرۍ سوار، یِم تٔمۍ رتھن ہٕندِس شہرس مَنٛز تہٕ بادشاہس سٍتـ̡ یروشلمس مَنٛز تھوو۔\n15.\\tتہٕ بادشاہن بنوو یروشلمس مَنٛز رۄپہٕ تہٕ سۄن، تہٕ دیودار کُلۍ بنوو تِم کُلۍ یِم وادی مَنٛز کثرت خٲطرٕ چھِ۔ {بنیومُت: ہیب۔ دِنہٕ آمُت}\n16.\\tتہٕ سُلیمانن کٔرِن مصرہٕ منزٕ گُرِ تہٕ کُن یار: بادشاہ سٕندِس سوداگرن دِژ کُنہِ قٕمتس پیٹھ کُنہِ کُنہِ سوت ۔ {سلیمان...: ہیب۔ گُرٮ۪ن ہُند نیرُن یُس سُلیمان سُند اوس}\n17.\\tتہٕ تِمو أنِتھ مصرہٕ منزٕ شیہ ہتھ رۄپہٕ ہُند اکھ رتھ تہٕ ہتھ پنژاہ خٲطرٕ اکھ گُر، تہٕ یِتھٕ پٲٹھۍ أنِکھ تِمو حِطین ہٕندٮ۪ن سارنٕے بادشاہن تہٕ شام کین بادشاہن ہٕندِ خٲطرٕ تہٕ تِمن ہٕندِ ذٔریعہٕ گُرۍ۔ {مطلب: ہیب۔ اتھہٕ}","1. تہٕ سُلیمانن کوٚر خداوند سٕندِ ناوٕ خٲطرٕ اکھ مکانہٕ تہٕ پننہِ بادشٲہی خٲطرٕ اکھ مکانہٕ بناونُک ارادٕ۔\n2. تہٕ سُلیمانن ووٚن تریہ تہٕ داہ ساس نفر بوج تُلنہٕ خٲطرٕ، تہٕ ژور ساس ساس پہاڑس منز ژٹنہٕ خٲطرٕ، تہٕ تریہ ساس شیہ ہتھ تِمن ہٕنز نگرٲنی کرنہٕ خٲطرٕ۔\n3. تہٕ سُلیمانن سوٗز صور کِس بادشاہ حُرامس نِش، یِتھ کٔنۍ ژے میٲنِس مٲلِس سٍتـ̡ {حُرم: یا، ہیرم}\n4. وُچھِو بہٕ خداوند پننِس خدایہ سٕندِس ناوٕ خٲطرٕ اکھ مکانہٕ بناوان، یُس أمِس برونہہ کُن مٔدٕر اگربتی زالنہٕ خٲطرٕ، تہٕ مُسلسل روٹی دِنہٕ خٲطرٕ، تہٕ صُبح تہٕ شامَس دۅہہٕ، نوِ زوٗنہٕ دِنہٕ خٲطرٕ، تہٕ خداوند سٕندِ خدایہ سٕندِس مقدس تہوارس پیٹھ۔ یہِ چُھ اِسرٲیلِس خٲطرٕ ہمیشہٕ خٲطرٕ اَکھ آرڈیننس۔ {مٔٹھۍ...: ہیب۔ مسالہٕ ہُند اگربُب}\n5. تہٕ یُس مکانہ میہ تعمیر کران چھُ، سُہ چُھ عظیم سٍتـ̡ سارِنٕے دیوتاہن پیٹھ۔\n6. مگر کُس ہیکہِ تس مکانہ بنٲوِتھ، یہ وچھتھ زِ آسمانس تہ آسمانس منز ہیکہِ نہ تس رٔٹتھ۔ بہٕ کُس چُھس تٔمِس مکانہٕ بناوُن، صرف أمِس برونہہ کُن قربانی زالنہٕ خٲطرٕ؟ {قٲبل: ہیب۔ چُھ برقرار تھوومُت، یا طاقت حٲصل کٔرمٕژ}\n7. تێمہِ کِنۍ سوز میہ اکھ چالاک انسان یُس سۄنہٕ سٍتـ̡ تہٕ رۄپہٕ سٍتـ̡ تہٕ ششتٕرَس مَنٛز تہٕ ششتٕرَس مَنٛز تہٕ جامنی تہٕ سرخ تہٕ نیلِس مَنٛز کٲم کٔرِتھ تہٕ یُس یہوداہ تہٕ یروشلمس مَنٛز میہ سٍتـ̡ دِنہٕ آمُت چُھ، یُس میٲنس مٲلہِ داؤدس مَنٛز دِژمُت اوس۔ {قبر کُن: ہیب۔ قبر کِس گریونگس تام}\n8.\\tلبنان منزٕ سوز مے دیودار کُلۍ، فر کُلۍ تہٕ الگم کُلۍ تہِ، کیازِ بہٕ چھُس پتاہ زِ تہند خادم ہیکن لبنانس منز لٔکر ژٹنس منز مہارت حٲصل کٔرِتھ۔ تہٕ وچھ، میٲنۍ خادم گژھن تہندٮ۪ن خادمَن سٍتۍ، {الگم: یتھ المُگِم تہِ ونان چھِ}\n9.\\tیُس مکانہ بہٕ بناوُن چُھس تہٕ یُس مکانہٕ بناوُن چُھس تہِ آسہِ، سُہ آسہِ حیرت انگیز عظیم۔ {شاندار...: ہیب۔ عظیم تہٕ شاندار}\n10.\\tتہٕ وُچھ بہٕ دِیہ پننین خادمَن یِم لٔکٕر ژٹان چھِ، وُہ ساس پیمانہٕ کٕنُک تہٕ وُہ ساس پیمانہٕ شراب، تہٕ وُہ ساس باتھ شراب، تہٕ وُہ ساس باتھ تیل۔\n11.\\tتیلہِ دیُت صور کِس بادشاہ حُرامَن لیکھِتھ جواب، یُس تٔمۍ سُلیمانس سوزمُت، تِکیازِ خداوند چُھ پننین لوکن سٍتـ̡ محبت کٔرمٕژ، تٔمۍ بنوو تِمن پیٹھ بادشاہ۔\n12.\\tحُرامن ووٚن بییہِ زِ بابرکت آسُن اسرٲیلُک خدا، یٔمۍ اسمانس تہٕ زمینہٕ بنوو، یٔمۍ داؤد بادشاہس اکھ عقلمند نیچو دِژمُت، یُس عقلمندی تہٕ سمجھ سٍتـ̡ دِژمُت چُھ، یُس خداوند سٕندِ خٲطرٕ اکھ گرٕ تہٕ تٔمۍ سٕنزِ بادشاہی خٲطرٕ اکھ مکانہٕ تعمیر کرِ۔ {enddued...: Heb. سمجھداری تہٕ سمجھ زانن}\n13.\\tتہٕ وۅنۍ چھُ مے سوزمُت اکھ چالاک انسان، یُس میٲنس مٲلہِ سُند حُرم سُند سمجُن آسہِ،\n14.\\tدان سٕنزِ کورِ ہٕنزِ زنانہِ ہُند نیٚچُو، تہٕ تٔمۍ سُند مول اوس صورُک مرد، سۄنہٕ سٍتـ̡ تہٕ رۄپہٕ سٍتـ̡ ، پیتلَس منز، ششتٕرَس منز، کنن منز، تہٕ لٔکرِس منز، واگن رنگس منز، نیوٗل رنگس منز، تہٕ باریک کُن تہٕ سرخ رنگس منز۔ تہٕ کُنہِ تہِ قٕسمٕچ کُنہِ تہِ کُنہِ تہِ چال ژھانڈنہٕ خٲطرٕ، تہٕ پرٮ۪تھ کانہہ چال ژھانڈنہٕ خٲطرٕ یُس أمِس دِنہٕ یُن، تہٕ میٲنِس مٲلِس مٲلِس داؤد سٕندِس چالاک نفرن سٍتۍ۔\n15.\\tتێلہِ گۆو کٕنُک، جو، تیٖل تہٕ شراب، یُس میانہِ مالہِ ہُند کتھ چُھ کٔرمٕژ، سُہ سوزُن پننین خادمَن نِش۔\n16. تہٕ أسۍ ژٔٹِو لبنان منزٕ لٔکٕر ژٹنہٕ، یوتاہ ژےٚ ضروُرت آسہِ، تہٕ أسۍ اَنِو سمندرٕ کِنۍ ژےٚ نِش یوپا تام۔ تہٕ تُہۍ نِو یہِ یروشلمس تام۔ {یوتاہ یوتا...: حیب حسب تمام ضروریات} {جوپا: ہیب۔ جافو}\n17.\\tتہٕ سُلیمانن کٔر تِمن سارِنٕے اجنبی لوکن ہُند گنزراونہٕ یُس اسرٲیلِس مَنٛز اوس، یُس تٔمۍ سٕندِس مٲلہِ داؤدس شُمار اوس کوٚرمُت۔ تہٕ تِم آیہ اکھ ہتھ پنژاہ ساس تریہ ساس شیہ ہتھ لبنہٕ۔ {اجنبی: ہیب۔ مرد دی اجنبی}\n18.\\tتہٕ تمٔۍ مقرر کٔرِن تِمو منزٕ تریہ ساس تہٕ داہ ساس بوج تُلنہٕ خٲطرٕ، تہٕ ژور ساس ساس تہٕ تریہ ہتھ نگران۔","1. پتہٕ کٔر سُلیمانن موریاہ کِس پہاڑس مَنٛز یروشلمس مَنٛز خداوند سُند گرٕ تعمیر کرُن، یتہِ {خداوند داؤدٕ سٕندِس مٲلِس سٍتـ̡ ظٲہر گوو، تتھ جایہِ یُس داؤد اورنان جیبوسی کِس تھریشنگ فلورس مَنٛز تیار کورمُت اوس۔ {کتہِ...: یا، یُس ڈیوڈ سندس مٲلس اوس وُچھنہٕ آمُت} {اورنان: تہِ ونان چھِ، ارونہ}\n2. تہٕ تٔمۍ کٔر دٔیمہِ ریتہٕ کِس دٔیمِس دۅہس منز، پننہِ دورِ حکومتہٕ کِس ژوٗرِمِس ؤریس مَنٛز تعمیر کرُن شروع۔\n3.\\tوۅنۍ چھہِ یِم چیز یِمن منز سُلیمانس خدایہ سُند گرٕ بناونُک حکم اوس دِنہٕ آمُت۔ گوڑنچہ پیمائش پتہٕ اوس کیوبٹس سۭتۍ زیچھر تریہ کیوبٹ، تہٕ کھجر اوس وُہ کیوبٹ۔ {ہدایت: ہیب۔ قٲئم کرنہٕ آمُت}\n4.\\tتہٕ یُس پورچ {مکانہٕ} برونہہ کُن اوس، امیک زیچھر اوس مکانہ کس کھجرس مطٲبق، وُہ کیوبِٹ، تہٕ تھزر اوس اکھ ہتھ تہٕ وُہ: تہٕ تٔمۍ اوس اتھ اندر خالص سۄنہٕ سٍتۍ ؤلتھ۔\n5.\\tتہٕ بٔڈِس مکانس سٍتـ̡ تٔمۍ کٔر فر کُلِس سٍتـ̡ ، یُس تٔمِس سٍتـ̡ لٔگِتھ تہٕ اَ\n6.\\tتہٕ أمۍ کٔر گَرٕ خوبصوٗرتی خٲطرٕ قیمتی پتھرو سۭتۍ سجاوُن: تہٕ سۄنہٕ اوس پرویم سُنٛد سۄن۔ {گارنش: ہیب۔ کور کٔرِتھ}\n7.\\tتٔمۍ کٔر گرٕ، بیم، کھورِ تہٕ دیوار تہٕ تِمن ہٕندِس دروازس تہٕ سۄنہٕ سٍتـ̡ تہٕ دیوارن پیٹھ قبر کرُن۔\n8.\\tتہٕ تٔمۍ بنوو سارِوٕے کھۄتہٕ مقدس مکانہٕ، ییٚمیُک زیچھر مکانہٕ کہِ کھجرٕ مُطٲبق اوس وُہ کیوبِٹ، تہٕ اَتھ ہُند کھجر اوس وُہ کیوبِٹ۔\n9.\\tکیلن ہند وزن اوس پنژاہ شیکل سون۔ تہٕ تٔمۍ کٔر ہیٚرمِس کمرس سۄنہٕ سٍتۍ ؤلِتھ۔\n10.\\tتہٕ مقدس گرس منز بنوو تٔمۍ زٕ کرُبِم شکلہِ ہٕنز کٲم تہٕ تِمن پیٹھ سۄنہٕ سٍتـ̡ سجٲوِتھ۔ {تصویر...: یا، (یتھ کٔنۍ کینہہ سوچان چھہِ) متحرک کامہِ}\n11.\\tتہٕ کروبن ہندۍ پکھہ ٲسۍ وُہ کیوبٹ زیوٹھ: اکھ پکھہ اوس پانژھ کیوبٹ، یُس مکانہ کس دیوارس تام واتان اوس، تہ بیاکھ پکھہ اوس پانژھ کیوبِٹ، یُس بییِس کربس ہندس پکھس تام وٲتِتھ۔\n12.\\tتہٕ بییِس کرُبُک {اَکھ} پکھہٕ {اوس} پانژھ کیوبِٹ، یُس مکانہٕ کِس دیوارس تام وٲتِتھ: تہٕ بیٛاکھ پَکھہٕ {اوس} پانژھ کیوبِٹ {تہ}، یُس بییِس کروبس سٕندِس پکھس سٍتۍ رلان اوس۔\n13.\\tیِمن کرُبن ہٕندِ پکھہٕ پھٔہلِتھ وُہن کیوبِٹَن تام تہٕ تِم ٲسۍ پننین کھۅرن پیٹھ کھڑا تہٕ تِمن ہٕندِس بُتھِس ٲس أنٛدرِم کُن۔ {اندرم: یا، گرس کُن}\n14.\\tتہٕ تٔمۍ بنوو نیوٗل تہٕ واگن تہٕ سرخ تہٕ عمدہ کُن تہٕ اَتھ پیٹھ بنوُن کروبیم۔ {wrought: Heb. کھسُن}\n15.\\tامہ علاوہ بنوو گرس برونہہ کنہِ ترہ پانژہ ہاتھ تھدِ تھدِ تھوٚد تہ یُس چیپٹر یُس پریتھ کُنہِ تھزرس پیٹھ اوس، پانژھ کیوبِٹ اوس۔ {تھزر: ہیب۔ زیٹھ}\n16.\\tتہٕ تٔمۍ بَنوو زنجیر، {یِتھ} نَرس مَنٛز، تہٕ تھووُن تھمن ہٕندِس کلَس پیٹھ۔ تہٕ بنٲوِن ہتھ انار، تہٕ تھووُن زنجیرن پیٹھ۔\n17. تہٕ تٔمۍ تھوٚد مندرس برونہہ کُن تھم، اکھ دچھنہِ طرفہٕ تہٕ بیاکھ کھوورِ طرفہٕ۔ تہٕ وونُن دٔچھنِس اتھس پیٹھ یُس ناو جاچن، تہٕ کھوورِ اتھس پیٹھ اوس تٔمِس ناو بوز۔ {جاچین: یعنی سُہ کرِ قٲیم} {بوز: یعنی اتھ منز چھہ طاقت}","1. امہ علاوہ بنوو تٔمۍ پیتلُک اکھ قربان گاہ، زیچھر وُہ کیوبِٹ، تہٕ کھجر وُہ کیوبٹ تہٕ تھزرس منز داہ کیوبِٹ۔\n2.\\tامہ علاوہ بنوو تمۍ دہن کیوبٹن ہند اکھ پگلہِ سمندر، یُس کمپسس منز گول تہ پانژھ کیوبٹ تھزرس پیٹھ اوس۔ تہٕ ترہن کیوبٹن ہٕنٛز اکھ لٲن ٲس اتھ اندۍ اندۍ اندۍ گھیران۔ {پیٹھ...: ہیب۔ تٔمۍ سٕندِ دٔرِ پیٹھٕ تٔمۍ سٕندِس دٔرِس تام}\n3.\\tتہ اتھ تلہ کنہِ اوس بیلن ہنز تشبیہ، یمۍ اتھ اندۍ بیلن ہٕنز زٕ قطارٕ آیہ کاسٹ کرنہٕ، ییٚلہ یہ کاسٹ آو کرنہٕ۔\n4.\\tیہ کھڑا باہ بیلن پیٹھ، تریہ شمالس کُن تہ تریہ مغرب کُن تہ تریہ ٲسۍ جنوبس کُن تہ تریہ مشرقس کُن نظر۔\n5.\\tتہ امیک موٚٹ اوس اتھہ کھجر، تہ امیک دوٚر پیالہ ہندِ کامہِ ہندۍ پاٹھۍ یتھ منز لِلہِ ہندۍ پوش ٲسۍ۔ {تہٕ} أمِس آو ترے ساس باتھ کرنہٕ۔ {پوشن سۭتۍ...: یا، لِلی فلاور ہٕندۍ پٲٹھۍ}\n6.\\tتِمو کٔرِن دٔچِھنہِ اتھس پانٛژھ تہٕ کھوورِ طرفہٕ پانژھ یِمن منز چھلنہٕ خٲطرٕ، یِتھۍ چیز یِم تِمن منز چھلنہٕ خٲطرٕ دِنہٕ آمٕتۍ ٲسۍ۔ مگر سمندرٕ اوس پادٕرین ہٕندِ خٲطرٕ واش کرنہٕ خٲطرٕ۔ {یتھہ پاٹھۍ...: ہیب۔ دزنہٕ نذرانہٕ ہٕنٛز کٲم}\n7. تہٕ تٔمۍ بنٲو تِمن ہٕنزِ شکلہِ مُطٲبق سۄنہٕ سٕندِ داہ شمعہٕ، تہٕ تھٲوِن مندرس مَنٛز، پانژھ دٔچھنِس اتھس تہٕ پانژھ کھوورِ طرفہٕ۔\n8.\\tتٔمۍ بنٲوۍ داہ میز تہِ، تہٕ تھووُن مندرس مَنٛز، پانژھ دٔچھنِس طرفہٕ تہٕ پانژھ کھوورِ طرفہٕ۔ تہٕ تٔمۍ بنٲو سۄنہٕ ہتھ بیسن۔ {بیسن: یا، پیالہٕ}\n9.\\tامہِ علاوٕ بنوو تٔمۍ پادٕرین ہُند صحن، تہٕ بٔڈ صحن تہٕ دربارٕکۍ دروازٕ، تہٕ یِمن ہٕندِس دروازٕ بَنووُن پیتلٕ سٍتۍ۔\n10. تہٕ تٔمۍ تھوو سمندرٕ مشرقی اندس کِس دچھنہِ طرفہٕ، جنوبس کُن۔\n11.\\tتہٕ حُرامَن بَنوو بانہٕ، بیلچہٕ تہٕ بیسن۔ تہٕ حُرام کٔر سُہ کٲم مُکمل یُس أمِس بادشاہ سُلیمان سٕندِ خٲطرٕ خدایہ سٕندِ گرٕ خٲطرٕ بناوُن اوس ۔ {بیسن: یا، پیالہٕ} {ختم: ہیب۔ مُکمل کَرنہٕ آمُت}\n12.\\t{وُچھُن}، زٕ تھَم تہٕ پومل، تہٕ چیپٹر {یِم ٲس} دۄن تھمن ہٕندِس پیٹھمِس پیٹھ، تہٕ دۅشوٕے گُلہٕ پوشہٕ یِم تھمَن ہٕندِس تھزرس پیٹھ ٲسۍ۔\n13.\\tدۅن گلدستن پیٹھ ژور ہتھ انار۔ پرتھ گلدستس پیٹھ ٲس دٲنچ زٕ قطار، تاکہ چیپٹرن ہنٛد زٕ پوملن کور کرنہٕ خٲطرٕ یم ستونن پیٹھ {ٲس}۔ {on: Heb. بُتھِس پیٹھ}\n14.\\tتٔمۍ بنوو اڈہ تہِ، تہٕ لاورَن بنوو اڈن پیٹھ۔ {لیورز: یا، کالڈرون}\n15.\\tاکھ سمندر، تہٕ اتھ تلہ کنہِ باہ بیل۔\n16.\\tبانہٕ تہٕ بیلچہٕ تہٕ ماز ہُک تہٕ تِہٕندِس سارِنٕے سازو سامان تہٕ تٔمۍ سٕندِس مٲلۍ سُلیمانس بادشاہ سُلیمانس خٲطرٕ چمکدار پیتل سٕندِ گرٕ خٲطرٕ۔ {روشن: ہیب۔ چمک، یا، ژھانڈنہٕ}\n17.\\tاردن کِس مٲدانس منز ترٲو بادشاہن یِم سوکوتھ تہٕ زرداتاہ کِس میژِ مٲدانس منز۔ {میژے...: ہیب۔ زٔمیٖنُک موٚٹ}\n18. یِتھٕ پٲٹھۍ بنوو سُلیمانن یِم سارِنٕے بانہٕ سٮ۪ٹھاہ کثرت سان، تکیازِ پیتلُک وزن ہیوٚک نہٕ لٔبِتھ۔\n19. تہٕ سُلیمانن بَنوو تِم سارِنٕے بانہٕ یِم خدایہِ سٕندِ گرٕ خٲطرٕ ٲسۍ، سۅنہٕ قربان گاہ تہٕ تِم میز یِمن پیٹھ شیو بریڈ ٲس تھاونہٕ آمٕژ۔\n20.\\tامہِ علاوہ چُھہ شمعدان پننین شمعن سٍتـ̡ زالنہٕ یُن، یُس خالص سۄنہٕ سٍتـ̡ دزنہٕ یُن۔\n21. تہٕ پوش، تہٕ چراغ، تہٕ ٹانگ، {بنیوو} سۄنہٕ، {تہٕ} سُہ کامل سۄن۔ {کامل...: ہیب۔ سۄنہٕ ہٕکۍ کمال}\n22.\\tتہٕ نِش تہٕ بیسن، تہٕ چمچ، تہٕ سنسر، خالص سۄنہٕ: تہٕ گرُک اژُن، اَمہ کِس اندرمِس دروازٕ تہٕ مندرٕکۍ دروازٕ، تہٕ سۄنہٕ سٕندِ۔ {بیسن: یا، پیالہٕ}","1. یِتھٕ پٲٹھۍ گٔیہِ سُلیمانن خداوند سٕندِ گرٕ خٲطرٕ سورُے کٲم مُکمل تہٕ سُلیمانن أنِن تِم چیز یِم أمۍ سٕندِس مٲلہِ داؤد سٕندِ خٲطرٕ وقف کٔرۍمٕتۍ۔ تہٕ رۄپہٕ، سۄن، تہٕ سٲری آلات، تھوو سُہ خدایہ سٕندِس گرٕ کِس خزانس مَنٛز۔\n2. اَمہِ پَتہٕ کٔر سُلیمانن اِسرٲیلٕکۍ زِٹھہٕ تہٕ قبیلن ہٕندِس سارِنٕے سردار، یُس بنی اِسرٲیلِیَن ہٕندِس مٲلِس سٍتـ̡ سردار اوس، یُس داؤد سٕندِس شہرس مَنٛز اَننہٕ خٲطرٕ، یُس صیہون چُھ۔\n3. اَمہِ مۄکھٕ گٔیہِ اِسرٲیلٕکۍ سٲری مرد بادشاہس نِش یُس سٔتِمِس رٮ۪تس مَنٛز اوس۔\n4. تہٕ اسرائیلٕکۍ سٲری بزرگ آیہ۔ تہٕ لیویو تُل صندوق۔\n5.\\tتہٕ تِمو اَنِتھ صندوق، تہٕ جمٲژ ہُند خیمہ تہٕ سارِنٕے مقدس بانہٕ یِم خیمہ خانس مَنٛز ٲسۍ، یِمو کٔر پادٕرۍ تہٕ لاویو تُلِتھ۔\n6.\\tبادشاہ سُلیمان، تہٕ اِسرٲیلٕچ سارِنٕے جماعت یِم أمِس سٍتـ̡ صندوقس برونہہ کنہِ جمع گٔیہِ، کٔرٕکھ دانٛد تہٕ بیل قربان، یِم نہٕ وَننہٕ یِوان تہٕ بٔڑِس سٍتـ̡ گنزراونہٕ آمٕتۍ۔\n7. تہٕ پادٕرۍ أنۍ خداوند سٕندِ عہد کِس صندوقس منز تٔمۍ سٕنزِ جایہ، گرٕ کِس اوریکلس تام، حتیٰ کہ کروبن ہٕندِس پکھس تل تہِ۔\n8.\\tتکیازِ کرُبِمو پھٔہلٲوِتھ صندوقہٕ کِس جایہِ پَکھہٕ تہٕ کرُبِمو کٔر صندوق تہٕ اَمہ کِس ہیرِ کُن لٔگِتھ۔\n9.\\tتہٕ تِمو کٔڈِتھ لٔگِتھ صندوقہٕ سٍتـ̡ وُچھنہٕ آمٕتـ̡ ۔ مگر تم ٲسۍ نہٕ نیبر وچھنہٕ آمٕتۍ۔ تہٕ از تام چُھ یہٕ موجود۔ {تتہِ...: یا، تِم چھِ تَتہِ}\n10.\\tصندوقس منز اوس نہٕ تِمن دۅن میزن علاوٕ کینہہ تہِ یُس موسىٰ ہن حوربس مَنٛز تھوومُت اوس، ییلہ خداوند بنی اسرائیل سٍتـ̡ {اکھ معاہد} کورمُت، ییلہ تِم مصرہٕ منزٕ نیبر آو۔ {ییلہ خداوند: یا، کتہِ، وغیرہ}\n11.\\tتہٕ سپُد ییلہ پادٕرۍ مقدس {جایہ} منزٕ نیبر نیرِتھ: (تکیازِ سارِنٕے پادٕرۍ {یِم موجود} ٲسٕکھ پاک کرنہٕ آمٕتۍ، {تہٕ} اوس نہٕ {پتہٕ} انتظار کٔرِتھ: {موجود: حب۔ لٔب}\n12.\\tتہِ ٲسۍ لاوی (یِمَن) گٮ۪وَن وٲلۍ، یِم سٲری آساف، ہیمانٕکۍ، یہدوتونٕکۍ تہٕ پننین نیچوٮ۪ن تہٕ بٲے سٍتۍ، سفید کُن لٲگِتھ، تہٕ تِمن سٍتـ̡ ٲسۍ ہتھ وُہ پادٕرۍ بٔرِتھ قربان گاہ کِس مشرقی اندس پیٹھ کھڑا تہٕ تِمن سٍتـ̡ ہتھ وُہ پادٕرۍ ٲسۍ بُرٕ وایِتھ:)\n13.\\tیہ سپد تہِ یُتھ زن بُرِ تہٕ گیون وٲلِس اَکہٕ وِزِ اَکھ آواز بوزنہٕ یِنہٕ خٲطرٕ تہٕ خدایہِ سُند حمد تہٕ شُکرٕ ادا کرنہٕ خٲطرٕ بوزنہٕ یِنہٕ خٲطرٕ۔ تہٕ ییلہ تِمو تُلِتھ تُلِتھ تہٕ تِمو کٔرِکھ بُرِ سٕندِ تعریف، {سُہ چُھ} اصل۔ تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ چُھہ ہمیشہٕ سٍتـ̡ بٔرِتھ {تۯێم} یێلہِ گَرٕ سٍتـ̡ بٔرِتھ {یێلہِ} چُھہ خداوند سُند گرٕ تہِ۔\n14.\\tیێلہِ ہیوٚک نہٕ پادٕرۍ اوٚبرٕ سٍتـ̡ خدمت کرنہٕ خٲطرٕ کھڑا گٔژھِتھ: کیازِ خداوند سٕندِ جلال سٍتـ̡ اوس خدایہ سُند گرٕ بٔرِتھ بٔرِتھ۔","1.\\tپتہٕ ووٚن سُلیمان، خداوند چُھ ووٚنمُت زِ سُہ روزِ گٔنِس گٔنِس گٔنِس اندِپِس مَنٛز روزُن۔\n2. مگر مے بنوو چانہِ خٲطرٕ اکھ مکانہٕ تہٕ تۅہہِ ہمیشہٕ خٲطرٕ روزنٕچ جاے۔\n3. تہٕ بادشاہن پھیُر پَنُن بُتھ، تہٕ دِتُن سارِنٕے اسرٲیلٕچ جماعت دُبارٕ۔\n4.\\tتہٕ وۆنُن خداوند اسرٲیلُک خدا، یُس پننیو اتھو سٍتـ̡ پورٕ کورمُت یُس تٔمۍ میٲنِس مٲلِس داؤدس سٍتـ̡ وونُن چُھ،\n5.\\tییمہِ دۅہہ میہ پنٕنۍ قوم مصرہٕ منزٕ نیبر کڈنہٕ آمٕژ، میہ چُھہ نہٕ اسرٲیلٕکۍ سارِنٕے قبیلن مَنٛز کانہہ تہِ شہر ژارنہٕ یُتھ مَنٛز مکانہٕ بناونہٕ خٲطرٕ، یُتھ میون ناو آسہِ۔ نہ چُھس میہ کٲنسہ نفر پننین لوکن پیٹھ حکمران بننہٕ خٲطرٕ منتخب کرنہٕ۔\n6. مگر میہ چُھ یروشلم ژٲرمُت، یُتھ میون ناو آسہِ۔ تہٕ چُھکھ داؤد میانین لوکن پیٹھ اسرائیلس پیٹھ منتخب کوٚرمت۔\n7. وۅنۍ اوس میٲنس مٲلس داؤد سٕندِس دلس مَنٛز زِ سُہ کرِ اسرٲیلِکِس خدایہ سٕندِ ناوٕ خٲطرٕ اکھ مکانہٕ بَناوُن۔\n8. مگر خداوند ووٚن میٲنِس مٲلِس دٲید، یێلہِ تێلہِ چُھہ تۅہہِ دِلس مَنٛز میانہِ ناوٕ خٲطرٕ اکھ مکانہ بناوُن، تێہہ کٔر تۅہہ سٍتـ̡ تہندِس دِلس مَنٛز۔\n9.\\tتوتہِ گژھِ نہ مکانہ تعمیر کرُن۔ مگر تُہند نیچو یُس چانہِ کمرہ منزٕ نیرِ، سُہ بناوِ میانہِ ناوٕ خٲطرٕ مکانہٕ۔\n10. تێمہِ کِنۍ چُھس خداوند پنُن کلام پورٕ کورمُت، یُس تٔمۍ کُن کتھ کورمُت چُھ: کیازِ بہٕ چُھس پننِس مٲلس داؤد سٕندِس کمرس مَنٛز زندٕ گومُت، تہٕ بہٕ چُھس اسرٲیلِس کِس تختس پیٹھ بِہتھ بِہُن، یِتھہٕ کٔنۍ خداوند سُند وعدٕ کورمُت، تہٕ چُھس یہِ گرٕ بنوومُت یُس خداوند اسرٲیلُک خدا سٕندِ ناوٕ خٲطرٕ بنوومُت۔\n11. تہٕ اَتھ مَنٛز چُھس سُہ صندوق تھوومُت، یَتھ مَنٛز خداوند سُند عہد چُھ، یُس تٔمۍ بنی اسرٲیلِس سٍتـ̡ کورمُت اوس۔\n12. تہٕ سُہ اوس خداوند سٕندِس قربان گاہَس برونہہ کُن سارِنٕے اسرٲیلِچ جماعت ہٕندِس حٲضِری مَنٛز کھڑا تہٕ پَنُن اتھہٕ پھٔہلٲوِتھ ۔\n13.\\tتکیازِ سُلیمانن اوس پانژھ ہُند زیوٹھ تہٕ پانژھ ہُند کھوٚر تہٕ تریہ ہُند تھوٚد تہٕ کورُن دربارس مَنٛز تھووُن، تہٕ اتھ پیٹھ کھڑا تہٕ کۅٹھن پیٹھ بٔنِتھ بٔنِتھ کٔرِن اسرٲیلِچ سارِنٕے جمٲژ برونہہ کُن تہٕ پَنٕنۍ اتھہٕ پھٔہلٲوِتھ اسمانس کُن۔ امیک زیچھر وغیرہ}\n14. تہٕ وونُن، اے خداوند، اسرٲیلُک خدا، آسمانس مَنٛز تہٕ زمینس مَنٛز چُھہ نہٕ توے ہیوٗ کانہہ خدا۔ یُس عہد رژھراوان چُھ، تہٕ پننین بندن پیٹھ رحم کران چُھ، یُس تۅہہِ برونہہ کُن پَنُن دِل دِل دِوان چُھ:\n15.\\tژے یُس پننِس خادم ڈیوڈس سٍتـ̡ پننِس مٲلس سٍتـ̡ یُس وعدٕ کورمُت چُھ، سُہ چُھہ تٔمِس سٍتـ̡ پورٕ کورمُت۔ تہٕ کٔرٕن پننہِ ٲسس سٍتۍ، تہٕ کورُن پننہِ اتھہٕ سٍتـ̡ پورٕ، یِتھٕ پٲٹھۍ {یہ} از چُھ۔\n16. تێمہِ کِنۍ، اے خداوند، اسرٲیلُک خدا، پننِس بندس داؤد سٕندِس مٲلِس سٍتـ̡ یُس ژے أمِس وعدٕ کورمُت چُھ، یہِ ؤنِتھ زِ میانہِ نظرِ منز گژھِ نہٕ کانہہ تہِ انسان اسرٲیلِس کِس تختس پیٹھ بِہنہٕ خٲطرٕ۔ توتہِ یُتھ تہٕ تُہٕندِ شُرِ گژھن میانہِ قانونس مَنٛز پکنٕچ وتہِ ہُند خیال تھاوُن، یِتھ کٔنۍ ژے میانہِ برونہہ پکان چھِ۔ {تتہِ...: ہیب۔ اتہِ گژھِ نہ کانہہ انسان ژٹنہٕ یُن}\n17.\\tوُن، اے خدایہِ اسرٲیلِکِس خدا، تێہُند کلام گژھہِ پَنٕنِس خادمَس داؤدِس سٍتـ̡ کتھ کرنہٕ آمُت۔\n18.\\tمگر کیا خدایہ روزِ زمینس پیٹھ انسانن سٍتـ̡ روزُن؟ وچھو، اسمانس تہٕ آسمانُک آسمانہٕ ہیکہِ نہٕ ژےٚ رٔٹِتھ۔ یہ مکانہ کوتاہ کم یُس میہ بنوومُت چھُ!\n19. تێمہِ مۅکھہٕ کٔرِو پننِس بندہ سٕنزِ دُعا تہٕ تٔمۍ سٕنزِ دُعا ہُند احترام یُس تُہٕندِس بُردٕ سٕندِس دُعا سٍتـ̡ چُھہ تۅہہِ برونہہ کُن دُعا کران چُھ:\n20.\\tیُتھ زن تۅہہ دۅہ راتس اتھ گرس پیٹھ یلہٕ روزُن، یتھ جایہ ژیہ وونمت چھُکھ زِ ژے کرِ پنُن ناو اتہِ تھاوُن۔ سُہ دُعا بوزُن یُس تُہند خادم یَتھ جایہِ کُن دُعا کران چُھ۔ {کُن...: یا، یَتھ جایہِ پیٹھ}\n21. تێمہِ کِنۍ بوزو پنہٕ نِس بندس تہٕ پننہِ قوم اسرٲیلٕچ دُعا، یُس تِم یَتھ جایہِ کُن کرِ، تہٕ بوزُن پنہٕ نِس مکانہٕ پیٹھ، {حتیٰ کہ} اسمانس پیٹھ۔ تہٕ ییلہ تہِ بوزو، معافی دِیُن۔ {بناو: ہیب۔ دُعا} {کُن...: یا، یَتھ جایہِ منز}\n22.\\tاگر کانہہ شخص پننِس ہمساین خلاف گناہ کرِ، تہٕ أمِس پیٹھ قَسم کرنہٕ ییہِ تہٕ تٔمِس سٍتـ̡ یێلہِ گَرِ مَنٛز تُہٕندِس قربان گاہَس برونہہ کُن ییہِ حلف کرنہٕ۔ {تہٕ اکھ حلف...: ہیب۔ تہٕ أمِس چھُ أمِس سُند حلف ضروُر}\n23. تیلہِ کرو اسمانس پیٹھٕ بوزو، تہٕ کرو پننین خدمتگارن ہُند فیصلہٕ، بدکارن ہُند بدلہٕ دِتھ تہٕ تٔمۍ سٕندِس کلس پیٹھ تٔمۍ سٕندِس وتہٕ سٍتـ̡ بدلہٕ دِتھ۔ تہٕ صالحن ہٕندِس راستبازس مُطٲبق دِنہٕ سٍتـ̡ تہٕ دِنہٕ سٍتـ̡ ۔\n24. تہٕ یێلہِ تُہٕندِس قومس دُشمن سٍتـ̡ بدتر کرنہٕ ییہِ، کیازِ تِمو چ تہٕ گژھِ واپس تہٕ تُہند ناو اقرار کرُن، تہٕ یَتھ گرس مَنٛز کرِ تۅہہِ برونہہ کُن دُعا تہٕ دُعا کرنہٕ۔ {بَے پُٹ...: یا، بَے سِمِٹَن} {منز: یا، کُن}\n25. تیلہِ کرو آسمانہٕ پیٹھٕ بوزو، تہٕ پننِس قومہٕ اسرٲیلُک گۅناہ معافی دِیُن، تہٕ تِم أنِو تِمن تہٕ تِمن ہٕندِس مٲلِس دِنہٕ آمٕژ زمینس کُن۔\n26.\\tییلہ اسمانس بند گژھہِ، تہٕ روٗد آسہِ نہٕ، کیازِ تِمو چُھہ توے سٍتـ̡ گۅناہ کورمُت۔ {توتہِ} اگر تِم یَتھ جایہِ کُن دُعا کَرن، تہٕ تُہُند ناو اقرار کَرن، تہٕ پنہٕ نِس گۅنہٕ نِش پتھ کُن، ییٚلہِ تُہۍ تِمن مُتٲثِر کٔرِو۔ {کُن...: یا، یَتھ جایہِ پیٹھ}\n27. تێمہِ پٲٹھـ̡ بوزو اسمانس پیٹھ، تہٕ پننین خدمتگارن تہٕ پننہِ قوم اسرائیلُک گۅناہ معاف، یێلہِ تێلہِ ژے تِمن اصل وتھ ہیچھناوٕن، یتھ مَنٛز تِم پَکُن پَکُن پَکُن۔ تہٕ تراوو پننہِ زمینس پیٹھ رود، یُس ژے پننین لوکن وراثتس خٲطرٕ دِژمُت چھُ۔\n28. اگر زمینس منز کمی آسہِ، اگر وبا آسہِ، اگر دھماکہٕ آسہِ، یا پھپھون، ٹِڈی یا کیٹرپلر۔ اگر تِہٕندِس دُشمن تِمن ہٕندِس سرزمینہٕ کِس شہرن منز محاصرٕ کٔرِ۔ یُس تہِ دگ یا کانہہ تہِ بیمار آسہِ: {شہرن منز...: ہیب۔ تہندِس دروازن ہٕندِس سرزمینس منز}\n29.\\t{پَتہٕ}کُس دُعا ییہِ کٲنسہِ انسانس سٍتـ̡ یا تہندِس سارِنٕے قومہٕ اِسرٲیلس سٍتـ̡ کُنہِ دُعا سٍتـ̡ یێلہِ پرٮ۪تھ کانہہ پنُن دُعا تہٕ پنُن غم زانہِ تہٕ یێلہِ یێلہِ پَنُن اَتھٕ پھٔہلاونہٕ ییہِ: {منز: یا، کُن} {کُن...: یا، یَتھ جایہِ پیٹھ}\n30. تیلہٕ بوز اسمانہٕ پیٹھٕ پنٕنـ̡ روزنٕچ جاے تہٕ معافی دِیُن، تہٕ کٔرِو پرٮ۪تھ أکِس انسانس تٔمۍ سٕندِس سارِنٕے طریقو مُطٲبِق، یٔمۍ سُند دِل ژے زانان چھُ۔ (تِکیازِ تُہۍ چھِو صرف انسانن ہٕندٮ۪ن شُرین ہٕندِس دِلس زانان:)\n31.\\tیُتھ تِم گژھن تۅہہِ کھوژِتھ، توٚت تام تِم تِمن زمینس مَنٛز روزان یُس ژے سانین آباؤ اجدادن دِژمُت چھُ۔ {واریاہ زیٹھ...: ہیب۔ سارِنٕے دۅہ یُس {زمینس منز: ہیب۔ زمینہٕ کس بُتھس پیٹھ}\n32.\\tیُس اجنبی شخصس متعلق، یُس نہٕ تُہٕندِس قومہٕ سٍتـ̡ چُھہ یُس نہٕ تُہٕندِس بٔڈِس ناوٕ سٍتـ̡ تہٕ تُہٕندِس بٔڈِس ناوٕ سٍتـ̡ تہٕ تُہٕندِس بٔڈِس نٔرِ سٍتـ̡ دوٗر مُلکہٕ سٍتـ̡ آمُت چُھ، تہٕ چُھہ تُہٕندِس بٔڈِس ناو اگر تِم یِن یِتھ گرس مَنٛز عبادت کَرٕن؛ {کُن...: یا، یَتھ جایہِ پیٹھ}\n33. تیلہِ بوزو اسمانہٕ پیٹھ، تہٕ پننہِ مکانہٕ پیٹھٕ تہِ کرُن، تہٕ یُس اجنبی ژے بلاوان چُھ، تِمن مُطٲبق کٔرِو یُس اجنبی ژےٚ بلاوان چُھ۔ یُتھ زِ زمینہِ ہٕندِس سارِنٕے لُکھ گژھن تُہند ناو زانن، تہٕ ژے کھوژُن، یِتھ کٔنۍ تُہٕندِس لوکَس سٍتـ̡ چُھہ تُہند ناو دِنہٕ آمُت۔ {یہ...: ہیب۔ تُہند ناو چُھ یتھ گرس پیٹھ وننہٕ یوان}\n34. یێلہِ تُہٕندِس دُشمن سٍتـ̡ جنگ کرنہٕ خٲطرٕ نیران یێلہِ تہٕ تِم چُھہ تۅہہِ سٍتـ̡ تُہٕندِس شہرس کُن دُعا کران یُس ژے ژٲرمُت چُھ، تہٕ یُس مکانہٕ یُس میہ تُہندِ ناوٕ خٲطرٕ بنوومُت چُھ،\n35. تیلہِ کرو آسمانہٕ پیٹھٕ تِہٕنزِ دُعا تہٕ دُعا بوزُن تہٕ تِہُند مقصد برقرار تھاوُن۔ {وجہ: یا، صحیح}\n36.\\tاگر تِم تۅہہِ سٍتـ̡ گناہ کٔرِتھ، تہٕ تِمن سٍتـ̡ چُھہ تِمن سٍتـ̡ ناراض تہٕ تِمن دُشمن برونہہ کُن دِیُو، تہٕ تِم کٔرِو یِمن دوٗر یا نزدیٖکی زمینس کُن نِنہٕ۔ {تِم چھِ یِم قٲد نِوان: حب۔ یِم یِم قٲد کران چھِ تِم نِوان چھِ}\n37.\\tتوتہِ یێلہِ تِم تِمن زمینس مَنٛز یێلہِ تِم قٲد کرنہٕ آمٕتۍ چھِ، تہٕ یێلہِ تِم پَنٕنِس قٲد کِس سرزمینس مَنٛز پھیران تہٕ دُعا کران چھِ، تہٕ وَنُن زِ أسـ̡ چُھ گۅناہ کورمُت، أسـ̡ چُھہ غلط کورمُت، تہٕ بدکار کٔرِمُت۔ {be-think...: Heb. تِہنٛدِس دِلس منٛز واپس انِو}\n38.\\tیێلہِ تِم پَنٕنـ̡ دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ تُہٕندِس سرزمینس مَنٛز واپس یِن، یێلہِ تِم قٲد کٔرِمٕتـ̡ تہٕ تِمن ہٕندِس مٲلِس سٍتـ̡ دِژمٕژ چھِ، تہٕ تتھ شہرس کُن یُس ژے ژٲرمُت چُھ، تہٕ تتھ مکانس کُن یُس میہ تُہندِ ناوٕ خٲطرٕ بنوومُت چُھ:\n39. تیلہِ بوزو اسمانہٕ پیٹھ، تہنزِ روزن جایہ پیٹھ، تہنز دعا تہٕ دُعا تہٕ تِہٕنزِ دُعا تہٕ تِہٕندِس مقصدس برقرار تھاوُن، تہٕ پننین لوکن کٔرِن معافی یِمو تۅہہِ سٍتـ̡ گۅناہ کورمُت۔ {وجہ: یا، صحیح}\n40.\\tوۅنۍ میانہِ خدایہ، بہٕ چُھس ژے التجا کٔرِتھ، چانۍ أچھ یلہٕ روزٕنۍ، تہٕ پَنٕنۍ کَن گژھہِ یَتھ جایہِ دُعاہس سٍتـ̡ توجہ دِنہٕ۔ {اُن...: ہیب۔ امہ جایہ چہ دعاہس تام}\n41. تێمہِ وۆنـ̡ وۅتھ، اے خداوند، پننہِ آرامٕچ جاے تہٕ پننہِ طاقتہٕ کِس صندوقس منز، اے خداوند خدایہ، گژھہِ پنٕنـ̡ پادٕرۍ نجات سٍتـ̡ لٔگِتھ تہٕ پۯاوٕنـ̡ نیکی سٍتـ̡ شاد گژھن۔\n42. اے خدایہ، پَنُن مسح کرنہٕ آمُت بُتھ نہٕ پھیُرُن، پنُن خادم داؤد سُند رحمتہٕ یاد تھاوُن۔","1. وُنہِ ییلہ سُلیمانن دُعا ختم کٔر، اسمانہٕ سٍتـ̡ ووت نار تہٕ دزنہٕ نذرانہ تہٕ قربانی کھٲلِتھ ۔ تہٕ خداوند سُند جلال گۆو گرس بٔرِتھ۔\n2. تہٕ پادٕرۍ ہیوٚک نہٕ خداوند سٕندِس گرس مَنٛز اژِتھ، تِکیازِ خداوند سٕندِ جلال سٍتـ̡ اوس خداوند سٕندِس گرس بٔرِتھ بٔرِتھ۔\n3. تہٕ یێلہِ سارِوٕے بنی اِسرٲیلِیو وُچھ نار کِتھہ پٲٹھۍ، تہٕ گرس پیٹھ خداوند سُند جلال وُچھ، تِمو کٔر پَنُن بُتھ پٲٹھـ̡ نمُن، تہٕ کٔرٕکھ خداوند سٕندِ حمد تہٕ وونُن، کیازِ سُہ چُھہ نیک ۔ تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ خٲطرٕ۔\n4. پتہٕ کٔر بادشاہ تہٕ سارِوٕے لُکھ خداوند سٕندِ برونہہ کُن قربانی۔\n5. تہٕ بادشاہ سُلیمانن کٔر وُہن زٕ ساس بیلن تہٕ اکھ ہتھ ساس دانٛدن ہٕنز قربانی۔ یِتھ کٔنۍ کٔر بادشاہ تہٕ سارِنٕے لوکو خدایہ سُند گرٕ وقف۔\n6. تہٕ پادٕرۍ ٲسۍ پننین دفترن پیٹھ پیاران: لاوی تہِ ٲسۍ خداوند سٕنزِ موسیقی ہٕندِس سازس سٍتۍ، یُس داؤد بادشاہن خداوند سٕنز تعریف کرنہٕ خٲطرٕ بنوومُت اوس، کیازِ تٔمۍ سٕنز رحمت چھے ہمیشہٕ خٲطرٕ روزان، یێلہِ داؤد تِہٕنزِ وزارت سٍتـ̡ تعریفن کٔر۔ تہٕ پادٕرۍ کٔر تِمن برونہہ کُن بُرٕ، تہٕ سارِوٕے اِسرٲیل کھڑا گٔیہِ۔ {بذریعہ تِہُند...: ہیب۔ تہندِ اتھہٕ سٍتۍ}\n7. امہِ علاوٕ کٔر سُلیمانن دربارس منز یُس خداوند سٕندِس گرس برونہہ کُن اوس، تکیازِ تتہِ اوس تٔمۍ دزنہٕ آمٕژ نذرانہ تہٕ امن ہٕنز چربی پیش کٔرمٕژ، تکیازِ یُس سُلیمانن اوس بنوومُت سُہ اوس نہٕ دزنہٕ آمٕژ نذرانہ تہٕ مازٕچ نذرانہ تہٕ چربی حٲصل کٔرِتھ۔\n8.\\tاَمی وِزِ سُلیمانن کٔر سَتھ دۅہہٕ تہٕ سارِنٕے اسرٲیلِس سٍتـ̡ ہمت کِس دٔریاوَس تام دٔرِتھ سٍتـ̡ دٔرِتھ دِنہٕ آمُت۔\n9. تہٕ ٲٹھمہِ دۅہہٕ کٔر تِمو اکھ سنجیدہ مجلس، تکیازِ تِمو تھوو قربان گاہُک وقف ستن دۅہن تہٕ سَتھ دۅہ۔ {اکھ سنجیدہ...: ہیب۔ اکھ پابندی}\n10. تہٕ سٔتِمہِ ریتہٕ کِس تریہ تہٕ وُہمہِ دۅہہٕ سوٗزۍ تٔمۍ لُکھ تِہندین خیمن مَنٛز، یُس خداوند داؤدس تہٕ سُلیمانس تہٕ اسرٲیلِس سٍتـ̡ ہٲومٕژ ٲس۔\n11. یِتھٕ پٲٹھـ̡ کٔر سُلیمانن خداوند سُند گرٕ تہٕ بادشاہ سُند گرٕ مُکمل تہٕ سُہ سورُے یُس سُلیمان سٕندِس دِلس مَنٛز آو، تہٕ یُس خداوند سٕندِس گرس مَنٛز تہٕ پننِس گرس مَنٛز بَناونہٕ خٲطرٕ آو، تٔمِس کٔر خوشحالی ہُند اثر۔\n12. تہٕ خداوند آو رٲژ سُلیمانس نِش ظٲہر تہٕ وونُن تٔمِس زِ مے چُھس تُہٕنز دُعا بوزمٕژ، تہٕ چُھس یہِ جاے پانس خٲطرٕ قربان کرنہٕ خٲطرٕ ژٲرمُت۔\n13.\\tاگر بہٕ آسمانس بند کرُن زِ روٗد گژھہِ نہ، یا اگر بہٕ ٹِڈین زمینہٕ کھٮ۪نُک حُکُم دِوان، یا اگر بہٕ پننین لوکن منز وبا سوزان چھُس۔\n14. یێلہِ میانہِ لُکھ یِم میانہِ ناوٕ سٍتـ̡ وننہٕ یوان چھِ، تێلہِ گژھن عاجزی تہٕ دُعا کٔرِن، تہٕ میانہِ بُتھ ژھارن، تہٕ پنہٕ نـ̡ بدکار وتہٕ نِش پھیرٕنـ̡ ۔ تیلہِ بوزٕ بہٕ آسمانہٕ پیٹھ، تہٕ تِہُند گۅناہ معاف، تہٕ کرٕ تِہٕنزِ زمینہِ شفا بخش۔ {کُس...: ہیب۔ ییٚمِس پٮ۪ٹھ میون ناو وننہٕ چُھ آمُت}\n15.\\tوۅنۍ گژھن میٲنۍ أچھ یلہٕ، تہٕ میٲنۍ کَن گژھن اتھ جایہِ دُعا سٍتـ̡ دِنہٕ آمٕژ۔ {اُن...: ہیب۔ امہ جایہ چہ دعاہس تام}\n16.\\tوُنـ̡ چُھہ مے یہِ گرٕ ژٲرمُت تہٕ پاکیزٕ کورمُت، یُتھ میون ناو ہمیشہٕ روزُن: تہٕ میٲنۍ أچھ تہٕ میون دِل روزِ ہمیشہٕ خٲطرٕ۔\n17.\\tتہٕ یێلہِ تہٕ ژے یێلہِ تێلہِ میانہِ برونہہ کُن پٔکِتھ، یێلہِ پٲٹھـ̡ تُہند مول پکان چُھ، تہٕ یُس میہ چُھہ تُہند حکم دِژمُت تِمن مُطٲبق کٔرِو تہٕ میٲنۍ قونونن تہٕ میانین فیصلن ہٕنز پاسداری کرٕنـ̡ ۔\n18. تیلہٕ بہٕ چُھس چانہِ بادشٲہی ہُند تخت قٲیم کٔرِتھ، یِتھ کٔنۍ مے پننِس مٲلِس سٍتـ̡ داؤدس سٍتـ̡ عہد کورمُت چُھ، تہٕ وَنُن چُھس نہٕ تُہٕندِس مٲلِس سٍتـ̡ کانہہ تہِ انسان روزُن اِسرٲیلـ̡ سٍتـ̡ حُکُمران بنہٕ۔ {تتہِ...: ہیب۔ ژیہ گژھہِ نہ ژٹنہِ}\n19. مگر یێلہِ ژے پتھ کُن پھیرِو، تہٕ میٲنۍ قونونن تہٕ میٲنۍ حُکمن ترٲوِو، یِم مے ژے برونہہ کُن مقرر کٔرۍمٕتۍ، تہٕ گژھِو باقین دیوتاہن ہٕنز عبادت تہٕ تِمن ہٕنز عبادت کٔرِو۔\n20. تیلہٕ کٔرٕ بہٕ تِم پننہِ زمینہٕ منزٕ موٗلہٕ سٍتـ̡ تُلِتھ یُس مے تِمن دِژمُت چُھ۔ تہٕ یہِ گرٕ یُس میہ پننہِ ناوٕ خٲطرٕ مقدس کورمُت چُھ، بہٕ کٔرٕ پننہِ نظرِ نِش کٔرِتھ، تہٕ بَناوٕ یہِ سارِنٕے قومن مَنٛز اکھ محاورٕ تہٕ ضمنی لفظ۔\n21. تہٕ یُس گرٕ یُس تھوٚد چُھ، یُس اَتھ نِش گزرن وٲلِس خٲطرٕ آسہِ حیران۔ یێلہِ سُہ وَنُن زِ خداوند کیازِ چُھ یَتھ زمینس تہٕ یتھ گرس سٍتـ̡ یِتھٕ پٲٹھۍ کورمُت؟\n22.\\tتہٕ یِہ گژھہِ جواب دِنہٕ، کیازِ تِمو ترٲو پننین آباؤ اجدادن ہُند خدا، یُس تِم مصر کہِ سرزمینہٕ منزٕ نیبر کٔرِتھ، تہٕ باقین دیوتاہن رٔٹِتھ تہٕ تِمن ہٕنز عبادت کٔرٕن، تہٕ تِمن ہٕنز خدمت کٔرٕن، تێمہِ کِنۍ چُھ تِمن سٍتـ̡ یہِ سورُے بُرٕ دِنہٕ آمُت۔","1. تہٕ وُہن ؤرین ہٕندِس ٲخرس پیٹھ سپُد، یتھ مَنٛز سُلیمانن خداوند سُند گرٕ تہٕ پنُن گرٕ بنوومُت،\n2. یِم شہر حُرام سُلیمانس بحال کٔرۍمٕتۍ، سُلیمانن بنوو تِم تہٕ بنی اسرٲیلِس کٔرِن اَتہِ بسنہٕ۔\n3.\\tتہٕ سُلیمان گۆو حمتزوبہ کُن تہٕ کوٚرُن اتھ خلاف غلبہٕ۔\n4.\\tتہٕ تٔمۍ بنوو بیابانن مَنٛز تدمور تہٕ سارِنٕے سٹور شہر، یِم تٔمۍ حمتس مَنٛز بنوومٕتۍ۔\n5.\\tامہ علاوہ بنوو تٔمۍ بِتھورُن تہٕ بیتھورون بٔنِتھ تہٕ دیوار، دروازٕ تہٕ سلاخہٕ سٍتـ̡ بٔنِتھ شہر بٔنِتھ ۔\n6. تہٕ بعلت، تہٕ سُلیمانس نِش سارِنٕے ذخیرٕ شہر، تہٕ سارِنٕے رتھَن ہٕندِ شہر، تہٕ گُرۍ سوارَن ہٕندِ شہر، تہٕ سُلیمان یِم سُلیمان یروشلمَس مَنٛز تہٕ لبنان تہٕ پَنٕنِس سارِنٕے سرزمینس مَنٛز تعمیر کرُن یژھان اوس۔ {یہ سورُے...: ہیب۔ سُلیمان سٕنز سورے خٲہش یُس سُہ بناوُن یژھان اوس}\n7. {یێلہِ} سارِنٕے لُکھ {یِم حِتی، امورِی، تہٕ پیرزی، تہٕ حِوِی، تہٕ یبوسی، یِم نہٕ اسرٲیلِس سٍتـ̡ ٲسۍ،\n8.\\tتِہندِ شُرۍ، یِم تِمن پتہٕ زمینس مَنٛز باقٕے ٲسۍ، یِم نہٕ بنی اسرٲیلِو کھٮ۪وان ٲسۍ، سُلیمانن کٔر تِمن از تام خراج دِنہٕ۔\n9.\\tمگر بنی اسرٲیلـ̡ سُلیمانن بنوو نہٕ پننہِ کامہِ خٲطرٕ کانہہ نوکر۔ مگر تم ٲسۍ جنگی نفر، تہٕ تٔمۍ سٕنٛدیٚن کپتانن ہٕنٛدۍ سردار، تہٕ تٔمۍ سٕنٛدیٚن رتھن تہٕ گُرۍ سوارن ہٕنٛدۍ کپتان۔\n10.\\tتہٕ یِم ٲسۍ بادشاہ سلیمان سٕندٮ۪ن افسرن ہٕندِ سردار، {حتیٰ کہ} زٕ ہتھ پنژاہ، یِم عوامس پیٹھ حُکوٗمت کران ٲسۍ۔\n11. تہٕ سُلیمانن واتنوو فرعون سٕنز کورِ داؤد شہرٕ منزٕ تتھ مکانس مَنٛز یُس تٔمۍ تٔمِس خٲطرٕ بنوومُت اوس، تکیازِ میانہِ زنانہٕ روزِ نہٕ اسرٲیلِک بادشاہ داؤد سٕندِس گرس مَنٛز، تکیازِ یِم جاے چھِ مُقدس، یَتھ مَنٛز خداوند سُند صندوق آمُت چھُ۔ {مقدس: ہیب۔ پاکیزگی}\n12. تێمہِ پَتہٕ کٔر سُلیمانن خداوند سٕندِس قربان گاہس پیٹھ دزنہٕ نذرانہ پیش یُس تٔمۍ دٲرِ برونہہ کُن بنوومُت اوس،\n13.\\tموسیٰ سٕندِس حُکمس مُطٲبق تہٕ نوِ زونہِ دۅہس مُطٲبق تہٕ وریس مَنٛز تریہ لٹہِ، خمیر روٚس روٹی ہٕندِس دعوتس منز، ہفتن ہٕندِس عیدس مَنٛز، تہٕ خیمہ خانن ہٕندِس دعوتس مَنٛز۔\n14.\\tتہٕ تٔمۍ کٔر پننِس مٲلہِ داؤد سٕندِ حُکمس مُطٲبق، پادٕرین ہٕنزِ خدمتہٕ خٲطرٕ تہٕ لاوی تہٕ پادٕرین ہٕنزِ خدمتہٕ خٲطرٕ مقرر کرنہٕ، یُس پرٮ۪تھ دۅہُک فرض اوس، یِتھ کٔنۍ زِ پرٮ۪تھ دۅہُک فرض اوس پادٕرین برونہہ کُن تعریف کرنہٕ تہٕ خدمت کرنہٕ خٲطرٕ۔ {تہِ اوس ڈیوڈ...: ہیب۔ یتھے پاٹھۍ اوس داؤد سُند حکم خدایہ سُند انسان}\n15.\\tتہٕ تِمو کٔر نہٕ بادشاہ سٕندِس حکمس سٍتـ̡ کُنہِ تہِ معاملس متعلق، یا خزانہٕ سٍتـ̡ کُنہِ تہِ معاملس متعلق۔\n16.\\tوۅنۍ ٲس سُلیمان سٕنز سورے کٲم خداوند سٕندِ گرٕچ بُنیاد تراونہٕ کِس دۅہس تام تیار کرنہٕ آمٕژ، یێلہِ تام یہِ مُکمل سپدِ۔ {توتہِ}خداوند سُند گرٕ گۆو کامل۔\n17. پتہٕ گۆو سلیمان ایزینگبر تہٕ ایلوتھس کُن، یُس ادوم کِس سرزمینس مَنٛز سمندرٕ کِس بٹھس پیٹھ اوس۔ {ایلوتھ: یتھ ایلاتھ تہِ ونان چھِ}\n18.\\tتہٕ حُرام سوٗز سُہ پننین خادمَن، جہازن تہٕ نوکروں ہٕندِ اتھہٕ سٍتـ̡ یِمن سمندرُک علم اوس۔ تہٕ تِم گٔیہِ سُلیمان سٕندِس نوکرَس سٍتـ̡ اوفیرس نِش تہٕ تتہِ نِکھ ژور ہتھ پنژاہ ٹیلنٹ سۄنہٕ، تہٕ أنِکھ بادشاہ سلیمانس نِش۔","1.\\tتہٕ ییلہ سُہ سُلیمانٕچ ملکہٕ سُلیمان سٕنز شہرت بوٗز، سُہ آیہِ سُلیمانس سٍتـ̡ سُلیمانس سٍتـ̡ س\n2. تہٕ سُلیمانن ووٚن أمِس پنٕنۍ سٲری سوال: تہٕ سُلیمانس نِش اوس نہٕ کانہہ تہِ ژوٗرِ روزان یُس نہٕ أمِس وَنُن۔\n3. تہٕ ییلہ شیبا ہٕچ ملکہِ سُلیمان سٕنز حکمت وُچھمٕژ تہٕ یُس مکانہٕ تٔمۍ بنوومُت اوس،\n4. تہٕ تٔمۍ سٕندِس دسترُک ماز، تہٕ تٔمۍ سٕندٮ۪ن خدمتگارن ہٕنز بِہنہٕ، تہٕ تٔمۍ سٕندٮ۪ن وزیرن ہٕنز حاضری، تہٕ تِہٕندِس لباس۔ تٔمۍ سٕندِ پیالہ تہٕ تِہٕندِ لباس۔ تہٕ تٔمۍ سُند کھسُن ییمہ سٍتـ̡ سُہ خداوند سٕندِس گرس مَنٛز ووت؛ تس منز اوس نہ بییہ کانہہ جذبہ۔ {کپ بیئررز: یا، بٹلرز}\n5. تہٕ تٔمۍ ووٚن بادشاہس {یہ} اکھ پوٚز خبر یُس میہ پننِس زمینس مَنٛز تُہنزِ اعمالن تہٕ تُہنزِ دانشمندی مُتلق بوزمُت: {رپورٹ: ہیب۔ لفظ} {اعمال: یا، اقوال}\n6.\\tبہٕ بہٕ اوسُس نہٕ تِہٕندِس کلامَس پیٹھ پژھ کٔرِتھ، یوٚت تام بہٕ آو، تہٕ میانہِ أچھن وُچھمُت تہٕ یُس میہ بوزمُت اوس، تِمن ہٕندِس کُنہِ کُنہِ تہِ وُچھمُت چھُ۔\n7. تُہٕندِس نفرس چھِ خۅش گٔژھِتھ تہٕ یِم تۅہہِ برونہہ کُن کھڑا روزان چھِ، تہٕ تُہٕنز حکمت بوزان چھِ۔\n8. خداوند چُھہ تُہند خدا، یُس ژے پنہٕ نِس تختس پیٹھ بِہاونہٕ خٲطرٕ خوش گوو، تہٕ خداوند سٕندِ خداہٕ سٕندِ خٲطرٕ بادشاہ بنُن، کیازِکہِ تُہند خدا اوس اسرٲیلِس محبت کران، تہٕ تِمن ہٕندِس ہمیشہٕ خٲطرٕ قٲیم کرنہٕ خٲطرٕ، تێلہِ بنووُن تِمن پیٹھ بادشاہ، یُس فیصلہ تہٕ انصاف کرنہٕ مۅکھہٕ بنووُن۔\n9. تہٕ تٔمۍ دِژ بادشاہس اکھ ہتھ وُہ ٹیلنٹ سۄن، تہٕ مسالہٕ واریاہ زیادٕ تہٕ قیمتی پتھر، تہٕ نہ اوس تِتھۍ مسالہٕ یُس شیبا ہٕچ ملکہٕ سُلیمانس بادشاہس دِیُت۔\n10.\\tتہٕ حُرامٕکۍ خادم تہٕ سُلیمان سٕندِ نوکر یِمو اوفیرس سٍتـ̡ سۄنہٕ أنِتھ، أنِن الگم کُلۍ تہٕ قیمتی پتھر۔ {الگم...: یتھ المگ ٹری تہِ ونان چھِ}\n11.\\tتہٕ بادشاہن بنوو خداوند سٕندِس گرس تہٕ بادشاہ سٕندِس محلس مَنٛز تہٕ گیون والٮ۪ن ہٕندِ خٲطرٕ ہارپ تہٕ زبور تہٕ یہوداہ کِس سرزمینس مَنٛز اوس نہٕ یِتھٕ وُچھنہٕ آمُت۔ {چھت: یا، ہیڑۍ: ہیب۔ شاہراہ}\n12.\\tتہٕ بادشاہ سُلیمانن دِژ شیبا ہٕنزِ ملکہِ سٲرۍسٕے خٲہش، یُس تٔمۍ بادشاہس نِش أنِمُت اوس۔ چنانچہ سۅ پھیرۍ تہ گٔیہِ پننہِ زمینہِ کُن، سۅ تہ تسند نوکر۔\n13.\\tسُہ وزن یُس أکِس ؤریس منز سلیمانس نِش آو سُہ اوس شیہ ہتھ تریہ تہٕ شیہ ٹیلنٹ سۄنہٕ۔\n14.\\tتمہِ علاوٕ یُس چیپمین تہٕ سوداگرن أنِتھ اوس۔ تہٕ عربٕکۍ سٲری بادشاہ تہٕ ملکٕکۍ گورنرن أنۍ سُلیمانس سۄن تہٕ رۄپھ۔ {گورنرز: یا، کیپٹن}\n15.\\tتہٕ بادشاہ سُلیمانن بنوو زٕ ہتھ نشانہٕ: شیہ ہتھ {شیکل} مارنہٕ آمُت سۄنہٕ أکِس نشانس کُن۔\n16.\\tتہٕ ترے ہتھ ڈھال {بنیومٕت} سۄنہٕ سٍتـ̡ ترے ہتھ سۄنہٕ سٍتـ̡ گٔیہِ أکِس ڈالس مَنٛز۔ تہٕ بادشاہن تھوو تم لبنان کِس جنگل کِس گرس منٛز۔\n17.\\tامہِ علاوٕ بنوو بادشاہن ہٕندِ دندن ہُند اکھ بوٚڈ تخت، تہٕ اتھ پیٹھ تھووُن خالص سۄنہٕ۔\n18.\\tتہٕ {اتہِ} تختس تام شیہ قدم ٲس، سۄنہٕ سٕندِس کھۅرن سٍتـ̡ {یُس} تختس سٍتـ̡ لٲگِتھ اوس، تہٕ بِہنہٕ چہ جایہِ ہٕندِس پریتھ طرفہٕ روزان اوس، تہٕ زٕ شیر ٲسۍ بِہنہٕ کِس جایہِ نِش کھڑا روزان: {Stays: Heb. اتھہٕ}\n19. تہٕ اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ شیٚن ہیرن پیٹھ باہ شیر کھڑا ۔ کُنہِ تہِ سلطنتس منز اوس نہٕ یِتھُے بناونہٕ آمُت۔\n20.\\tتہٕ بادشاہ سُلیمان سٕندِ سارِنٕے بانہٕ سٍتـ̡ یہ اوس نہٕ سلیمان سٕندِس زمانس منز کانہہ تہِ چیز حسابہٕ کرنہٕ آمُت۔ {خالص: ہیب۔ بند کرُن} {کانہہ تہِ اوس نہ رۅپہ: نتہ تمن منز اوس نہ کانہہ رۅپہ کٔرتھ}\n21.\\tکیازِ بادشاہ سٕندِ جہازٕ ٲسۍ حُرم سٕندٮ۪ن خادمن سٍتۍ ترشِش کُن گٔژھمٕتۍ: پریتھ تریہ ؤری پتہٕ ٲسۍ ترشِش سٕندِ جہازٕ سۄن، رۄپھ، ہٕندِ دند، تہٕ بندر تہٕ مور انان۔ {ہاتھی دندن: یا، ۂستین ہٕندِ دند}\n22.\\tتہٕ بادشاہ سُلیمانن کٔر زمینہٕ کین سارِنٕے بادشاہن دولت تہٕ دانشمندی سٍتـ̡ دِنہٕ۔\n23.\\tتہٕ زمینہٕ کِس سارِنٕے بادشاہو کٔر سُلیمان سٕنزِ حٲضِری ہٕنزِ حٲضِر، یُس خداین پننِس دِلس مَنٛز دِژمُت اوس۔\n24. تہٕ تِمو أنۍ پرٮ۪تھ أکِس شخصس پنُن تحفہٕ، رۄپہٕ ہٕندۍ بانہٕ، تہٕ سۄنہٕ سٕندِ بانہٕ، پلو، ہار تہٕ مصالحہٕ، گُرِ تہٕ خچر، ؤری پتہٕ ؤری۔\n25.\\tتہٕ سُلیمانس ٲسۍ گُرٮ۪ن تہٕ رتھن خٲطرٕ ژور ساس دُکان، تہٕ باہ ساس گُرۍ سوار۔ یُس تٔمۍ رتھ شہرن منٛز تہٕ یروشلمس منٛز بادشاہس سۭتۍ عطا کوٚر۔\n26. تہٕ تٔمۍ کٔر دریاو پیٹھٕ فلسطینن ہٕندِس سرزمینس تام تہٕ مصر کِس سرحدس تام سارنٕے بادشاہن پیٹھ حکومت۔ {دریاو: یعنی فرات }\n27.\\tتہٕ بادشاہن بنوو یروشلمس مَنٛز رۄپہٕ کٔنۍ تہٕ دِودار کُلۍ بَنوو سُہ کُلۍ یِم بٔنِم مٲدانن مَنٛز واریاہ زیادٕ چھِ۔ {رۄپہٕ رۄپہٕ: ہیب۔ رۄپہٕ دِیُت}\n28.\\tتہٕ تِمو أنۍ سُلیمانس نِش مصرٕ منزٕ تہٕ سارِوٕے زمینو منزٕ گُرۍ۔\n29.\\tوۅنۍ چھہ نہ سلیمان سٕندِ باقی اعمال گۅڈنچہ تہٕ ٲخری کتابہِ منز لیکھنہ آمٕتۍ، تہٕ احیجہ شِلونائی سٕنزِ پیشین گویی منز، تہٕ نیبت سٕندِس نیچوِس یروبعام سٕندِس وژنس مَنٛز چھُنہٕ لیکھنہٕ آمٕتۍ۔ {کتاب: ہیب۔ لفظ}\n30. تہٕ سُلیمانن کٔر یروشلمس مَنٛز سارِنٕے اسرٲیلِس مَنٛز ژتٲجی وُہٕرۍ۔\n31.\\tتہٕ سُلیمان گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ سُہ آو پننِس مٲلس داؤد سٕندِس شہرس مَنٛز دفن کرنہٕ۔","1.\\tتہٕ رحبعام گۆو شیکیمس کُن، تکیازِ سٲرۍسٕے اسرٲیلِس اوس أمِس بادشاہ بناونہٕ خٲطرٕ آمُت۔\n2. تہٕ سپُد یہِ سپدِتھ ییلہ نیبت سُند نیچو یربعام، یُس مصرس مَنٛز اوس، یُس سُہ سلیمان بادشاہ سٕندِ حٲضِری نِش ژوٚلمت اوس، بوز زِ یربعام آو مصرہٕ منزٕ واپس۔\n3. تہٕ تِمو سوٗزۍ تہٕ بُلوو۔ چنانچہ یربعام تہٕ سارِوٕے اِسرٲیلِس آو تہٕ وونُن رحبعامس سٍتـ̡ کتھ\n4. تێلہِ کٔر پننِس مٲلہِ سٕنزِ غٲلبٕچ غلامی تہٕ تٔمۍ سٕندِس گۄبٕرِ سٍتـ̡ یُس تٔمۍ اسہِ پیٹھ تھوومُت اوس، تہٕ أسۍ کٔرِو تۅہہِ ہٕنز خدمت۔\n5.\\tتہٕ تٔمۍ ووٚن تِمن ، تریہ دۅہہٕ پَتہٕ آو میہ نِش دُبارٕ۔ تہٕ لوٗکھ گٔیہِ روانہٕ۔\n6.\\tتہٕ بادشاہ رحبعام کٔر تِمن بُزرگَن سٍتـ̡ مشورٕ یُس سُلیمانس مٲلِس سُلیمانس برونہہ کُن کھڑا اوس، یہِ وونُن زِ ژے کیاہ مشورٕ دِیُت یێمہِ لُکہٕ سُند جواب دِنہٕ خٲطرٕ؟\n7. تہٕ تِمو کٔر أمِس سٍتـ̡ کتھ کرنہٕ، یێلہِ ژے یِمن لُکن سٍتـ̡ مہربان کٔرِو، تہٕ تِمن سٍتـ̡ رٔژ کتھ کٔرِو، تِم روزن ہمیشہٕ خٲطرٕ تُہٕندِس خادم۔\n8.\\tمگر تٔمۍ ترٲو سُہ مشورٕ یُس بُزرگَن أمِس دِژمُت اوس، تہٕ تِمن نوجوانَن سٍتۍ مشورٕ کٔرِتھ یِم أمِس برونہہ کنہِ کھڑا ٲسۍ۔\n9.\\tتہٕ تٔمۍ ووٚن تِمَن، تُہۍ کیا مشورٕ دِوان زِ أسۍ یِمن لُکن جواب دِتھ، یِمو مےٚ سٍتـ̡ کتھ کٔرمٕژ چھِ، یُس چانہِ مٲلہِ اسہِ پیٹھ تھوومُت اوس، سُہ کُنہِ حدس تام کم کرُن؟\n10.\\tتہٕ یِم نوجوان أمِس سٍتـ̡ پرورش کٔرۍمٕتۍ، تِمو کٔر أمِس سٍتـ̡ وَنُن، یِتھٕ پٲٹھـ̡ تہٕ یِمن لُکن ہُند جواب دِیُن تہٕ وَنُن زِ تێہٕندِس مٲلہِ سٍتـ̡ چُھہ سانہِ خٲطرٕ ہلکہٕ ہلکہٕ۔ یتھہ پاٹھۍ ونن تمن میون لۅکٹۍ {اونگجہ} آسہِ میٲنس مٲلہِ سٕنزِ کمرہ کھۅتہ زیادہ موٚٹ۔\n11.\\tییلہ میانہِ مٲلہِ ژے گۅب جولہٕ تھوو، بہٕ تراوٕ ژیہ ژۅنہِ ہٕندِس جوتس منز: میانہِ مٲلہِ دِژ ژےٚ کوڑو سٍتۍ، مگر بہٕ دِیہ ژیہ بچھو سٍتـ̡ سزا۔ {میون مول تھوو: ہیب۔ میون مول لیڈ}\n12. یێمہِ دۅہہ آو یربعام تہٕ سٲری لُکھ تریمہِ دۅہہ رحبعام کُن، یُتھ زن بادشاہن حکم دِیُت زِ تریمہِ دۅہہ آو میہ نِش۔\n13. تہٕ بادشاہن دیت تمن سختی سان جواب۔ تہٕ بادشاہ رہبعام ترٲو بُزرگَن ہُند مشورٕ،\n14.\\tتہٕ نوجوانَن ہٕندِ مشورٕ پتہٕ دیتُن تِمن جواب دِتھ زِ میانہِ مٲلہِ اوس تُہند جوُر گوٚب کوٚرمُت، مگر بہٕ کٔرٕ اتھ منز اضافہٕ: میانہِ مٲلہِ دِژ ژےٚ کوڑو سٍتۍ، مگر بہٕ کرٕ ژےٚ بچھو سٍتۍ سزا۔\n15.\\tیێلہِ کٔر نہٕ بادشاہن لوکن ہٕنز کتھ بوزنہٕ، تکیازِ یہِ مقصد اوس خدایہِ سُند، یُس خداوند پنُن کلام پورٕ کرُن، یُس تٔمۍ شیلونایہِ ہیجہ سٕندِ اتھہٕ سٍتـ̡ نیبت کِس نیچوِس یروبعام سٕندِس سٍتـ̡ کتھ کٔرِ۔\n16. تہٕ ییلہ سارِنٕے اسرٲیلَن وُچھ زِ بادشاہ چُھ نہٕ تِمن ہٕنز کتھ بوزن، لوکو دِژ بادشاہس جواب دِتھ زِ اسہِ کُس حصہٕ چُھ داؤدس مَنٛز۔ تہٕ یسیٰ سٕندِس نیچوِس مَنٛز چُھنہٕ اسہِ کانہہ وراثت: اے اسرٲیل، پرٮ۪تھ کانہہ نفر چُھہ پننین خیمن منز، اے اسرائیل: {تہٕ} وُن، ڈیوڈ، پنہٕ نِس گرس وچھُن۔ چنانچہ سارِوٕے اِسرٲیل گٔیہِ پننین خیمن منز۔\n17.\\tمگر یہوداہ کین شہرن مَنٛز روزن وٲلِس بنی اسرائیلس سٍتـ̡ کٔر رحبعام تمن پیٹھ حکومت۔\n18.\\tبادشاہ رہبعام سوٗز ہدورم یُس خراج دِنس پیٹھ اوس۔ تہٕ بنی اسرٲیلیو لگٲوۍ تس کنیو سٍتـ̡ کٔنہِ سٍتـ̡ سُہ مٔرِتھ۔ مگر بادشاہ رہبعام کٔر سُہ یروشلم کُن ژلنہٕ خٲطرٕ تیز رفتار۔ {میڈ سپیڈ: ہیب۔ پنُن پان کٔرُن مضبوط}\n19. تہٕ اسرائیلن کٔر از تام داؤد سٕندِس گرس خلاف بغاوت۔","1.\\tییلہ رحبعام یروشلم آو تٔمۍ کٔر یہوداہ تہٕ بنیامین سٕندِس گرس منزٕ اکھ لچھ ژٲرِتھ ژٲرِتھ {نفر}، یِم اسرٲیلِس خلاف لڑنہٕ خٲطرٕ جنگجو ٲسۍ، یُس سُہ دُبارٕ رہبعام کُن بادشاہت انِ۔\n2. مگر خداوند سُند کلام ووت خدایہ سٕندِس انسانس شمعیاہ ہس نِش یُس وَنُن چُھ،\n3. یہوداہ کِس بادشاہ سُلیمان سٕندِس نیچوِس رحبعام سٍتـ̡ تہٕ یہوداہ تہٕ بنیامین سٍتـ̡ کٔرِو سارنٕے اسرٲیلِس سٍتـ̡ کتھ کرنہٕ،\n4. خداوند چُھ یِتھٕ پٲٹھۍ ونان زِ تُہۍ گژھِو نہٕ ہیوٚر تہٕ نہ پننٮ۪ن باین سٍتـ̡ جنگ کٔرِتھ: پرٮ۪تھ أکِس نَفس پٔنِس گَرَس مَنٛز واپس، تِکیازِ یہِ کتھ چھِ میہ سٍتـ̡ کرنہٕ آمٕژ۔ تہٕ تِمو کٔر خداوند سٕندِ کلامٕچ فرمانبرداری، تہٕ گٔیہِ یربعام سٕندِس خلاف گژھنہٕ نِش واپس۔\n5. تہٕ رحبعام روٗد یروشلمس مَنٛز روزان، تہٕ بنوو یہوداہَس مَنٛز دفاع خٲطرٕ شہر۔\n6. تٔمۍ بنوو بیت اللحم، تہٕ ایٹم تہٕ ٹیکوا،\n7. تہٕ بیت زور، شوکو، تہٕ عدلم،\n8.\\tگاٹھ تہٕ مریشہ تہٕ زیپھ،\n9. تہٕ ادوریم تہٕ لاچیش تہٕ عزیقاہ،\n10.\\tزورہ تہٕ ایجالون تہٕ ہیبرون، یُس یہوداہ تہٕ بنیامین سٕندِس شہرس مَنٛز تار لٔگِتھ چھِ۔\n11.\\tتہٕ تٔمۍ کٔرِن مضبوط قلعہٕ مضبوط، تہٕ تِمن مَنٛز تھووُن کپتان، تہٕ تیٖل تہٕ شرابُک ذخیرٕ۔\n12.\\tتہٕ پرٮ۪تھ واریاہن شہرن مَنٛز تھووُن ڈھال تہٕ نیزٕ، تہٕ بنٲیِن یہوداہ تہٕ بنیامین پانس سٍتـ̡ واریاہ مضبوط۔\n13.\\tتہٕ پادٕرۍ تہٕ لاوی یُس سارِنٕے اسرٲیلِس مَنٛز ٲس، تِمو کٔر أمِس سٍتـ̡ {ریزورٹ...: ہیب۔ تمس کٔر پنن پان پیش}\n14.\\tکیازِ لاوی ترٲوۍ پنُن مضافاتی علاقہٕ تہٕ پنُن قبضہٕ، تہٕ آیہ یہوداہ تہٕ یروشلمس کُن، کیازِ یربعام تہٕ تٔمۍ سٕندٮ۪و نیچویو اوس تِم پادٕرۍ سُند عہدٕ خداوند سٕندِس عہدس پیٹھ پھٲلاونہٕ نِش کڈمُت۔\n15.\\tتہٕ تٔمۍ دِژ أمِس تھدٮ۪ن جاین تہٕ شیطانن خٲطرٕ تہٕ بَچھرٮ۪ن ہٕندِ خٲطرٕ پادٕرۍ مقرر کرنہٕ۔\n16.\\tتہٕ تِہندِ پَتہٕ سارِوٕے قبیلو منزٕ یِمو اسرٲیلُک خداوند خدایہِ سٕندِس خداہس سٍتـ̡ دِل دِنہٕ خٲطرٕ دِل دِنہٕ آمُت اوس، یێلہِ یُس پننین مٲلن ہٕندِس خداہس سٍتـ̡ قربانی دِنہٕ خٲطرٕ دِنہٕ آمُت۔\n17. یێمہِ پٲٹھـ̡ کٔر تِمو یہوداہ کِس بادشاہتس مضبوٗط، تہٕ بنووُن رحبعام سُلیمان سُند نیچو تریہ ؤری مضبوٗط۔\n18. تہٕ رہبعام نیو أمِس داؤد سٕندِس نیچوِس یرموتھ سٕنز کورِ مہلات، تہٕ یسیٰ سٕندِس نیچوِس الیاب سٕنز کورِ ابیحیل۔\n19.\\tأمِس کُس بچہٕ چھُ۔ عیسیٰ مسیح تہٕ شمریاہ تہٕ زحام۔\n20. تہٕ أمِس پَتہٕ رٔٹِو أمِس ابسالوم سٕنزِ کوٗر معچہ۔ ییمہ سٍتـ̡ أمِس ابیجاہ تہٕ عتایی تہٕ زیزا تہٕ شیلومِتھ دِنہٕ آمٕتۍ۔ {ماخہ: أمِس چھِ میکائیاہ، یُس یوریل سٕنز کوٗر تہِ ونان چھِ}\n21.\\tتہٕ رحبعام اوس ابسالوم سٕنزِ کورِ ماچہ سٕنزِ سارِنٕے زنانہٕ تہٕ تٔمۍ سٕنزِ لونڈین سٍتـ̡ محبت کران: (تکیازِ أمس رٔٹۍ ارداہ زنانہٕ تہٕ تریہ لونڈی۔ تہٕ زاے وُہ ٲٹھ نیچوۍ تہٕ تریہ کورِ۔\n22.\\tتہٕ رحبوامن بنوو ابیاہس ماچہ سُند نیچو سردار ، یُس پننین باین منز حکمران بنوو، تکیازِ تٔمۍ اوس سونچان زِ سُہ بَناوُن بادشاہ۔\n23. تہٕ تٔمۍ کٔر دانشمٲری سٍتـ̡ تہٕ پنٕنـ̡ سارِنٕے شُرِ یہوداہ تہٕ بنیامین کِس سارنٕے مُلکن مَنٛز پھٔہلِتھ تہٕ دِژٕن تِمن سٍتـ̡ وافر زیادٕ۔ تہٕ سُہ اوس واریہن زنانن ہٕنٛز خواہش۔ {واریاہ زنانہٕ: ہیب۔ زنانن ہُند اکھ بٔڑ}","1. تہٕ سپُد یہِ سپدُن، ییٚلہِ رحبوامن بادشٲہی قٲیم کٔر، تہٕ پنُن پان مضبوٗط کوٚرُن، تٔمۍ ترٛٲو خداوند سٕنز شریعت تہٕ سارِنٕے اسرٲیلِس پانس سٍتـ̡ ۔\n2.\\tتہٕ سپُد یہ، {یہ} بادشاہ رحبعام سٕندِس پوٗنٛژمِس ؤریس مَنٛز آو مصرُک بادشاہ شیشک یروشلمس خٕلاف، کیازِ تِمو اوس خداوند سٕندِس خلاف زیادتی کٔرمٕژ۔\n3.\\tباہ ہتھ رتھ تہٕ تریہ ساس گُرۍ سوارِ سٍتۍ: تہٕ تِم لُکھ ٲسۍ بے شمار یِم أمِس سٍتـ̡ مصرہٕ منزٕ نیران ٲسۍ۔ لوبیم، سوکیمس تہٕ ایتھوپیائی۔\n4.\\tتہٕ تٔمۍ نِش یِم یہوداہ سٍتـ̡ {متعلق} شہرن پیٹھ قبضہ کٔرِتھ، تہٕ آو یروشلمس کُن۔\n5.\\tامہ پتہ آو شمعیاہ پیغمبر رحبعام نِش، تہٕ یہوداہ کین شہزادن نِش، یِم شیشک سٍتـ̡ یروشلمس مَنٛز جمع گٔیہِ، تہٕ تِمن وونُن یِتھٕ پٲٹھۍ، خداوند چُھ ونان زِ تہٕ تۅہہ چھُ میہ ترٲومُت، تہٕ تێلہِ چھُس ژے شیشک سٕندِس اتھس منز تروومُت۔\n6. اَمہِ پتہٕ کٔر اسرٲیلٕکۍ شہزادٕ تہٕ بادشاہ پنُن پان عاجز۔ تہٕ تِمو ووٚن، خداوند چُھ نیکوس۔\n7. تہٕ یێلہِ خداوند وُچھ زِ تِم چھِ پنُن پان عاجز کٔرِتھ، خداوند سُند کلام آو شمعیہ ہس نِش یُس ونان چھِ، تِمو کٔر پانس عاجز۔ {لہذا} بہٕ کٔرٕ نہٕ تِم تباہ مگر بہٕ دِیہ تِمن رژھ۔ تہٕ میون قہر گژھہِ نہٕ شیشک سٕندِ اتھہٕ سٍتۍ یروشلمس پیٹھ تراونہٕ۔ {کیٚنٛہہ: یا، کیٚنٛہہ کال}\n8.\\tبہر حال گژھن تِم تٔمۍ سٕندِس خادم۔ تاکہ تِم گژھن میٲنۍ خدمت، تہٕ ملکن ہٕنزِ سلطنتن ہٕنز خدمت۔\n9.\\tیِتھٕ پٲٹھـ̡ آو مصرُک بادشاہ شیشک یروشلمس خلاف تہٕ نِن خداوند سٕندِ گرُک خزانہٕ تہٕ بادشاہ سٕندِ گرُک خزانہٕ۔ تٔمۍ نِش سٲری نِتھ: تٔمۍ نِش سۄنہٕ سٕنز ڈھال تہِ یُس سُلیمانن بنٲومٕژ ٲس۔\n10.\\tیَمہِ بدلہٕ بَنوو بادشاہ رِہبعام پیتلٕچ ڈھال، تہٕ کٔرٕن رٲچھ دارس سٕندِس اَتھَس حوالہٕ، یُس بادشاہ سٕندِس گرُک دروازٕ تھوو۔\n11. تہٕ ییلہ بادشاہ خداوند سٕندِس گرس منز اژِو، رٲچھ دِنہٕ وول آو تہٕ أنِن تِم دُبارٕ رٲچھ کِس کمرس منز۔\n12.\\tتہٕ ییلہ أمس پانس عاجز کٔر، خداوند سُند غضب پھیُر أمِس نِش، زِ سُہ کرِ نہٕ أمِس پوٗرٕ پٲٹھۍتباہ کرنہٕ، تہٕ یہوداہَس مَنٛز تہِ گٔیہِ معاملہٕ ٹھیٖک۔ {تہٕ بییہِ...: یا، تہٕ توتہِ ٲس یہوداہَس مَنٛز اصل چیز}\n13. یێمہِ کِنۍ کٔر بادشاہ رحبعام یروشلمس مَنٛز پانس مضبوط، تہٕ کٔرٕن حکومت: تکیازِ رہبعام اوس اکھ ژتٲجی وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز سدہ ؤری حکومت، سُہ شہر یُس خداوند اِسرٲیلٕکۍ سارِوٕے قبیلو منزٕ ژٲرمُت اوس، تتہِ اوس پنُن ناو تھاونہٕ مۅکھہٕ۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس نعمہ اکھ امونائیٹیس۔\n14.\\tتہٕ تٔمۍ کٔر بُر، تکیازِ تٔمۍ اوس نہٕ خداوند سٕندِ سٍتـ̡ دِل دِل تیار کٔرِتھ۔ {تَیار: یا، فِکسڈ}\n15.\\tوۅنۍ چھہ رحبعام سٕندِ اعمال گۅڈنچہ تہ ٲخری کتابہِ منز لیکھنہ آمٕتۍ، تہٕ عیدو سٕنزِ شجرہ نسب کِس بارس منز لیکھنہٕ آمٕتۍ؟ تہٕ {تتہِ} رودۍ رحبعام تہٕ یربعامس درمیان مسلسل جنگ۔ {کتاب: ہیب۔ لفظ}\n16.\\tتہٕ رحبعام گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ آو داؤد شہرس مَنٛز دفن کرنہٕ۔ {ابیجاہ: ابیجام تہِ ونان چھِ}","1. وۅنۍ کٔر بادشاہ یربعام سٕندِس اردٲہمہِ ؤریس منز ابییاہ یہوداہ ہس پیٹھ حکومت کرنہٕ خٲطرٕ شروع۔\n2. تٔمۍ کٔر یروشلمس مَنٛز تریہ ؤری حکومت۔ تٔمۍ سٕنزِ ماجہ ہُند ناو تہِ اوس میکائیاہ، یُس گیبیاہ کِس یوریل سٕنز کوٗر ٲس۔ تہٕ ابیاہس تہٕ یربعام درمِیان گوٚو جنگ۔\n3.\\tتہٕ ابیاہَن کٔر جنگہٕ کِس بہادر نفرن ہٕندِس لشکرس سٍتـ̡ صفہٕ سٍتـ̡ جنگہٕ، {حتیٰ کہ} ژور لچھ ساس منتخب نفرن سٍتـ̡ جنگہٕ: یربعام تہِ کٔر أمِس خٕلاف ٲٹھ لچھ ساس منتخب نفرو سٍتـ̡ جنگہٕ سٍتـ̡ صفہٕ سٍتـ̡ ۔ {ابیاح سیٹ: ہیب۔ ابیجا گٔیہِ اَکہٕ وَٹہٕ بٔنِتھ}\n4. تہٕ ابییاہ ووت کوہ زیمریم کِس پہاڑس پیٹھ، یُس افرائیم کِس پہاڑس مَنٛز چُھ، تہٕ ووٚنُن، اے یربعام تہٕ سارِنٕے اسرٲیلِس بوزو۔\n5. کیا تۅہہ پزِ نہٕ یہ زانُن زِ اسرٲیلُک خداوند خداہن دِژ اسرٲیلِچ بادشاہت داودس ہمیشہٕ خٲطرٕ، تمِس تہٕ تٔمۍ سٕندِس نیچوِس نوٗنہٕ کِس معاہدس سٍتـ̡ دِژمٕژ۔\n6. توتہِ چُھہ نیبت سُند نیچو یُس داؤد سُند نیچو سلیمان سُند خادم چُھ، یُس داؤد سُند خادم چُھ، چُھہ زندٕ گومُت، تہٕ کورُن پننِس آقا سٕندِس خٕلافس سٍتـ̡ بغاوت کٔرِتھ۔\n7.\\tتہٕ یێمہِ سٍتـ̡ چُھہ بیلیال سٕندِس نیچوِس رحبعام سٍتـ̡ پانس مضبوط، ییلہ رحبعام جوان تہٕ نرم دل اوس، تہٕ ہیوٚک نہٕ تِمن ہُند مقابلہٕ کٔرِتھ۔\n8. تہٕ وُنہِ چُھہ تُہۍ داؤد سٕندِس نیچوِس سٕندِس اتھس منز خداوند سٕنزِ بادشٲہی ہُند مقابلہ کرُن۔ تہٕ تُہۍ چھِو واریاہ بٔڈ بٔڈۍ، تہٕ تۅہہِ سٍتـ̡ سۄنہٕ بَچھرٕ یِم یربعام ژے دیوتاہَن ہٕندِ خٲطرٕ بنوومٕتۍ۔\n9. کیا ژے نہٕ خداوند سٕندِ کاہن، ہارون سٕندِ نیچو تہٕ لاوی کٔڈِتھ تہٕ کٔرِکھ نہٕ پادٕرۍ بَنوومُت؟ یُس تہِ یُس أکِس جوان دانٛد تہٕ سَتھ کٔرِتھ پنُن پان مقدس کرنہٕ یِیہ، سُہ آسہِ تِمن ہُند پادٕرۍ یِم نہٕ کانہہ دیوتا چھِ۔ {مقدس کرنہٕ خٲطرٕ...: ہیب۔ تٔمۍ سُنٛد اَتھٕ برنہٕ خٲطرٕ}\n10. مگر یێلہِ أسـ̡ خداوند چُھہ سون خدا، تہٕ أسـ̡ چُھہ نہٕ سُہ ترٲومُت۔ تہٕ پادٕرۍ، یِم خداوند سٕنز خدمت کران چھِ، چھِ ہارون سٕندِ نیٚچِو، تہٕ لاوی {انتظار} کٔرِتھ:\n11. تہٕ تِم چھِ پرٮ۪تھ صُبحَس تہٕ پرٮ۪تھ شامَس خداوند سٕندِ خٲطرٕ زالنہٕ آمٕژ قربانی تہٕ مٔدٕر اگربَن دزان: روٹی تہِ چھِ صاف میزس پیٹھ تھاونہٕ یِوان۔ تہٕ سۄنہٕ سُند شمع، یُس پرٮ۪تھ شامَس زالنہٕ خٲطرٕ: کیازِ أسۍ چھِ خداوند پنُن خدایہ سُند ذمہ دار۔ مگر ژے چھُکھ سُہ ترٲومُت۔\n12. تہٕ وُچھِو، خدا چُھ پانہٕ اسہِ سٍتـ̡ سٍتـ̡ پى اے بنی اِسرٲیلِو، پَنٕنـ̡ پَنٕنـ̡ باپَن ہٕندِس خداہس سٍتـ̡ لڑٲے نہٕ۔ تِکیازِ تُہۍ ہیکِو نہٕ کامیاب گٔژھِتھ۔\n13.\\tمگر یربعام کٔر یِمن پَتہٕ کُن حملہٕ، تہٕ تِم ٲسۍ یہوداہ برونہہ کُن، تہٕ یِمن پَتہٕ اوس حملہٕ۔\n14. تہٕ یێلہِ یہوداہ پتھ کُن نظر دِژ، وُچھِو جنگ برونہہ تہٕ پَتہٕ کُن، تہٕ تِمو کٔر خداوند سٍتـ̡ فریاد تہٕ پادٕرَو کٔر بُنـ̡ ۔\n15. اَمہِ پَتہٕ دِژ یہوداہ کٮ۪و مردو کرٛٮ۪کھ، تہٕ یُتھ زن یہوداہ کٮ۪و لوکو کرٛٮ۪کہٕ دِژ، یہِ سپُد زِ خداین دِژ یربعام تہٕ سارِنٕے اسرٲیلِس ابییاہ تہٕ یہوداہ برونہہ کُن۔\n16.\\tتہٕ بنی اسرائیل ژول یہوداہ برونہہ کُن، تہٕ خداین دیت تِم تِمن ہٕندِس اتھس مَنٛز۔\n17.\\tتہٕ ابییاہ تہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ مارۍ یِم سٍتـ̡\n18. یِتھٕ پٲٹھـ̡ گٔیہِ اَمہِ وِزِ بنی اِسرٲیلِس تل اننہٕ، تہٕ یہوداہ سٕندِس اولادَس سٍتـ̡ گٔیہِ غٲلب، تِکیازِ تِمو اوس پننین مٲلن ہٕندِس خداہس پیٹھ بھروسہ کران۔\n19.\\tتہٕ ابییاہ لوٚگ یربعام سٍتـ̡ پَتہٕ تہٕ أمِس نِش شہر تہٕ یِمن ہٕندِس قصبن سٍتـ̡ تہٕ یِمن ہٕندِس قصبن سٍتـ̡ کٔرٕن افرینس سٍتـ̡ شہر۔\n20. ابییاہ سٕندِس دۅہس مَنٛز ہیوٚت یربعام دُبارٕ طاقت حٲصِل تہٕ خداوند دِژ أمِس تہٕ سُہ موٗد۔\n21.\\tمگر ابییاہ ہیوٚت زوردار تہ ژۅداہ زنانن سٍتـ̡ خانٛدر، تہٕ زٲیِن وُہ تہٕ زٕ نیچوۍ تہٕ شُراہ کورِ۔\n22.\\tتہٕ ابییاہ سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِ وَتہٕ تہٕ تٔمۍ سٕندِس کلامَس مَنٛز لیکھنہٕ آمٕتۍ۔","1.\\tیێلہِ گۆو ابییاہ پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ تِمو کٔر سُہ داؤد شہرس مَنٛز دفن۔ تٔمۍ سٕنٛدیٚن دۄہن منٛز ٲس زمین دہن ؤرین خاموش۔\n2. تہٕ آساہن کٔر خداوند سٕندِس خدایہ سٕندِس نظرِ منز اصل تہٕ صحیح:\n3. تکیازِ تٔمۍ نِش نِش عجیب {دیوتاہن ہٕندِس قربان گاہٕ، تہٕ تھدِ مقامہٕ، تہٕ کٔرِن مجسمہٕ ژٹِتھ، تہٕ کٔرٕن باغہٕ: {images: Heb. مجسمہٕ}\n4.\\tتہٕ دِتُن یہوداہَس حکم زِ سُہ کٔرِن پننین آباؤ اجدادن ہُند خداوند خدا، تہٕ شریعت تہٕ حکم۔\n5.\\tتٔمۍ نِش نِش یہوداہ کٮ۪و سارِوٕے شہرو منزٕ تھدِ جایہِ تہٕ مجسمہٕ تہٕ بادشٲہی ٲس أمِس برونہہ کُن ژھۄپہٕ۔ {تصویر: ہیب۔ آفتاب امیجز}\n6. تہٕ تٔمۍ بنٲو یہوداہَس مَنٛز تار لٔگِتھ شہر: تکیازِ زمینس اوس آرام تہٕ تمن ؤرین منز اوس نہٕ تس کانہہ جنگ۔ تکیازِ خداوند اوس تس آرام دِژمُت۔\n7. تَمہِ کِنۍ ووٚن تٔمۍ یہوداہَس زِ أسۍ یِم شہر بناوٕن، تہٕ یِمن اندۍ پٔکھۍ دیوار، مینار، دروازٕ تہٕ بند بناوُن، {یێلہِ} زمین {چُھ} اسہِ برونہہ کُن۔ کیازِ أسۍ چھِ خداوند پنُن خدایہ ژھانڈمُت، اسہِ چھُ أمِس ژھانڈمُت، تہٕ تٔمۍ دِژ اسہِ پرٮ۪تھ طرفہٕ آرام دِنہٕ۔ تہٕ تِمو کٔر تعمیر تہٕ ترقی۔\n8.\\tتہٕ آسا ہس اوس اکھ لشکر یُس یہوداہ منزٕ ترے لچھ نِش نشانہٕ تہٕ نیزٕ نِش ٲس۔ تہٕ بنیامین منز، یُس نٮ۪بر ڈھال تہٕ کمان، زٕ ہتھ ژۅن ساس: یِم سٲری ٲسۍ بہادر نفر۔\n9. تہٕ تِمن خٕلاف دراو زرہ ایتھوپیا ساس ساس تہٕ ترے ہتھ رتھ۔ تہٕ آو مارشاہس نِش۔\n10.\\tپتہٕ دراو آسا أمِس خٕلاف، تہٕ تِمو کٔر مریشاہس مَنٛز زیفتھا کِس وادی مَنٛز جنگ۔\n11. تہٕ آسا ہن کٔر خداوند پننِس خداہس کُن فریاد تہٕ وونُن، خداوند، یہ چُھہ نہٕ تۅہہِ سٍتـ̡ کانہہ تہِ مدد کرُن، چاہے واریاہن سٍتـ̡ یا تِمن سٍتـ̡ یِمن نہٕ کانہہ طاقت آسہِ: اے خداوند سانہِ خدایہِ سٍتـ̡ کٔر اسہِ مدد۔ تکیازِ أسۍ چھِ ژے پیٹھ آرام کران، تہٕ تہندِ ناوٕ سٍتـ̡ أسۍ یَتھ بٔڈِس خلاف چھِ۔ اے خداوند، تو چُھکھ سون خدا۔ انسان گژھ نہٕ توے پیٹھ غالب گژھن۔ {مرد: یا، فانی انسان}\n12. یێمہِ کِنۍ دِژ خداوند ایتھوپیا ہٕندِس آساہس برونہہ تہٕ یہوداہ برونہہ کُن۔ تہٕ ایتھوپیا ژٔلۍ۔\n13.\\tتہٕ آسا تہٕ أمِس سٍتـ̡ لُکھ لُکھ تِمن ہُند پیچھا جیرارس تام: تہٕ ایتھوپیا ہٕندِس تختہٕ پیٹھ، زِ تِم ہیوٚک نہٕ پان بازیافت کٔرِتھ۔ تِکیازِ تِم گٔیہِ خداوند سٕندِ برونہہ تہٕ تٔمۍ سٕندِس لشکرس برونہہ کُن تباہ کرنہٕ۔ تہٕ تِمو نِش واریاہ غنیمت۔ {تباہ: ہیب۔ پھُٹمُت}\n14.\\tتہٕ تِمو کٔر جیرارس اندۍ پکھۍ سارنٕے شہرن پیٹھ حملہٕ۔ تِکیازِ خداوند سُند خوف آو تِمن سٍتـ̡ تہٕ تِمو کٔرِکھ سارِنٕے شہر برباد۔ تکیازِ تمن منز اوس واریاہ زیادٕ غنیمت۔\n15.\\tتِمو کٔرِکھ چارواین ہٕندِس خیمے تہٕ کٔرِکھ کۅکرِ تہٕ اونٹھ کٔرِتھ واپس۔","1. تہٕ خدایہِ سُند روح آو عودید سٕندِس نیچوِس عزریاہ پیٹھ:\n2.\\tتہٕ سُہ دراو آساہس سمکھنہٕ خٲطرٕ، تہٕ وونُن أمِس بوزو، آسا تہٕ سارِنٕے یہوداہ تہٕ بنیامین سٍتـ̡ بوزو۔ خداوند چُھہ توے سٍتـ̡ ، یێلہِ تہٕ تُہۍ أمِس سٍتـ̡ ٲسِو۔ تہٕ اگر توہہِ أمِس ژھانڈان چھِو، سُہ گژھہِ ژےٚ نِش لبنہٕ۔ مگر اگر توہہِ أمِس ترٛٲوِو، سُہ تراوِ توے ترک۔ {مِلنہٕ خٲطرٕ...: ہیب۔ آسا برونہہ}\n3. وۅنۍ چھہ واریاہس کالس پیٹھ، اسرٲیل، حقیقی خدایہ ورٲے تہٕ کُنہِ پرناوُن پادٕرٕ ورٲے، تہٕ شریعت ورٲے رودمُت۔\n4. مگر ییلہ تِمو پننِس مصیبت سٍتـ̡ اسرٲیلـ̡ کِس خداہس کُن پھیرِ، تہٕ أمِس ژھانڈنہٕ آمُت، سُہ آو تِمن سٍتـ̡ لبنہٕ۔\n5.\\tتہٕ تِمن زمانن منز اوس نہٕ تٔمِس سٍتـ̡ کانہہ امن یُس نیبر نیران اوس، تہٕ یُس اژان اوس تٔمِس سٍتـ̡\n6. تہٕ قوم گٔیہٕ قومہٕ تہٕ شہرٕ سٍتـ̡ تباہ کرنہٕ، تکیازِ خداین کٔر تِمن سارِنٕے مُصیبتن سٍتـ̡ پریشان۔ {تباہ: ہیب۔ ٹکڑن منز مارنہٕ}\n7. تَمہِ مۄکھٕ روٗزِو مضبوٗط تہٕ پَنٕنۍ اَتھٕ گژھِ نہٕ کمزور، تِکیازِ تُہٕنٛزِ کامہِ ہُند ثواب میلہِ۔\n8.\\tتہٕ ییلہ آساہن یِم کلام تہٕ عودید نبی سٕنز پیشن گویی بوز، تمٔۍ کٔر ہمت تہٕ کٔرِن یہوداہ تہٕ بنیامین سٕندِ سارِنٕے سرزمینہٕ منزٕ تہٕ تِمن شہرو منزٕ یِم تٔمۍ کوہ افرائیم پیٹھٕ نِمٕتۍ ٲسۍ، تہٕ خداوند سٕندِ قربان گاہ ہٕنز تجدید کٔرٕن، یُس خداوند سٕندِس برآمدس برونہہ کُن اوس۔ {مذموم...: ہیب۔ مکروہ چیز}\n9.\\tتہٕ تٔمۍ کٔر یہوداہ تہٕ بنیامین تہٕ اَفریم تہٕ منسی نِش تہٕ شمعون نِش سارِنٕے یہوداہ تہٕ بنیامین تہٕ اَمہ سٍتـ̡\n10.\\tتہ گٔیہِ تِمو یروشلمس مَنٛز یکوٹہٕ، یُس آسا کِس بادشاہت کِس پنٛدٲہِمِس ؤریس مَنٛز تریمہِ رٮ۪تہٕ مَنٛز جمع گٔیہِ۔\n11. تہٕ تِمو کٔر اَمی ساتہٕ خداوند سٕندِس سٍتـ̡ سَتھ ہتھ بیل تہٕ سَتھ ساس دانٛد پیش کرنہٕ۔ {یۅہے ...: ہیب۔ تمہ دۅہہ}\n12. تہٕ تِمو کٔر پننین مٲلن ہٕندِس خداہس سٍتـ̡ سٲرۍسٕے دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ تلاش کرنُک معاہدٕ۔\n13. یُس نہٕ یُس نہٕ اسرٲیلِکِس خداوند سٕندِس خداہس سٍتـ̡ ژھانڈان چُھ، سُہ گژھہِ قتل کرنہٕ یُن، چاہے لۄکُٹ آسہِ یا بٔڈ، مرد یا زنانہٕ۔\n14. تہٕ تِم چِھ بَڑِ آوازٕ سٍتـ̡ تہٕ کرٛٮ۪کہٕ دِتھ تہٕ بُنجہِ سٍتـ̡ تہٕ کارنیٹَس سٍتـ̡ قٕسم کَران۔\n15.\\tتہٕ سارِوٕے یہوداہ گٔیہِ حلف سٍتـ̡ خۄش، تِکیازِ تِمو اوس پوٗرٕ دِلہٕ سٍتـ̡ حلف کٔرمُت، تہٕ أمِس سٍتـ̡ سٍتـ̡ ژھارنہٕ آمُت۔ تہٕ سُہ آو تِمن نِش لبنہٕ: تہٕ خداوند دِژ تِمن اندۍ پٔکھۍ آرام۔\n16.\\tتہٕ آسا بادشاہ سٕنزِ موج ماچہ سٍتـ̡ ہٹٲوِتھ تٔمۍ سُہ ملکہ نِش ہٹٲومُت، تکیازِ تٔمۍ اوس أکِس باغس مَنٛز اکھ بُت بنوومُت: تہٕ آساہن ژٔٹِتھ تہٕ دِژُن نالہٕ کِدرنس پیٹھ زٲلِتھ۔ {موج: یعنی نانی} {بُت: ہیب۔ ہارر}\n17.\\tمگر تھدِ جایہ آیہ نہٕ اسرٲیلِس منزٕ نِنہٕ، توتہِ اوس آسا سُند دِل سارِنٕے دۅہن کٲم۔\n18. تہٕ تٔمۍ أنۍ خدایہ سٕندِس گرس مَنٛز تِم چیز یُس أمۍ سٕندِس مٲلہِ وقف کورمُت اوس، تہٕ یُس تٔمۍ پانہٕ وقف کورمُت اوس، رۄپہٕ تہٕ سۄنہٕ تہٕ بانہٕ۔\n19.\\tتہٕ آسا کِس دورِ حکومتہٕ کِس پانژمِس تہٕ ترہمس ؤریس تام اوس نہٕ کانہہ جنگ۔","1.\\tآسا باسا سٕندِس دورِ حکومتہٕ کِس شیٚیِمہِ تہٕ ترہمہِ ؤریس مَنٛز آو اسرٲیلُک بادشاہ یہوداہ سٕندِس خلاف تہٕ بنووُن رامہ یُس نہٕ یہوداہ کِس بادشاہس آساہس نِش اژُن۔\n2. پَتہٕ کٔر آسا سٕندِس گرٕ تہٕ بادشاہ سٕندِس گرٕ سٕندِس خزانہٕ منزٕ رۄپہٕ تہٕ سۄنہٕ تہٕ سوٗزُن شامٕکِس بادشاہ بن ہدادس نِش، یُس دمشقس مَنٛز روزان اوس، وونُن {دمشق: حب۔ دارمیسیک}\n3.\\tمیہ تہٕ تۅہہِ درمیان چھہ اکھ رابطہ، یتھہ پاٹھۍ میٲنس مٲلس تہٕ تہندس مٲلس درمیان اوس، وچھ میہ ژے رۄپہ تہٕ سون سوزمُت۔ گژھ اسرٲیلِک بادشاہ باشا سٍتـ̡ پَنُن اتحاد پھُٹراوُن، یُتھ سُہ میانہِ نِش نیرِ۔\n4.\\tتہٕ بنہداد کٔر بادشاہ آسا سٕندِس سٍتـ̡ تہٕ سوٗزِن پَنٕنـ̡ سٍتـ̡ س� تہٕ تِمو دِژ اِجون، دان، تہٕ ابیلمایم، تہٕ نفتالی ہٕندِس سارنٕے ذخیرٕ شہرس پیٹھ مار۔ {امس: ہیب۔ کُس اوس تٔمۍ سٕندِ}\n5.\\tتہ سپد ییلہ بعشہِ یہ بوز زِ تمٔۍ ترٲو رامہ سنز تعمیر تہ پنن کٲم بند کرُن۔\n6.\\tپَتہٕ آسا بادشاہن نِش سورُے یہوداہ۔ تہٕ تِمو نِیہِ رامہٕکۍ کٔنہِ تہٕ تِمن ہٕنزِ لٔکر، یَتھ سٍتـ̡ باشا اوس تعمیر کران۔ تہٕ تٔمۍ بنٲو اتھ سٍتۍ گیبا تہٕ مزپاہ۔\n7.\\tتہٕ تمہِ وِزِ آو حنانی یُس یہوداہ کِس بادشاہس آسا نِش تہٕ وونُن تٔمِس کیازِ ژے چُھکھ شام کِس بادشاہس پیٹھ بھروسہ کورمُت، تہٕ چُھنہٕ خداوند پنُن خدایہ سُند بھروسہ کورمُت، تێلہِ چُھہ شامُک بادشاہ سُند لشکر ژٔلِتھ ژٔلِتھ۔\n8. کیا ایتھوپیا تہٕ لوبیم ٲسۍ نہٕ اکھ بٔڑ میزبان، یتھ منٛز واریہن رتھ تہٕ گُرۍ سوار ٲسۍ؟ توتہِ، کیازِ ژے اوس خداوند سٍتـ̡ بھروسہ کٔرِتھ، تٔمۍ دِژ تِم پانس اتھس مَنٛز۔ {اکھ بٔڑ: ہیب۔ کثرت منز}\n9. یێمہِ سٍتـ̡ چُھہ خداوند سٕنزِ أچھ سارِنٕے زمینہٕ سٍتـ̡ یێلہِ سٍتـ̡ پَنُن پان مضبوٗط ہاونہٕ مۅکھہٕ یێمِس سٍتـ̡ دِل {تٔمِس} سٍتـ̡ کامل چُھ۔ اَتھ مَنٛز چھُ ژےٚ بیوقوفی کٔرمٕژ: لہذا یِنہٕ پتہٕ گژھہِ ژےٚ جنگ۔ {ہاونہٕ خٲطرٕ...: یا، سختی سان تمن سٕتۍ رٔٹنہٕ خٲطرٕ، وغیرہ}\n10.\\tپتہٕ گوٚو آسا سٕندِس سٍتـ̡ شرارت تہٕ تھووُن سُہ أکِس قٲد خانس مَنٛز۔ تکیازِ {سُہ} اوس اتھ {چیز} کِنۍ أمِس سٍتۍ غصہٕ تھاوان۔ تہٕ آساہن کٔر اکی ساتہٕ لوکن پیٹھ ظلم۔ {مظلوم: ہیب۔ کرشڈ}\n11.\\tتہٕ وُچھِو آسا سٕندِ اعمال گۅڈنِچ تہٕ ٲخری کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n12.\\tتہٕ آسا سٕندِس دورِ حکومتہٕ کِس کُنترٕمہِ ؤریس مَنٛز گوو تٔمِس کھورِ مَنٛز بٮ۪مار، یوتام تٔمۍ سٕنز بیمارِ {بٔڈ} گٔیہِ، توتہِ کٔر تٔمۍ نہٕ خداہس نِش بلکہ طبیبن ہٕنز کوشش۔\n13.\\tتہٕ آسا گۆو پننین مٲلن سٍتۍ، تہٕ گۆو پننہِ دورِ حکومتہٕ کِس أکِس ژتٲجی ؤریس مَنٛز۔\n14.\\tتہٕ تِمو دفن سُہ پننین قبرن منز، یُس تٔمۍ داؤد شہرس مَنٛز پانس خٲطرٕ بنوومُت اوس، تہٕ تھووُن سُہ بسترس مَنٛز یُس مٔدٕر خوشبو تہٕ مُختلِف قٕسمٕچ مَسالہٕ سٍتـ̡ بٔرِتھ اوس، یُس داروداہن ہٕندِ فن سٍتـ̡ تیار کرنہٕ آمُت اوس، تہٕ تِمو کٔر أمِس خٲطرٕ سٮ۪ٹھاہ زال۔ {اوس بنوومُت: ہیب۔ اوس کھننہٕ آمُت}","1. تہٕ تٔمۍ سٕندِس نیچوِس یہوشافتن کٔر أمِس بدلہٕ حکوٗمت، تہٕ کٔر اسرٲیلِس خلاف پانس مضبوٗط۔\n2. تہٕ تٔمۍ کٔرِن یہوداہ کِس سارنٕے تارٕ دار شہرن مَنٛز فوج تہٕ یہوداہ کِس سرزمینس تہٕ افرائیم کِس شہرن مَنٛز چھاونی قٲیم، یُس تٔمۍ سٕندِس مٲلہِ آسا سٕندِس مٲلہِ سٕندِس قبضس مَنٛز اوس قبضہٕ کوٚرمُت۔\n3. تہٕ خداوند اوس یہوشافتس سٍتـ̡ ، تکیازِ سُہ اوس پننِس مٲلِس داؤد سٕنزِ گۄڈنِچہِ وتہِ پٲٹھـ̡ پٔکِتھ تہٕ بعلِم سٍتـ̡ یێلہِ پى۪ٹھ۔ {of...: یا، پننس مٲلس سٕند، تہٕ ڈیوڈ سٕند}\n4.\\tمگر پننِس مٲلہِ سٕندِس خدایس سٍتـ̡ ژھانڈُن، تہٕ پۯاوُن تٔمۍ سٕندِس حُکمس مُطٲبق، نہ کہ اسرٲیلـ̡ سٕندِس عملس پٲٹھۍ۔\n5. تێمہِ کِنۍ کٔر خداوند پننِس اتھس مَنٛز بادشٲہی قٲیم۔ تہٕ سورُے یہوداہ آو یہوشافاتس نِش تحفہٕ۔ تہٕ أمِس ٲس دولت تہٕ عزت۔ {اننہٕ: ہیب۔ دِنہٕ آمُت}\n6. تہٕ تٔمۍ سُند دِل گۆو خداوند سٕنزِ وتہِ سٍتـ̡ تُلنہٕ۔ {اوس...: یعنی حوصلہٕ افزایی کرنہٕ}\n7.\\tپننہِ دورِ حکومتہٕ کِس تریمہِ ؤریس مَنٛز سوٗز تٔمۍ پننین شہزادن نِش، بنہیل، عبادیہ، زکریا تہٕ نیتھانیل تہٕ میکائیاہس نِش یہوداہ کِس شہرن مَنٛز پرناونہٕ خٲطرٕ۔\n8.\\tتہٕ تِمن سٍتـ̡ سٍتـ̡ تہٕ سٍتـ̡ س� تہٕ تمن سٍتـ̡ الیشاما تہٕ یہورام، پادٕر۔\n9. تہٕ تِمو کٔر یہوداہَس مَنٛز پرناوُن، تہٕ تِمو ٲس پانس سٍتـ̡ خداوند سٕنزِ شریعت ہٕنز کتاب تہٕ یہوداہ کین سارنٕے شہرن مَنٛز گٔژِھتھ تہٕ لُکن ہیچھناوٕنـ̡ ۔\n10. تہٕ خداوند سُند خوف پیوو یہوداہ ہٕندِس اندۍ پٔکھۍ سارنٕے ملکن ہٕندِس بادشاہتس پیٹھ، یُتھ زن تِمو یہوشافاتس سٍتـ̡ کانہہ جنگ کٔرِتھ۔ {فیل: ہیب۔ اوس}\n11. تہٕ کینہہ فلسطینی اوٚن یہوشافت تحفہٕ تہٕ رۄپہٕ خراج ۔ تہٕ عربو أنۍ أمِس سَتھ ساس تہٕ ستھ ہتھ مینڈٕ تہٕ ستھ ستھ ہتھ ژھاوٕل۔\n12.\\tتہٕ یہوشافات کٔر سٮ۪ٹھاہ زیادٕ۔ تہٕ تٔمۍ بنٲو یہوداہ قلعہٕ تہٕ دکانک شہر۔ {قلعہٕ: یا، محل}\n13. تہٕ أمِس اوس یہوداہ کِس شہرن مَنٛز واریاہ کارٕبار: تہٕ جنگی نفر، بہادر نفر ٲسۍ یروشلمس مَنٛز۔\n14.\\tتہٕ یِمن ہُند تعداد چُھہ تِہندِ مٲلِس سٕندِ گرٕ مُطٲبق: یہوداہٕک، ساسہٕ بٔدۍ ہٕندِس کپتان؛ عدنہ سردار، تہٕ أمِس سٍتۍ ٲسۍ ترے لچھ بہادر نفر۔\n15.\\tتہٕ أمِس سٍتـ̡ اوس یہوہانان کپتان، تہٕ أمِس سٍتـ̡ زٕ ہتھ ژۅن ساس۔ {امہِ پتہٕ...: ہیب۔ تٔمۍ سٕنٛدس اتھس پیٹھ}\n16.\\tتہٕ أمِس پتہٕ اوس زیکری سُند نیچو اماسیاہ، یٔمۍ پننہ مرضی سان پان خداوند سٕندِ خٲطرٕ پیش کوٚر۔ تہٕ أمِس سٍتۍ ٲسۍ زٕ لچھ ساس بہادر نفر۔\n17. تہٕ بینجمن۔ الیاڈا اوس اکھ طاقتور بہادر نفر، تہٕ أمِس سٍتۍ ٲسۍ کمان تہٕ ڈھال ہیتھ زٕ لچھ ہتھیار بند۔\n18.\\tتہٕ أمِس پَتہٕ اوس یہوُزآباد، تہٕ أمِس سٍتـ̡ ہَتھ ژۄہٕ ساس جنگہٕ خٲطرٕ تیار۔\n19.\\tیِم ٲسۍ بادشاہس پیاران، تِمن سٍتـ̡ یِمن بادشاہن سٲرۍسٕے یہوداہ سٕندِس تارس مَنٛز بٔنِتھ شہرن مَنٛز تھوو۔","1.\\tوۅنۍ اوس یہوشافتس دولت تہٕ عزت، تہٕ کوٚرُن احابس سٍتـ̡ رشتہٕ۔\n2. تہٕ {یقین} ؤری پَتہٕ ووت سُہ احاب کُن سامریہ۔ تہٕ احابن مارۍ أمِس خٲطرٕ تہٕ تِمن لُکن ہٕندِ خٲطرٕ یِمن سٍتـ̡ أمِس سٍتـ̡ ٲس، تہٕ کورُن أمِس سٍتـ̡ راموتگلاڈس تام گژھنـ̡ رٲضی۔ {پتہٕ...: ہیب۔ ؤری کِس ٲخرس پیٹھ}\n3. تہٕ اسرائیلٕکۍ بادشاہ اہابَن ووٚن یہوداہ کِس بادشاہ یہوشافاتَس زِ کیا ژٕ گژھِہ میانہِ سٍتـ̡ راموتگیلاد کُن؟ تہٕ تٔمۍ دیُت أمِس جواب، بہٕ چُھس ژے تہٕ میٲنۍ لوٗکھ چُھس تُہند لوک۔ تہٕ {أسۍ آسہِ} جنگس منز ژے سٍتۍ۔\n4. تہٕ یہوشفاتن ووٚن اسرٲیلِکِس بادشاہس سٍتـ̡ پرژھہٕ، بہٕ چُھس ژے دُعا کٔرِتھ، از تام خداوند سٕندِس کلامس پیٹھ۔\n5. تَمہِ کِنۍ کٔر اسرٲیلٕکۍ بادشاہن پیغمبرن ہٕندِ ژور ہتھ نفر جمع تہٕ تِمن وونُن، کیا أسۍ گژھو راموتگیلاد کِس جنگس مَنٛز، کِنہٕ بہٕ کٔرٕ برداش؟ تہٕ تمو ووٚن، ہیوٚر گژھ۔ تکیازِ خدایہ دِیہِ بادشاہ سٕندِس اتھس منز۔\n6.\\tمگر یہوشفاتن ووٚن زِ {کیا یتہِ چھُنہٕ یتہِ رب سُند کانہہ پیغمبر تہٕ یُس أسۍ أمِس متعلق پرژھہٕ گٲر کٔرِتھ؟ {امہ علاوٕ: ہیب۔ توتہِ، یا، بییہِ}\n7.\\tتہٕ اسرائیلٕکۍ بادشاہن ووٚن یہوشافاطس زِ {اَکھ شخٕص چُھ}، یٔمِس سٍتـ̡ أسـ̡ خداوند سٕندِس سٍتـ̡ پرژھہٕ گٲر کٔرِتھ، مگر بہٕ چُھس أمِس سٍتـ̡ نفرت۔ تکیازِ تٔمۍ کٔر نہٕ میانہِ خٲطرٕ زانٛہہ نیکی ہٕنز پیشن گوئی، مگر ہمیشہ بُرٕچ پیشن گویی کٔرمٕژ: یۅہے چھُ میکایہ اِملہ سُند نیچو۔ تہٕ یہوشفاتن ووٚن زِ بادشاہ گژھہِ نہٕ یہِ وَنُن۔\n8.\\tتہٕ اسرٲیلٕکۍ بادشاہن بُلوو پننیو أکِس افسرس تہٕ وونُن زِ اِملہ سُند نیچو میکایہ أنِو جلدی ۔ {افسر: یا، خواجہ سرا} {فیچ...: ہیب۔ ہیسٹن}\n9.\\tتہٕ اسرائیلُک بادشاہ تہٕ یہوداہُک بادشاہ یہوداہُک بادشاہ بیوٹھ یِمو منزٕ دۅشوے پننِس تختس پیٹھ، تہٕ تِم بِہتھ سامریہٕ کِس دروازس منز اژنہٕ وِزِ أکِس خٲلی جایہ۔ تہٕ سارِنٕے پیغمبرن کٔر تِمن برونہہ کُن پیشن گوئی۔ {خٲلی...: یا، فرش}\n10.\\tتہٕ چنانہٕ سٕندِ نیچو زدقیاہ اوس أمِس ششتٕرٕکۍ سینگ بنوومُت، تہٕ ووٚنُن خداوند یِتھٕ پٲٹھۍ چُھہ فرماوان زِ یِمو سٍتـ̡ ژے شامس دِوان یوتام نہٕ تِم ختم گژھن۔ {تِم...: ہیب۔ تُہۍ چھِو تِم کھٮ۪وان}\n11. تہٕ سارِوٕے پیغمبرن کٔر یہِ پیشن گویی کٔرِتھ زِ رموتھگلاڈس تام گژھ تہٕ روزُن ترقی، تکیازِ خداوند کرِ یہِ بادشاہ سٕندِس اتھس مَنٛز۔\n12.\\tتہٕ یُس قاصد میکایاہ بُلاونہٕ آمُت اوس تٔمِس سٍتـ̡ وَنُن زِ وُچھِو پیغمبرن ہٕندِ کلامَن ہٕندِس کلامَس سٍتـ̡ بادشاہس سٍتـ̡ خیر قرار دِنہٕ۔ تَمہِ کِنۍ گژھہِ پنُن کلام تہٕ تِمن ہٕندِس پٲٹھۍ، تہٕ رٔژ کتھ کرٕنۍ۔ {with...: Heb. اَکہِ ٲسِس سٍتۍ}\n13. تہٕ میکایہ ووٚن زِ خداوند چُھ زندٕ روزان، یێلہِ تہِ میون خدا چُھ وَنُن، یێلہِ بہٕ کَرٕ بہٕ کَتھ کَرٕنـ̡ ۔\n14. تہٕ ییلہ سُہ بادشاہس نِش آو، بادشاہن ووٚن أمِس میکایا، کیا أسۍ گژھو راموتگیلاد کِس جنگس خٲطرٕ، کِنہٕ بہٕ کرٕ برداش؟ تہٕ تٔمۍ ووٚن، تم گژھ تھوٚد تہٕ ترقی کرٕن، تہٕ تم یِن تُہنٛدس اتھس منٛز حوالہٕ۔\n15.\\tتہٕ بادشاہن ووٚن أمِس زِ بہٕ کٲژاہ لٹہِ ژے وَنُن زِ ژے کٔرِو نہٕ خدایہ سٕندِ ناوٕ سٍتـ̡ میانہِ خٲطرٕ حقیقت۔\n16. تێمہِ وۆن میہ وُچھ سارِنٕے اسرٲیلِس پہاڑن پیٹھ بٔرِتھ، یِمن ہٕندِس پٲٹھۍ، یِمن نہٕ کانہہ چرواہ چُھہ، تہٕ خداوند وۆن، یِمن چُھنہٕ کانہہ مٲلک۔ تِم گژھن پرٮ۪تھ أکِس شخٕص سُکوٗن سان پننِس گرس منز واپس۔\n17. تہٕ اسرائیلٕکۍ بادشاہن ووٚن یہوشافاطس زِ کیا مے ووٚن نہٕ ژے زِ سُہ کرِ نہٕ میانہِ خٲطرٕ نیکی ہٕنز پیشن گوئی، بلکہ بدی ہٕنز پیشن گوئی؟ {مگر برائی: یا، مگر بد خٲطرٕ}\n18.\\tبییہِ وۆن، لہذا بوزو خداوند سُند کلام۔ میہ وُچھ خداوند پننِس تختس پیٹھ بِہتھ، تہٕ آسمانُک سورُے لشکر اوس تٔمۍ سٕندِس دچھنہِ اتھس پیٹھ تہٕ کھوورِ اتھس پیٹھ کھڑا ۔\n19.\\tتہٕ خداوند ووٚن زِ کُس کرِ اسرائیلُک بادشاہ احاب یُس رموتھگلاڈس پیٹھ کھسِتھ پیوٚو؟ تہٕ اَکھ وَنُن اَتھ پَتہٕ تہٕ بیٛاکھ وَنُن اَتھ پَتہٕ۔\n20. اَمہِ پَتہٕ دراو اَکھ روح تہٕ ووٚتھ خداوند برونہہ کُن، تہٕ وونُن، بہٕ کٔرٕ أمِس لالچ۔ تہٕ خداوند ووٚن أمِس کتھ سٍتۍ؟\n21.\\tتہٕ تٔمۍ ووٚن، بہٕ نیرٕ نیرِتھ تہٕ تٔمۍ سٕندٮ۪ن سارِنٕے پیغمبرن ہٕندِس ٲسِس مَنٛز اکھ اپُز روح بٔنِتھ۔ تہٕ {خدا} ووٚن، تہٕ ژے کرو [أمس}، تہٕ تہٕ گژھ غٲلب: نیٚبر، تہٕ کرُن تہٕ کرُن {حتی}۔\n22. تێمہِ کِنۍ، وُچھِو خداوند چُھہ تُہندین پیغمبرن ہٕندِس ٲسِس مَنٛز اکھ اپُز روح تروومُت، تہٕ خداوند چُھ تۅہہِ سٍتـ̡ بُرٕ کتھ کٔرمٕژ۔\n23. اَمہِ پَتہٕ آو چِناناہُک نیچو زِدیقیاہ نزدیک، تہٕ دیتُن میکایاہ ہٕندِس گالَس پیٹھ تھپھ تہٕ وونُن، خداوند سُند روح کَمہِ وتہِ ووت میانہِ طرفہٕ تہٕ ژے سٍتـ̡ کتھ کرنہٕ۔\n24. تہٕ میکایہ ہن ووٚن، وُچھ تۅہہ تمہِ دۅہہ ییلہ ژیہ پان ژوٗرِ روزنہٕ خٲطرٕ أنٛدرِمِس کمرس مَنٛز ژٔلِتھ گٔژھِو۔ {into...: یا، چیمبر پیٹھہٕ چیمبرس تام: Heb. أکس چیمبرس منٛز اکھ چیمبر}\n25.\\tاَمہِ پَتہٕ ووٚن اسرٲیلِکۍ بادشاہ میکایاہ نِش تہٕ نِیُن شہرُک حاکم امون تہٕ بادشاہ سٕندِس نیچوِس یواشس نِش۔\n26.\\tتہٕ ونُن زِ بادشاہ چُھ یِتھٕ پٲٹھۍ ونان زِ یہِ {نفر} تھاوُن قٲد خانس منٛز، تہٕ دِیُن أمِس مُصیبتٕچ روٹی تہٕ مُصیبتُک آبہٕ دِنہٕ، یوتام بہٕ سُکون سان واپس یِوان۔\n27.\\tتہٕ میکایاہ ووٚن زِ یێلہِ تہٕ یێلہِ چُھہ نہٕ خداوند سٕندِ دٔسۍ کتھ کٔرمٕژ۔ تہٕ تٔمۍ ووٚن، بوزو، تم سارنے لوکو۔\n28. یێمہِ پٲٹھـ̡ گٔیہِ اسرٲیلُک بادشاہ تہٕ یہوداہُک بادشاہ یہوشافات، راموتگیلاد کُن۔\n29.\\tتہٕ اسرائیلٕکۍ بادشاہن ووٚن یہوشافتس زِ بہٕ کرٕ پنُن پوش تہٕ جنگس منز گژھہٕ۔ مگر پَنٕنۍ پوشہٕ لٲگِتھ لٲگِتھ۔ چنانچہ کٔر اسرٲیلُک بادشاہ پوش۔ تہٕ تِم گٔیہِ جنگس منٛز۔\n30.\\tشامٕکۍ بادشاہن اوس تمِس سٍتـ̡ رتھن ہٕندِس کپتھن ہُند حُکُم دِژمُت، یِم أمِس سٍتـ̡ ٲسۍ، یہِ وونُن زِ لوٚکٹِس تہٕ بٔڈِس سٍتـ̡ لڑٲے نہٕ، مگر صرف اسرٲیلِکِس بادشاہس سٍتـ̡ لڑُن۔\n31.\\tتہٕ سپُد ییلہ رتھن ہٕندیو کپتانو یہوشافات وُچھ، تِمو ووٚن زِ یہِ چُھ اسرٲیلُک بادشاہ۔ تَمہِ کِنۍ گٔیہِ تِمو أمِس أندۍ پٔکھۍ لڑنہٕ خٲطرٕ، مگر یہوشافتن کٔر کرٛٮ۪کھ، تہٕ خداوند کٔر أمِس مدد۔ تہٕ خداین کٔر تِم پانس نِش الگ گژھنہٕ خٲطرٕ۔\n32.\\tتکیازِ سپد یہ زِ ییلہ رتھن ہٕندِس کپتاہن یہ وُچھ زِ یہِ چُھنہٕ اسرٲیلُک بادشاہ، تِمو پھیرۍ أمِس پتہٕ پَتہٕ نِش دُبارٕ۔ {پیٹھ...: ہیب۔ تمس پتہٕ}\n33.\\tتہٕ أکِس نفرن کٔر أکِس کمانس کُن تہٕ لوٚگُن اسرٲیلِس بادشاہس لٔگِتھ لٔگِتھ تہٕ تٔمۍ ووٚن پننِس رتھَس نِش اتھہٕ پھیُرُن، یُتھ ژے مے لشکرٕ نِش نِتھ نِش نِش نِنہٕ۔ تکیازِ بہٕ چُھس زخمی۔ {أکِس منصوبس پیٹھ: ہیب۔ پننہ سادگی منز} {درمیان...: ہیب۔ جوڑن درمیان تہٕ سینہ پلیٹس درمیان} {زخمی: Heb. بیمار بنیومُت}\n34.\\tتہٕ امہِ دۅہہ ہُریوو جنگہٕ: تاہم روٗد اسرٲیلُک بادشاہ شامس خلاف پننِس رتس منز وُتھ، تہٕ آفتاب لوسنہٕ وِزِ سپُد سُہ موٗد۔","1. تہٕ یہوداہُک بادشاہ یہوشافاط، امن سان یروشلم کُن پننِس گھرس منز واپس۔\n2.\\tتہٕ حنانی سُند نیچو یہو درٛاو أمِس سمکھنہٕ خٲطرٕ، تہٕ وونُن بادشاہ یہوشپتَس زِ کیا ژے کٔرِو بےٚ دیندارن ہٕنز مدد کٔرٕن، تہٕ یِمن سٍتـ̡ خداہس سٍتـ̡ نفرت کرن وٲلِس سٍتـ̡ محبت کرٕنـ̡ ۔ تێمہِ کِنۍ چُھہ خداوند سٕندِ برونہہ کُن تہِ غضب۔\n3. توتہِ چُھہ ژے مَنٛز اصل چیز لبنہٕ آمٕژ، یتھ مَنٛز چُھہ ژے زمینہٕ منزٕ کُن کٔڈِتھ تہٕ خدایہ سٕندِ سٍتـ̡ پَنُن دِل تیار کورمُت۔\n4.\\tتہٕ یہوشافات روٗد یروشلمس مَنٛز روزان، تہٕ سُہ دُبارٕ بیرشبع پیٹھٕ لُکن ہٕندِس مٔنزۍ افرایم کِس پہاڑس تام درٛاو تہٕ أنِن تِم پننین مٲلن ہٕندِس خداہس نِش واپس۔ {سُہ گۆو ...: ہیب۔ سُہ آو واپس تہٕ درٛاو نیبر}\n5. تہٕ تٔمۍ کٔر یہوداہ کِس سارنٕے تارٕ دار شہرن مَنٛز شہرٕ پتہٕ شہر،\n6.\\tتہٕ وونُن قاضن یُس تہِ کرُن چُھہ یُس تہِ کرُن چُھہ یُس تہِ کرُن چُھہ یُس تہٕ یُس تہِ فٲصلس مَنٛز تہِ چُھہ تُہٕندِس سٍتـ̡ انصاف کٔرِتھ تہٕ یُس تہٕ چُھہ تُہٕندِس سٍتـ̡ انصاف کٔرِتھ تہٕ یُس تہٕ یُس {منز...: ہیب۔ فیصلہٕ کس معاملس منٛز}\n7. تێلہِ گژھہِ وۅنۍ خداوند سُند خوف تہِ آسُن؛ ہوشیار کرُن تہٕ کٔرِو {یہ}: کیازِکہِ خداوند سٕندِس خداہس سٍتـ̡ چُھنہٕ کانہہ بدکاری تہٕ نہ شخصن ہُند احترام، تہٕ تحفہٕ نِنہٕ سٍتـ̡ چُھہ نہٕ۔\n8.\\tامہِ علاوہ یروشلمس منز کٔر یہوشفات لاویو تہٕ پادٕرین تہٕ اسرٲیلِکۍ باپَن ہٕندِس سردارس سٍتـ̡ خداوند سٕندِ فیصلہٕ خٲطرٕ، تہٕ یێلہِ تِم یروشلمس واپس یِنہٕ وِزِ تنازعہٕ خٲطرٕ مقرر کٔرۍ۔\n9. تہٕ تٔمۍ دِیُت تِمن حکم دِتھ زِ یِتھٕ پٲٹھـ̡ گژھِو خداوند سٕندِس خوفس سٍتـ̡ وفادار تہٕ کامل دِلہٕ سٍتـ̡ کرنہٕ۔\n10. تہٕ یُس تہٕ تُہٕندِس شہرس مَنٛز، خونس تہٕ خونس درمِیان روزان چُھ، شریعت تہٕ حُکُم، قونونن تہٕ فٲصلن درمِیان تہٕ تُہۍ کٔرِو تِمن خبردار تہٕ تِمن تہِ خبردار کرُن زِ تِم چِھ نہٕ خداوند سٕندِس خلاف گُزٲر کٔرِتھ، تہٕ یێلہِ چُھہ تۅہہِ تہٕ پننین باین پى۪ٹھ، یێلہِ تہٕ تُہٕندِس بٲے سٍتـ̡ گژھِ نہٕ زیادٕ۔\n11.\\tتہٕ وُچھِو، امریاہ بٔڈ پادٕرۍ چُھہ خداوند سٕندِس سارِنٕے معاملس مَنٛز توے پیٹھ۔ تہٕ زبادیہ یُس یہوداہ کِس گرُک حکمران اوس، یُس بادشاہ سٕندِس سارِنٕے معاملَس مۅکھہٕ اوس، تہٕ لاوی تہِ گژھن تۅہہِ برونہہ کُن افسر۔ ہمت سان کٔرِو معاملہٕ، تہٕ خداوند روزِ نیکن سٍتـ̡ ۔ {ڈیل...: ہیب۔ ہمت کرو تہٕ کرُن}","1.\\tامہ پتہ تہِ سپد یہ زِ موآب سٕندِ بچہِ تہٕ عمونن ہٕندِ شُرۍ تہٕ تِمن سٍتـ̡ یێلہِ سٍتـ̡ عمونین سٍتـ̡ یێلہِ سٍتـ̡ یہوشافاتس سٍتـ̡ جنگہٕ کرنہٕ خٲطرٕ۔\n2. اَمہِ پَتہٕ آو کینہہ یِمو یہوشافتس ووٚنمُت زِ سمندرٕ اپارِ شامس کِس اپارِ چُھہ تۅہہِ خلاف واریاہ بٔڈ لشکر آمُت۔ تہٕ وچھو تِم {be} ہزازونتمارس منز، یُس {چُھ} اینگیدی چُھ۔\n3.\\tتہٕ یہوشفات کھوژُن تہٕ کوٚرُن پانس خداوند ژھارنہٕ خٲطرٕ تیار، تہٕ کورُن سٲرۍسٕے یہوداہَس مَنٛز روزُک اعلان۔ {پانہٕ: ہیب۔ تٔمۍ سُنٛد بُتھ}\n4.\\tتہٕ یہوداہ کٔر پان جمع تہ خداوند سٕنز مدد منگنہٕ خٲطرٕ، یہوداہ کین سارِوٕے شہرو منزٕ تہِ آیہ تِم خداوند سٕندِ سٍتـ̡ ژھانڈنہٕ خٲطرٕ۔\n5. تہٕ یہوشفات اوس یہوداہ تہٕ یروشلم کِس اجتماعس مَنٛز، خداوند سٕندِس گرس مَنٛز، نٔوِس دربارس برونہہ کُن کھڑا،\n6. تہٕ وونُن، اے خداوند، سانین آباؤ اجدادن ہُند خدا، کیا چُھہ نہٕ اسمانس مَنٛز خدا؟ تہٕ تہٕ چُھکھ نہ کافرن ہٕندِس سارنٕے سلطنتن پیٹھ حکمرٲنی کٔرتھ؟ تہٕ تۅہہِ ہٕندِس اتھس منز چھا نہٕ طاقت تہٕ طاقت، یُتھ زن کانہہ تہِ ہیکہِ نہٕ تۅہہِ مقابلہ کٔرِتھ؟\n7.\\tژے چھُنہٕ سٲنـ̡ خدا، {یێمہِ} کٔر یێمہِ زمینہٕ کین بسکینن پننہِ قوم اسرٲیلـ̡ برونہہ کٔڈِتھ تہٕ دِژُن ابراہیم سٕندِس اولادس ہمیشہٕ خٲطرٕ؟ {کُس: ہیب۔ تو}\n8.\\tتہٕ تِمو کٔر اَتھ مَنٛز روزان، تہٕ تُہٕندِس ناوٕ خٲطرٕ بنووُکھ تۅہہِ اَتھ مَنٛز اکھ مقدس گاہ،\n9.\\tاگر اسہِ پیٹھ تلوار، فیصلہ، یا وبا یا قحط ییہ اسہِ برونہہ کُن کھڑا تہ چانہِ حضوری منز، (تکیازِ تہند ناو چھہ یتھ گرس منز،) تہٕ سانہِ عذابس منز ژے کُن فریاد کرُن، تیلہِ کرو ژے بوزان تہٕ مدد۔\n10.\\tوُچھو وُچھِو عمون تہٕ موآب تہٕ کوہ سیرٕکۍ شُرۍ، یِمن نہٕ اسرٲیلِس حملہٕ کرنہٕ دِیُن، یێلہِ تِم مصر کہِ سرزمینہٕ منزٕ نیرِ، مگر تِمو گٔیہِ تِمن نِش پھیُر تہٕ تِم کٔرِکھ نہٕ تِمن تباہ ۔\n11.\\tوُچھو، {بہٕ چُھس ونان، کِتھہ کٔنۍ چِھ تِم اسہِ انعامہٕ دِوان، یُس ژے اسہِ وٲرث دِنہٕ خٲطرٕ دِژمُت چھُ۔\n12. اے سانہِ خدایہ، کیا ژٕ کٔرِکھ نہٕ تِمن ہُند فٲصلہٕ؟ تکیازِ اسہِ چھہ نہ اتھ عظیم صحبتس خلاف کانہہ طاقت یُس اسہِ خلاف یُس اسہِ خلاف یِوان چھُ۔ اسہِ چھیہ نہ پتاہ زِ اسہِ کیا کرُن، مگر سانۍ نظر چھیہ ژے پیٹھ۔\n13. تہٕ سارِوٕے یہوداہ گۆو خداوند برونہہ کُن، پننین شُرین، زنانہٕ تہٕ شُرٮ۪ن سٍتـ̡ کھڑا ۔\n14. تێمہِ پَتہٕ آو زکریا سُند نیچو یُس بنیاہ سُند نیچو یُس متانیاہ سُند نیچو یُس عیعیل سُند نیچو اوس، یُس عیعیل سُند نیچو اوس، یُس اساف سٕندِس نیچوِس سٍتـ̡ اوس، یُس جماعت ہٕندِس درمِس مَنٛز خداوند سُند روح آو ۔\n15.\\tتہٕ ووٚن یێمہِ سارِوٕے یہوداہ تہٕ یروشلمٕکۍ بسکیٖن دِنہٕ والیو تہٕ یێلہِ بادشاہ یہوشافاط، یِتھٕ پٲٹھـ̡ چُھہ خداوند تہِ ونان زِ یێمہِ بٔڈِ ہٕندِس بٔڈِس ہٕندِس وجہہ سٍتـ̡ گژھ نہٕ خوفزدہ تہٕ خوفزدٕ۔ تکیازِ جنگ {چُھ} چُھ نہٕ تُہند بلکہ خدایہ سُند۔\n16.\\tپَتہٕ گژھِو تِمن خٕلاف وُچھِو: وُچھِو تِم زِز کِس بالہٕ پیٹھ۔ تہٕ ژیہ لٔبِو تِم نالہِ ہٕندِس اندس پیٹھ، یرویل کِس بیابانس برونہہ کُن۔ {کلف: ہیب۔ عروج} {بروک: یا، وادی}\n17. یَتھ {جنگہٕ} مَنٛز گژھِو نہٕ لڑنٕچ ضوروٗرَتھ: پَنُن پان کھڑا کٔرِو، تہٕ خداوند سٕنز نجات وُچھِو پانس سٍتۍ، اے یہوداہ تہٕ یروشلم: خوفہٕ گژھِو نہٕ تہٕ خوفزدہ گژھِو۔ پَگہہ گژھ تِمن خلاف نیرُن: کیازِ خداوند آسہِ توے سٍتـ̡ ۔\n18.\\tتہٕ یہوشافات کٔر پنُن کلہٕ بُتھ زمینس کُن نوٚمُت، تہٕ سارِوٕے یہوداہ تہٕ یروشلمٕکۍ بسکیٖن گٔیہِ خداوند سٕنز عبادت کٔرِتھ خداوند سٕندِس برونہہ کُن۔\n19.\\tتہٕ کُہہیتی ہٕندِس اولادَس تہٕ کورہِین ہٕندِس اولادَس سٍتـ̡ گٔیہِ تھدِ آوازِ سٍتـ̡ اسرٲیِل کِس خدایہِ سٕندِس تعریفس مَنٛز کھڑا ۔\n20. تہٕ تِم ووٚتھ صُبحٲے سُلہِ تہٕ گٔیہِ تیکوع کِس بیابانس مَنٛز، تہٕ یێلہِ درٛاو یہوداہ، یہوداہ، تہٕ یروشلم کِس بسکیٖن دِن، بوزو۔ خداوند پنٕنِس خداہس پیٹھ کٔرِو ایمان تھاوُن، یِتھ کٔنۍ گژھِو تُہۍ قٲیِم گٔژھِو۔ تٔمۍ سٕندٮ۪ن پیغمبرن پیٹھ یقین کرو، تِتھٕ کٔنۍ گژھِو تُہۍ ترقی۔\n21. تہٕ ییلہ تٔمۍ لُکن سٍتـ̡ مشورٕ کٔر، تٔمۍ کٔر خداوند سٕندِ خٲطرٕ گیون وٲلۍ، تہٕ یێلہِ تِم لشکرس برونہہ کُن نیران چِھ، تہٕ ونُن زِ خداوند سٕنز حمد کرٕنۍ۔ تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ خٲطرٕ۔ {یہ...: ہیب۔ تعریف}\n22. تہٕ ییلہ تِمو گٮ۪وُن تہٕ تعریفہٕ کرنہٕ شروع کٔرِتھ، خداوند کٔر عمون، موآب تہٕ کوہ سیر کِس شُرین پیٹھ حملہٕ، یِم یہوداہَس خلاف آیہ۔ تہٕ تِم گٔے مارنہٕ۔ {تہٕ ییلہ...: ہیب۔ تہٕ تتھ وقتس منز ییلہ تم وغیرہ} {گیون...: ہیب۔ گٮ۪ونس تہٕ تعریفس منز} {تم ٲسۍ...: یا، تم ٲسۍ اکھ أکس ماران}\n23.\\tعمون تہٕ موآب ہٕندِس اولادَس کٔر سییر پہاڑ کین بسکینن خلاف کھڑا تہٕ یِمن مارنہٕ تہٕ تباہ کرنہٕ خٲطرٕ، تہٕ ییلہ تِمو سیر کین بسکینن ختم کٔر، پرٮ۪تھ أکِس کٔر بییِس تباہ کرنس منز مدد۔ {تباہ کرنہٕ خٲطرٕ: ہیب۔ تباہی خٲطرٕ}\n24.\\tتہٕ یێلہِ یہوداہ بیابانس مَنٛز نظر دِنہٕ آمُت، تِمو کٔر بٔڈِس کُن نظر، تہٕ وُچھِتھ گٔیہِ تِم لاشہٕ زمینس پٲٹھۍ، تہٕ کانہہ تہِ ژٔلِتھ ہیوٚک نہٕ۔ {نہٕ...: ہیب۔ ژلُن اوس نہٕ کانہہ تہِ}\n25.\\tتہٕ یێلہِ یہوشفات تہٕ تٔمۍ سٕندِ لُکھ تِمن ہُند مال نِنہِ آیہ، تِمو لٔب تِمن مَنٛز لاشہٕ تہٕ قۭمتی جوٲہِر، یِم تِمو پانس نِنہٕ کھۅتہٕ زیادٕ نِتھ، تہٕ تِم ٲسۍ تریہ دۅہہٕ غنیمت جمع کٔرِتھ، یہِ اوس واریاہ زیادٕ۔\n26.\\tتہٕ ژوٗرمہِ دۅہہ گٔیہِ تِم وادی بیراخ کِس وادی مَنٛز جمع ۔ تکیازِ تتہِ کٔر تِمو رب سٕنز برکت، تَمہِ کِنۍ اوس اَمہ جایہِ ہُند ناو از تام وادی بیراخ وننہٕ یوان۔ {بیراخ: یعنی برکت}\n27.\\tتمہ پتہ آیہ تم واپس، یہوداہ تہٕ یروشلمُک پرٮ۪تھ کانہہ شخص، تہٕ یہوشافات تہٕ یِمن برونہہ کُن، یُس خوشی سان یروشلمس کُن گژھُن۔ تکیازِ خداوند اوس تِم پننین دُشمنن پیٹھ شاد سپدان۔ {برونٛہہ: ہیب۔ ہیڈ}\n28. تہٕ تِم آیہ یروشلیم یُس خداوند سٕندِس گرس تام زبور تہٕ ہارپ تہٕ بُنگے ہٮ۪تھ ۔\n29. تہٕ خدایہِ سُند خوف اوس تِمن مُلکن ہٕندِس سارِنٕے سلطنتس پیٹھ، یێلہِ تِمو بوزمُت زِ خداوند چُھ اسرٲیلِس دُشمنن خلاف جنگ کوٚرمُت۔\n30.\\tتێلہِ اوس یہوشفات سُند دٲیرٕ ژھۄپہٕ، تکیازِ تٔمۍ سٕندِ خداین دِژ تس اندۍ پکھۍ آرام۔\n31. تہٕ یہوشافاتن کٔر یہوداہَس پیٹھ حکومت: {سُہ} اوس ترٕہ تہٕ پنژٕہ وُہُر وُہُر ییلہِ تٔمۍ بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز پٔنژٕہن ؤرین حکومت۔ تہٕ تٔمۍ سٕنٛزِ ماجہِ ہُنٛد ناو اوس ازوبہ یۄس شِلہی سٕنٛز کوٗر ٲس۔\n32.\\tتہٕ سُہ پوٚک پننِس مٲلِس آسا سٕنزِ وتہِ منز، تہٕ ہیوٚت نہٕ اَمہِ نِشہ نیرِتھ، یُس خداوند سٕندِس نظرِ سٍتـ̡ صحیح اوس۔\n33.\\tتھدِ جایہِ آیہ نہٕ نِنہٕ، تکیازِ وُنیُک تام اوس نہٕ لوکو پننین مٲلن ہٕندِس خداہس خٲطرٕ دِل تیار کورمُت۔\n34.\\tوۅنۍ چھہِ یہوشافاط سٕنزِ باقٕے اعمال، گۅڈنچہ تہٕ ٲخری کتھ، یُس حنانی سٕندِس نیچو یہو سٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، یُس اسرٲیلِکۍ بادشاہن ہٕنزِ کتابہِ مَنٛز {چُھ} دِنہٕ آمُت۔ {یہو سٕنز کتاب: ہیب۔ لفظ، بیترِ} {ذِکر: Heb. کھسنہٕ خٲطرٕ آو بناونہٕ}\n35.\\tتہٕ امہِ پتہٕ کٔر یہوداہ کِس بادشاہ یہوشافاطس سٍتـ̡ پانس سٍتـ̡ رلاونہٕ، یٔمۍ سٍتـ̡ سٮ۪ٹھاہ بدکار کٔرِتھ:\n36.\\tتہٕ سُہ رٔلِتھ تٔمِس سٍتـ̡ ترشِش گَژھنہٕ خٲطرٕ جہازٕ بَناوُن: تہٕ تِمو بَنوو اِزِنگبرس مَنٛز جہاز۔\n37.\\tاَمہِ پَتہٕ کٔر مریشہ کِس دوداہ سٕندِس نیچو الیعزر یہوشافتس خلاف پیشن گویی کٔرِتھ وونُن، کیازِ ژے چُھہ آحزیاہ سٍتـ̡ رٔلِتھ تہٕ خداوند چُھہ تُہٕندِس اعمال پھُٹرٲومٕتـ̡ ۔ تہٕ جہازٕ گٔیہِ پھُٹۍ، زِ تِم ہیوٚک نہٕ ترشِش گٔژھِتھ۔","1. وُنہِ اوس یہوشافات پننین مٲلن سٍتـ̡ شوٚنگمُت، تہٕ سُہ آو پننین مٲلن سٍتـ̡ داؤد شہرس مَنٛز دفن کرنہٕ۔ تہٕ تٔمۍ سٕندِ نیچوِس جہورام کٔر أمۍ سٕنزِ جایہِ حکومت۔\n2. تہٕ أمِس ٲس یہوشافاط، عزریاہ تہٕ یہیِیل، زکریا تہٕ عزریاہ تہٕ مائیکل تہٕ شیفطیاہ سٕندِ نیٚچِوۍ، یِم سٲری ٲسۍ اسرٲیلِکِس بادشاہ یہوشافات سٕندِ نیٚچِوۍ۔\n3. تہٕ یِہٕندِس مٲلہِ دِژ تِمن رۄپہٕ تہٕ سۄنہٕ تہٕ قۭمتی چیزن ہٕندِ بٔڈۍ تحفہٕ، یُس یہوداہَس مَنٛز تارٕ لٔگِتھ شہرن سٍتـ̡ دِنہٕ آمُت، مگر بادشٲہی دِژ یہورامس ۔ تکیازِ سُہ اوس گۄڈنیُک زامُت۔\n4. یێلہِ یہورام پننِس مٲلہِ سٕندِس بادشٲہی تام ووت، تٔمۍ کٔر پنُن پان مضبوط، تہٕ مارِن پنٕنـ̡ سٲری بٲے تلوار سٍتـ̡ تہٕ اسرٲیلٕکۍ شہزادن تہِ۔\n5. یہورام اوس ترہ تہٕ زٕ وُہُر وُہُر ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر ٲٹھن ؤرین یروشلمس مَنٛز حکومت۔\n6. تہٕ سُہ پوٚک اِسرٲیلِکۍ بادشاہن ہٕنزِ وتہِ پٲٹھۍ، یِتھٕ پٲٹھۍ اہاب سٕندِس گرس سٍتـ̡ پٔکِتھ، تکیازِ أمِس ٲس احاب سٕنز کورِ خانٛدارِنۍ تہٕ یُس خداوند سٕندِس نظرِ منز بُرٕ اوس۔\n7. تاہم خداوند کرِ نہٕ داؤد سُند گرٕ تباہ کرنہٕ، تِکیازِ تٔمۍ اوس داؤدس سٍتـ̡ عہد کورمُت، تہٕ یێلہِ تٔمِس تہٕ تٔمۍ سٕندِس نیچوِس ہمیشہٕ خٲطرٕ گاش دِنُک وعدٕ کورمُت۔ {گاش: ہیب۔ شمع، یا، شمع}\n8.\\tتٔمۍ سٕندِس دۅہس منز کٔر ایڈومیو یہوداہ کِس سلطنتس تل بغاوت تہٕ بنووُکھ پنُن پان بادشاہ۔ {ڈومینین: ہیب۔ اتھہٕ}\n9. تمہ پتہ دراو یہورام پننین شہزادن سٍتۍ، تہٕ تمس سٍتـ̡ سارِنٕے رتھَن سٍتـ̡ تہٕ سُہ ووٚتھ رٲژ تہٕ دِژُن ادومی یِمن ہٕندِس اندۍ پکھۍ تہٕ رتھن ہٕندِس کپتانن ہٕندِس سٍتـ̡ مار۔\n10. یێمہِ کِنۍ کٔر اَدومی یَتھ تام یہوداہ سٕندِس اتھہٕ سٍتـ̡ بغاوت۔ امی وقتہٕ کٔر لبناہن پننس اتھس تل بغاوت۔ تکیازِ تٔمۍ اوس پننین مٲلن ہُند خداوند خدایہ ترٲومُت۔\n11.\\tامہِ علاوٕ بنوو تٔمۍ یہوداہ کِس پہاڑن مَنٛز تھدِ جایہ، تہٕ یروشلم کین بسکینن زنا کرنُک حکم دِیُت، تہٕ یہوداہ کٔرٕن مجبوٗر۔\n12.\\tتہٕ تس آو ایلیاہ نبی سٕندِ طرفہٕ اکھ لیکھِتھ یتھ منز وَننہٕ آمُت چھُ، یِتھٕ پٲٹھۍ چُھہ تُہُند مٲل داؤد سُند خدا، کیازِ تہٕ چُھہ نہٕ پنہٕ نِس مٲلِس یہوشافع سٕنزِ وتہِ پٔکِتھ، تہٕ یہوداہ کِس بادشاہ آسا سٕنزِ وتہِ پٔکِتھ چُھہ،\n13.\\tمگر پٔکِن اِسرٲیلِکۍ بادشاہن ہٕنزِ وتہِ پٔکِتھ، تہٕ بنووُن یہوداہ تہٕ یروشلم کین بسکینن ہٕندِس پٲٹھۍ، یِتھٕ پٲٹھۍ، تہٕ کورُن پننِس مٲلہِ سٕندِس گرس ہٕندِس بٲے تہِ مٲرِتھ، یِم تۅہہِ کھوتہٕ بہتر ٲسۍ۔\n14. وُچھِو، خداوند کرِ تُہٕندِس لوکَن، تہٕ تُہٕندِس شُرِن، تہٕ تُہٕنزِ زنانہٕ تہٕ تُہٕندِس سارِنٕے مالہٕ سٍتـ̡ دِیُن: {اَکھ بٔڈ...: ہیب۔ اکھ زبردست سٹروک }\n15.\\tتہٕ تۅہہِ گژھہِ پننہِ أندرمن ہٕنزِ بیمارِ سٍتـ̡ سٍتـ̡ بٔڈ بیمارِ سٍتـ̡ بٔڈ بیمارِ سٍتـ̡ یێلہِ دۅہہٕ پۯاونہٕ یِنہٕ۔\n16.\\tامہِ علاوہ کٔر خداوند یہورامس خلاف فلسطینن تہٕ عربن ہُند روح یُس ایتھوپیا کین نزدیک اوس۔\n17. تہٕ تِم آیہِ یہوداہ کِس مَنٛز تہٕ اَتھ مَنٛز ژٔلِتھ تہٕ نِیُکھ سُہ سورُے چیز یُس بادشاہ سٕندِس گرس مَنٛز لبنہٕ آمُت اوس، تہٕ تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕنزِ زنانہٕ تہِ۔ یُتھ زن تس کانہہ نیچو ترووُن، یُس تٔمۍ سٕندِس نیچوِس منز سارِوٕے کھۄتہٕ لۄکُٹ یہواہاز سٕندِس نیچوِس سٍتـ̡ اوس۔ {کیریڈ...: ہیب۔ قٲد کٔرِتھ} {یہوحاز: یتھ تہِ وَننہٕ یوان چھُ، آہزیہ، یا عزریہ}\n18.\\tتہٕ یێمہِ سارِوٕے پَتہٕ دِژ خداوند أمِس أنٛدرِ مَنٛز اکھ لاعلاج بیمٲر۔\n19.\\tتہ سپد یہ زِ وقتس سٍتـ̡ زٕ ؤری گزرنہٕ پتہٕ گٔیہِ تٔمۍ سٕنزِ بیمارِ ہٕندِ وجہ سٍتـ̡ تٔمۍ سٕندِ أندرٕ پیوٚو تہٕ سُہ موٗد دَگ بیمارِ سٍتـ̡ ۔ تہٕ تٔمۍ سٕنٛدیو لوٗکو کٔر نہٕ أمِس خٲطرٕ زالنہٕ، یِتھ کٔنۍ تٔمۍ سٕنٛدٮ۪ن مٲلن ہٕنٛدِ زالنہٕ۔\n20. تٔمۍ اوس ترٕہ وُہُر ییٚلہِ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس منٛز ٲٹھن ؤرین حکوٗمت، تہٕ درٛاو نہٕ یژھنہٕ ورٲے ۔ بہرحال، تمو دفن سُہ ڈیوڈ شہرس منٛز، مگر بادشاہن ہٕندِس قبرن منٛز نہٕ۔ {بغیر...: ہیب۔ خواہش ورٲے }","1. تہٕ یروشلم کین بسکینو بنوو اَحزیاہ سٕندِ بدلہٕ پنُن لۄکُٹ نیچو بادشاہ، تکیازِ یُس نفرن ہُند جمٲژ عربن سٍتـ̡ خٲمس مَنٛز یِوان اوس، تِمو اوس سارِنٕے بٔڈۍ مٲرِتھ۔ یِتھٕ پٲٹھۍ کٔر یہوداہ کِس بادشاہ یہورام سُند نیچو احزیاہ حکومت۔\n2. ژتٲجی تہٕ زٕ وُہُر اوس اَحزیاہ یێلہِ تٔمِس بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز أکِس ؤریس پیٹھ حکومت۔ تٔمۍ سٕنٛزِ ماجہِ ہُنٛد ناو تہِ اوس عمری سٕنٛز کوٗر اتالیہ۔\n3.\\tسُہ اوس احاب سٕندِس گرٕ کِس وتہِ پَکُن، تکیازِ تسٕنزِ موج ٲس تٔمِس مُشیر یُس بدکار کٔرِتھ۔\n4. اَمہِ مۄکھٕ کٔر تٔمۍ خداوند سٕندِس نظرس مَنٛز بُرٕ یِتھ کٔرِتھ اہاب سٕندِس گرس سٍتـ̡ بُرٕے کٔرِتھ، تکیازِ تِم ٲسۍ تٔمۍ سٕندِس مٲلہِ سٕندِ مرنہٕ پتہٕ تٔمۍ سٕندِس مُشیرس سٍتـ̡ تٔمۍ سٕندِس مٲلہِ سٕندِ مرنہٕ پتہٕ\n5.\\tسُہ تہِ پوٚک تہندِس مشورس پٲٹھۍ، تہٕ سپُد اسرائیل کِس بادشاہ احاب سٕندِس نیچوِس یہورامس سٍتـ̡ راموتگلعادس مَنٛز شام کِس بادشاہ حزائیلَس سٍتـ̡ جنگہٕ کرنہٕ خٲطرٕ، تہٕ شامیو دِژ جورامس سٍتـ̡ مارنہٕ۔\n6.\\tتہٕ سُہ آو یزرایلس مَنٛز ٹھیک گژھنہٕ خٲطرٕ واپس، یِمو زخمو سٍتـ̡ أمِس راماہس مَنٛز دِنہٕ آمٕتۍ، ییٚلہِ تٔمِس شامٕکِس بادشاہ حزائیلَس سٍتـ̡ لَڑان اوس۔ تہٕ یہوداہ کِس بادشاہ یہورام سُند نیچو عزریاہ گۆو یہورام سٕندِس نیچوِس یزریلس مَنٛز وُچھنہٕ خٲطرٕ، کیازِ سُہ اوس بیمار۔ {کُس...: ہیب۔ یَتھ سٍتـ̡ تِمو زخمی کٔرِتھ} {Azariah: یتھ تہِ وَننہٕ چُھ، Ahaziah، یا یہواحز}\n7. تہٕ آہزیاہ سُند تباہی اوس خدایہِ سٕندِ طرفہٕ یُس جورامس مَنٛز یِنہٕ سٍتـ̡ بێیہِ سٍتـ̡ بێیہِ سٍتـ̡ نِمشی سٕندِس نیچوِس جہوُرَس سٍتـ̡ دِنہٕ آمُت، یُس خداوند اوس اَحاب سُند گرٕ ژٹنہٕ خٲطرٕ مسح کورمُت۔ {تباہی: ہیب۔ پَکُن پَکُن}\n8.\\tتہٕ سپُد یہِ زِ یێلہِ یہِ یێلہِ یہوُد اَہاب سٕندِس گرس پیٹھ فٲصلہٕ دِوان تہٕ یہوداہٕکۍ شہزادٕ تہٕ احزیاہ سٕندِس بٲے سٕندِس نیچوِس وُچھِتھ یِم احزیاہ سٕنز خدمت کران ٲسۍ، تٔمۍ کٔر تِم مٲرِتھ۔\n9.\\tتہٕ تٔمۍ ژھانڈ احزیاہ تہٕ تِمو رٔٹِتھ (تکیازِ سُہ اوس سامریاہس مَنٛز ژوُرِتھ) تہٕ أنِتھ یہوُس تہٕ ییلہ تمو مارِ، تِمو دفن کٔرِتھ دفن۔ کیازِ، تِمو ووٚن زِ سُہ چُھ یہوشافات سُند نیچو، یُس خداوند سُند دِلہٕ سٍتـ̡ ژھانڈان اوس۔ لہٰذا اوس نہٕ احزیاہ سٕندِس گرس سلطنت برقرار تھاونُک کانہہ اختیار۔\n10.\\tمگر ییلہ اَحزیاہ سٕنزِ ماجہِ اَتھالیاہ وُچھ زِ تٔمۍ سُند نیچو چُھ موٗدمُت، سُہ وُچھِتھ تہٕ کٔرٕن یہوداہ کِس گرٕ سٕندِس سارِنٕے شٲہی بُلِس تباہ۔\n11. مگر بادشاہ سٕنزِ کورِ یہوشابیتھ نِیوُن احزیاہ سُند نیچو یواش، تہٕ ژوٗرِ سُہ بادشاہ سٕندِس نیچوِس منزٕ ژوٗرِتھ تہٕ تھووُن سُہ تہٕ تٔمۍ سٕنزِ نرس أکِس بسترس مَنٛز۔ چنانچہ بادشاہ یہورام سٕنزِ کورِ، یہوعیدہ سٕنز زنانہٕ، (تکیازِ سۄ ٲس احزیاہ سٕنز بینہِ) ژوٗرِ سُہ اتھلیاہس نِش، تاکہ سُہ مٲرِتھ نہٕ۔ {یہوشبع: یتھ یہوشبع تہِ ونان چھِ}\n12. تہٕ سُہ اوس تِمن سٍتـ̡ خدایہِ سٕندِس گرس مَنٛز شیٚیہِ ؤری ژوٗرِتھ، تہٕ اتھالیاہ کٔر زمینس پؠٹھ بادشاہ۔","1. تہٕ سٔتِمہِ ؤریس مَنٛز کٔرٕن یہویاداہن پانس مضبوٗط، تہٕ ہتہٕ بٔدۍ ہٕندِس کپتان، عزریاہ یروہیم سُند نیچو، تہٕ یہوہحنان سُند نیچو اسماعیل، تہٕ عبید سُند نیچو عزریاہ تہٕ عدیاہُک نیچو معسییہ تہٕ زکری سُند نیچو الیشفاط سٍتـ̡ پانس سٍتـ̡ معاہدٕ کٔرِتھ۔\n2. تہٕ تِم گٔیہِ یہوداہ کِس سارِنٕے شہرو منزٕ لاوی جمع تہٕ اسرٲیلِکۍ باپَن ہُند سردار تہٕ تِم آیہ یروشلمس کُن۔\n3. تہٕ سارِوٕے جمٲژ کٔر خدایہ سٕندِس گرس مَنٛز بادشاہس سٍتـ̡ معاہدٕ۔ تہٕ تٔمۍ ووٚن تِمَن زِ وُچھِو، بادشاہ سُند نیچو کرِ بادشاہ، یِتھ کٔنۍ خداوند داؤد سٕندِس نیٚچوِس مُتلق ووٚنمُت۔\n4. یہِ {چُھ} سُہ چیز یُس تُہۍ کرِو۔ سبت کِس دۅہس منز اژُن چُھہ تُہُند تریم حصہ، پادٕرین تہٕ لاوِین ہُند، دروازن ہٕندِس قُلِس سٍتـ̡ دٲخل سپدُن۔ {دروازٕ: ہیب۔ تھریشولڈز}\n5. تہٕ تریم حصہ گژھہِ بادشاہ سٕندِس گرس مَنٛز۔ تہٕ تریم حصہٕ بُنیاد کِس دروازس پیٹھ: تہٕ سارِنٕے لُکھ گژھن خداوند سٕندِس گرٕ کِس دربارس مَنٛز۔\n6.\\tمگر کانہہ تہِ گژھہِ نہ خداوند سٕندِس گرس مَنٛز اژُن، پادٕرین تہٕ تِم یِم لاوِین ہٕندِس خدمتگارس سٍتـ̡ یِمن ہٕندِس گَرَس مَنٛز یِنہٕ۔ تِم گژھن اژُن، تِکیازِ تِم چھِ پاک، مگر سارِنٕے لُکھ گژھن خداوند سٕنزِ نگرٲنی تھاوٕنۍ۔\n7. تہٕ لاوی گژھن بادشاہس اندۍ گٔژھن، پرتھ کانہہ شخص پننس اتھس منز ہتھیار ہیتھ ۔ تہٕ یُس تہٕ یُس تہِ گرس منز یِیہ، سُہ گژھہِ مارنہٕ یُن، مگر ییلہ سُہ اژِ، تہٕ ییلہ سُہ نیرِ، تہٕ ییلہ سُہ نیرِ۔\n8. یِتھٕ پٲٹھۍ کٔر لاویو تہٕ سارِنٕے یہوداہ سٕندِس سارِنٕے چیزَس مُطٲبِق یُس یہویاداہَن پادٕرۍ دِیُتمُت اوس تہٕ تِمن سٍتـ̡ یِم سبت دۅہہٕ یِنہٕ وٲلِس نفرس سٍتـ̡ نیرُن اوس، تِمن سٍتـ̡ نِش یِمن سٍتـ̡ نیرُن اوس، تِمن سٍتـ̡ نِش یِم سبت دۅہہٕ نیرنہٕ وٲلۍ۔\n9.\\tامہِ علاوٕ دِژ یہویاداہن ہتہٕ بٔدۍ نیزٕ، بکلر، تہٕ ڈھالہٕ کِس کپتانس حوالہٕ، یُس بادشاہ داؤد سُند اوس، یُس خدایہ سٕندِس گرس مَنٛز اوس۔\n10.\\tتہٕ تٔمۍ تھووُن سارِنٕے لُکھ ، پرٮ۪تھ أکِس شخٕص سٕندِس اتھس منز ہتھیار ہیتھ ، مندرٕ کِس دٔچھنہِ طرفہٕ تہٕ مندرس سٍتـ̡ ، قربان گاہ تہٕ مندرس سٍتـ̡ ، بادشاہس اندۍ پکھۍ۔ {سائیڈ: ہیب۔ شولڈر} {مندر: ہیب۔ ہاؤس}\n11. پتہٕ اوٚن تِمو بادشاہ سُند نیچو، تہٕ لوگُکھ أمِس تاج، تہٕ دِتُکھ أمِس گوٲہی تہٕ بنووُکھ سُہ بادشاہ۔ تہٕ یہویاداہَن تہٕ تٔمۍ سٕنٛدٮ۪و نیچویو دِژ أمِس مسح تہٕ وونُن، خدایہ رَچھ بادشاہ۔ {خدا...: ہیب۔ بادشاہ زندٕ روزُن}\n12. وۅنۍ ییلہ اتھالیہ لُکن ہُند شور بوز تہٕ بادشاہ سٕندِس تعریفس منز لُکن ہُند شور بوز، سۅ آیہِ لُکن نِش خداوند سٕندِس گرس منز۔\n13.\\tتہٕ سۅ وُچھ تہٕ وُچھ بادشاہ اژنہٕ وِزِ پننِس تھمس پیٹھ کھڑا، تہٕ بادشاہ سٕندِ طرفہٕ دِژ شہزادٕ تہٕ بُرٕ: تہٕ ملکٕکۍ سارِنٕے لُکھ گٔیہِ خۅش تہٕ گٮ۪وُن گٮ۪وُن تہٕ گٮ۪وُن تہٕ یِمن ہٕندِس تعریفس منز گٮ۪وُن ہیچھناونہٕ آمُت۔ اَمہ پتہٕ ووٚنُن اَتھالیہ پنُن پلو ژٔٹِتھ تہٕ ووٚنُن، غداری، غداری۔ {غداری: ہیب۔ سازش}\n14.\\tاَمہِ پتہٕ أنۍ یہویاداہن پادٕرۍ ہتہٕ بٔدۍ کپتان یِم لشکرس پیٹھ مقرر کرنہٕ آمٕتۍ ٲسۍ، تہٕ تِمن وونُن، سُہ کٔرِو سِلہٕ نِش نیرُن، تہٕ یُس أمِس پتہٕ ییہِ سُہ تلوار سٍتـ̡ مارنہٕ۔ کیازِ پادٕرۍ ووٚن زِ یہِ مٲرِو نہٕ خداوند سٕندِس گرس مَنٛز۔\n15. تہٕ تِمو تروو أمِس پیٹھ اتھہٕ۔ تہٕ ییٚلہ سۄ بادشاہ سٕنٛدِ گرٕ کِس گُرِ دروازس منٛز اژنہٕ خٲطرٕ آیہ، تِمو مور سۄ تتہِ۔\n16.\\tتہٕ یہویاداہن کوٚر أمِس تہٕ سارنٕے لُکن درمِیان تہٕ بادشاہس درمِیان اکھ عہد زِ تِم گژھن خداوند سٕندِ لوک۔\n17.\\tاَمہِ پَتہٕ گٔیہِ سارِوٕے لُکھ بعل سٕندِس گرس کُن، تہٕ تٔمۍ سٕندِس قربان گاہَس تہٕ تٔمۍ سٕنزِ شکلہٕ ٹُکرٕ ٹُکرٕ کٔرِتھ مارُکھ بعلُک پادٕرۍ مَتان۔\n18. تہٕ یہویاداہن کٔر خداوند سٕندِ گرٕ کِس دفترس مُقرر، یُس داؤد خداوند سٕندِس گرس مَنٛز بٲگرٲومُت اوس، خداوند سٕندِس گرس مَنٛز بٲگراونہٕ آمُت، یِتھ کٔنۍ زَن موسیٰ سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت چُھ، خوشی تہٕ گیونہٕ سٍتـ̡ {یِتھ کٔنـ̡ داؤد سٕندِ دٔسۍ مقرر کرنہٕ آمُت}۔ {یتھہ پاٹھۍ اوس...: ہیب۔ ڈیوڈ سٕندِ اتھہٕ سٕتۍ}\n19.\\tتہٕ تٔمۍ تھووُن خداوند سٕندِس گرٕ کِس دروازس پیٹھ، یُس نہٕ کُنہِ تہِ چیزس مَنٛز ناپاک آسہِ۔\n20. تہٕ تٔمۍ رٔٹِن ہتہٕ بٔدۍ ہٕندِس کپتان، تہٕ رئیس، تہٕ عوامٕکۍ گورنر تہٕ زمینہٕ کِس سارِنٕے لوٗکھ، تہٕ بادشاہ سٕندِ گرٕ پیٹھٕ أنِن بادشاہ سٕندِ گرٕ پیٹھ۔\n21.\\tتہٕ سارِوٕے لُکھ گٔیہِ خۅش، تہٕ شہر گۆو خاموش، تمہ پتہ کٔر تِمو اتعالیہ تلوار سٍتـ̡ مار۔","1. یوآش اوس سَتھ وُہُر ییلہ تٔمۍ حکومت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز ژتٲجی ؤری حکومت۔ تٔمۍ سٕنٛزِ ماجہِ ہُنٛد ناو تہِ اوس بیرشیبا ہُک زیبیہ۔\n2. تہٕ یواشَن کٔر خداوند سٕندِس نظرِ سٍتـ̡ سارِنٕے دۅہن یہوعیدا سٕندِس نظرِ سٍتـ̡ صحیح۔\n3. تہٕ یہویاداہن رٔٹۍ أمِس خٲطرٕ زٕ زنانہٕ۔ تہٕ أمِس زاے نیٚچوۍ تہٕ کورِ۔\n4.\\tتہٕ یێمہِ پَتہٕ سپُد یُس خداوند سٕندِس گرس مرمت کرنُک خیال گۆو۔ {مرمت کرنہٕ خٲطرٕ: ہیب۔ تجدید کرُن}\n5. تہٕ تٔمۍ کٔر پادٕرۍ تہٕ لاوی جمع تہٕ تِمن وونُن، یہوداہ کِس شہرس مَنٛز گژھِو تہٕ سارِنٕے اسرٲیلِکۍ پٲنسہٕ جمع کٔرِو پَنٕنِس خدایہ سٕندِس گرس ؤری پتہٕ ؤری پتہٕ مرمت کرنہٕ خٲطرٕ، تہٕ وُچھِو تُہۍ یہِ معاملہٕ جلدی کٔرِو۔ توتہِ کٔر لاویو جلدی کٔرِتھ نہٕ۔\n6. تہٕ بادشاہن بُلوو یہویادا سردار، تہٕ وونُن تٔمِس زِ ژے کیازِ چُھہ نہٕ لیویو یہوداہ تہٕ یروشلم منزٕ یُس موسیٰ سٕندِ خدایہِ سٕندِ خادم تہٕ اسرٲیلٕچ جماعت سٕندِ حکمہٕ مطٲبق گواہ سٕندِ خیمہ خٲطرٕ انٛنہٕ خٲطرٕ اَننہٕ خٲطرٕ۔\n7. تکیازِ اتھلیا سٕندِ نیچوۍ، تمہِ بدکار زنانہِ اوس خدایہ سُند گرٕ پھُٹرٲومُت۔ تہٕ خداوند سٕندِ گرٕ سٕندِ سارِنٕے وقف کٔرِتھ کٔرِکھ تِمو بعلِمَس عطا کٔرِتھ۔\n8. تہٕ بادشاہ سٕندِس حُکمس پیٹھ بنوو تِمو اکھ صندوق تہٕ تھووُکھ خداوند سٕندِس گرٕ کِس دروازس پیٹھ۔\n9.\\tتہٕ تِمو کٔر یہوداہ تہٕ یروشلم کہِ ذریعہٕ اعلان زِ سُہ مجموعہ یُس موسیٰ خدایہِ سُند خادم {یُس} بیابانن مَنٛز اسرٲیلِس پیٹھ تراوُن۔ {اکھ اعلان: ہیب۔ اکھ آواز}\n10.\\tتہٕ سارِوٕے شہزادٕ تہٕ سارِوٕے لُکھ گٔیہِ خۅش تہٕ أنِتھ تہٕ ترٲوِکھ سینس مَنٛز، یوٚت تام تِم ختم گٔیہِ۔\n11.\\tوۅنۍ آو یہ سپد زِ ییلہ یہ صندوق لاویو ہٕندِ اتھہٕ سٍتـ̡ بادشاہ سٕندِس دفترس منز اننہٕ آو، تہٕ ییلہ تِمو وُچھ زِ واریاہ پٲنسہٕ چُھ، بادشاہ سُند کاتب تہٕ بڈِ پادٕرۍ سُند افسر آو تہٕ صندوق خٲلی کٔرِتھ رٔٹِتھ نِتھ دُبارٕ پننہِ جایہ۔ یِتھ کٔنۍ ٲسۍ تِم دۄہ دۄہ پتہٕ کران، تہٕ کٔرٕکھ وافر مقدار منٛز پونٛسہٕ جمع۔\n12. تہٕ بادشاہ تہٕ یہویاداہن دیُت تِمن یِمن یِمو خداوند سٕندِس گرٕچ خدمتٕچ کٲم کٔرِتھ، تہٕ خداوند سٕندِس گرس مرمت کرنہٕ خٲطرٕ کٔرٕکھ معمارن تہٕ چھانن ہٕنز خدمات حٲصل کرنہٕ، تہٕ یِمو کٔرٕکھ خداوند سٕندِس گرس ٹھیک کرنہٕ خٲطرٕ ششتٕر تہٕ پیتل تہٕ۔\n13.\\tیێلہِ کٔر کامگارو تہٕ کٲم کٔر تِمو سٍتـ̡ کامل، تہٕ تِمو کٔر خدایہ سُند گرٕ تٔمِس حالتس مَنٛز قٲیم، تہٕ کٔرٕکھ یہِ مضبوٗط۔ {کٲم...: ہیب۔ شفا گو کامہٕ پتہٕ}\n14. تہٕ ییلہ تِمو مُکمل کٔرِتھ، باقٕے پٲنسہٕ أنۍ بادشاہس تہٕ یہویاداہس برونہہ کُن، یِمو سٍتـ̡ خداوند سٕندِ گرٕ خٲطرٕ بانہٕ بناونہٕ آمٕتۍ، تہٕ بٔنِتھ تہٕ چمچہٕ تہٕ سۄنہٕ تہٕ رۄپہٕ ہٕندِ بانہٕ پیش کرنہٕ خٲطرٕ۔ تہٕ تِمو کٔر خداوند سٕندِس گرس مَنٛز سٲرۍسٕے دۅہہٕ سٍتـ̡ دزنہٕ نذرانہ پیش کرنہٕ۔ {پیش کرنہٕ خٲطرٕ...: یا، پیسٹلز}\n15.\\tمگر یہویاداہن ووت وٲنسہٕ، تہٕ ییلہ سُہ مرُن اوس دۅہن سٍتـ̡ بٔرِتھ بٔرِتھ۔ اکھ ہتھ ترہ وُہُر {اوس} ییلہ سہ مرنہٕ وِزِ اوس۔\n16. تہٕ تِمو دفن سُہ داؤد شہرس مَنٛز بادشاہن مَنٛز، تکیازِ تٔمۍ اوس اسرٲیلِس مَنٛز خدایہ سٕندِ طرفہٕ تہٕ پننِس گرس سٍتـ̡ نیکی کٔرمٕژ۔\n17.\\tیہوداہ سٕندِ مرنہٕ پتہٕ آیہِ یہوداہٕکۍ شہزادٕ تہٕ کٔرٕکھ بادشاہس سَجود۔ پتہٕ بوز بادشاہن تِمن ہٕنز کتھ بوز۔\n18.\\tتہٕ تِمو دراو پننین آباؤ اجدادن ہٕندِس خدایہ سُند گرٕ تہٕ کٔرٕکھ باغن تہٕ بُتن ہٕنز خدمت کرنہٕ۔ تہٕ یہوداہ تہٕ یروشلمس پیٹھ آو یِمن ہٕندِس خطاہس مۅکھہٕ قہر ۔\n19.\\tتوتہِ سوٗزۍ تِمن نِش پیغمبر، یُس تِمن دُبارٕ خداوند نِش اننہٕ خٲطرٕ۔ تہٕ تِمو دِژ تِمن خلاف گوٲہی مگر تِمو دِژ نہٕ بوزنہٕ۔\n20. تہٕ خدایہِ سُند روح آو یہویادا سٕندِس نیچوِس زکریا سٕندِس نِشس پیٹھ، یُس لُکن ہٕندِس پیٹھے کھڑا اوس، تہٕ تِمن وونُن یِتھٕ پٲٹھۍ، یِتھٕ پٲٹھۍ چُھ خدایہِ سٕندِس حکمس خلاف ورزی کٔرِتھ، یُس نہٕ تُہۍ ہێکہٕ کامیاب سپدِتھ؟ کیازِ تۅہہ چُھہ خداوند ترٲومُت، سُہ تہِ چُھ ژےٚ ترٲومُت۔ {آو...: ہیب۔ پلو لٲگِتھ}\n21.\\tتہٕ تِمو کٔر أمِس خلاف سٲزِش، تہٕ بادشاہ سٕندِس حُکمس پیٹھ کٔرٕکھ أمِس کٔنہِ کٔنہِ۔\n22. یِتھٕ پٲٹھـ̡ اوس نہٕ بادشاہس سُہ احسان یاد یُس یہویاداہن تٔمِس سٍتـ̡ کٔرمٕژ ٲس، بلکہ کوٚرُن پنُن نیچو مٲرِتھ۔ تہٕ ییلہ سُہ مرُن، تٔمۍ ووٚن، خداوند چُھ {یہ} وُچھان، تہٕ {it} ہُند ضرورت۔\n23.\\tتہٕ ؤری کِس ٲخرس پیٹھ سپُد شامُک لشکر أمِس خٕلاف۔ تہٕ تِمو آیہِ یہوداہ تہٕ یروشلمس مَنٛز تہٕ لُکن ہٕندِس سارِنٕے شہزادس تباہ کٔرِتھ تہٕ سوُزُکھ تِمن ہُند سورُے غُنیمت دمشق کِس بادشاہس نِش۔ {at the...: Heb. ؤری کس انقلابس منٛز} {دمشق: ہیب۔ دارمیسیک}\n24.\\tشامُک لشکر آو نفرن ہٕنز اکھ لۄکٕٹ جمٲژ ہٮ۪تھ، تہٕ خداوند دِژ تِمن ہٕندِس اتھس مَنٛز، تِکیازِ تِمو اوس پننین مٲلن ہُند خدایہ ترٲومُت۔ چنانچہ تمو دیت جواشس خلاف فیصلہٕ۔\n25.\\tتہٕ ییلہ تِمو أمِس نِش نیرِ، (تِکیازِ تِمو ترووُن أمِس سٕندِس بٔڈِس بیمارِس مَنٛز)، تٔمۍ سٕندٮ۪و خدمتگارو کٔر أمِس خلاف یہویادا سٕندِس نیچوین ہٕندِس خونہٕ خٲطرٕ سٲزِش، تہٕ مارُکھ سُہ پننِس بسترس پیٹھ، تہٕ سُہ موٗدُن، تہٕ تِمو دفن کٔرِکھ سُہ داؤد شہرس مَنٛز، مگر تِمو کٔر نہٕ سُہ بادشاہن ہٕندِس قبرن مَنٛز دفن۔\n26. تہٕ یِم چھِ تِم یِمو أمِس خلاف سٲزِش کٔر۔ زباد، شیمیتھ اکھ امونیتیس سُند نیچو، تہٕ یہوزاد آباد سُند نیچو۔ {زباد: یا، جوزاچر} {شمرتھ: یا، شومر}\n27.\\tوۅنۍ چھُ تٔمۍ سٕندِس نیچوِس متعلق، تہٕ تٔمِس پیٹھ تراونہٕ آمٕتۍ بوجھن ہٕنز عظمت، تہٕ خدایہ سٕندِس گرٕچ مرمت کِس متعلق، وُچھِو تِم {بادشاہن ہٕنزِ کتابہِ ہٕندِس افسانس مَنٛز لیکھنہٕ آمٕتۍ۔ تہٕ امازیاہ سٕندِس نیچوِس کٔر أمِس بدلہٕ حکومت۔ {مرمت: ہیب۔ بُنیاد } {کہانی: یا، تبصرہٕ}","1. امازیاہ اوس وُہُہ تہٕ پنٛژٕہ وُہُر وُہُر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز کُنوُہ وُہُر حکومت۔ تہٕ تسٕنزِ ماجہ ہُند ناو اوس یروشلمُک یہودان۔\n2. تہٕ تٔمۍ کٔر سُہ یُس خداوند سٕندِس نظرس منز صحیح، مگر کامل دِلہٕ سٍتـ̡ نہٕ۔\n3.\\tوۅنۍ سپد ییلہ أمِس بادشاہت قٲیم سپٕز، تٔمۍ مارۍ پَنٕنـ̡ خادم یِمو بادشاہ سُند مول مارمُت اوس۔ {قٲیم...: ہیب۔ تٔمِس پیٹھ تصدیق کٔر}\n4. مگر تٔمۍ مٲرِتھ نہٕ تِہندِ شُرِ مٲرِتھ بلکہ کٔرِن یِتھ کٔنۍ زِ شریعت مَنٛز موسیٰ سٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، یَتھ مَنٛز خداوند دِیُت حُکُم دِژمُت زِ باپ گژھن نہٕ شُرین ہٕندِ خٲطرٕ مَرُن، تہٕ بچہٕ گژھن مٲلن ہٕندِ خٲطرٕ مرُن، مگر پرٮ۪تھ کانہہ انسان گژھِ پننہِ گۅنہٕ خٲطرٕ مرُن۔\n5.\\tامہِ علاوٕ کٔر امازیاہ یہوداہ سٍتـ̡ سٍتـ�\n6.\\tتٔمۍ کٔرِن اِسرٲیلِس منزٕ ہتھ ٹیلنٹ رۄپہٕ خٲطرٕ اکھ لَچھ ساس بہادر نفر رٔٹِتھ ۔\n7.\\tمگر خدایہِ سُند اکھ شخص آو أمِس نِش یُس وَنُن زِ اے بادشاہ، اسرٲیلُک لشکر گژھ نہٕ پانس سٍتـ̡ نیرُن۔ کیازِ خداوند چُھ نہٕ اسرٲیلس سٍتـ̡ {یێلہِ سٍتـ̡ افرایم سٕندِس سارِنٕے اولادس سٍتـ̡ ۔\n8. مگر اگر ژیہ نیرِو، جنگہٕ خٲطرٕ روزِو مضبوط: خدا کرِ توے دُشمن برونہہ کُن، تکیازِ خدایہ چھُ مدد کرنُک تہٕ دُشمن ہُند طاقت تھاوان۔\n9.\\tتہٕ امازیاہَن ووٚن خدایہِ سٕندِس انسانس سٍتـ̡ مگر أسـ̡ کیا کٔرِو تِمن ہتہٕ ٹیلنٹَن ہٕندِ خٲطرٕ یُس میہ اسرٲیلِہ کِس فوجس دِژمُت چُھہ؟ تہٕ خدایہِ سٕندِ انسانَن دِیُت جواب، خداوند چُھ ژےٚ امہِ کھوتہٕ زیادٕ دِنس قٲبل۔ {فوج: ہیب۔ بینڈ}\n10. اَمہِ پَتہٕ کٔر اَمزیاہَن تِم الگ یُس لشکر افرائیم نِش أمِس نِش آو دُبارٕ گَرٕ گژھنہٕ خٲطرٕ، اَمہِ مۄکھٕ گوٚو تِہُند غصہٕ یہوداہَس سٍتـ̡ سٮ۪ٹھاہ شَرارتہٕ سٍتـ̡ واپس۔ {گَرٕ دوبارٕ: ہیب۔ تِمن ہٕندِس مقامس پیٹھ} {عظیم...: عبری۔ شَرارتہٕ کِس گرمی منٛز}\n11.\\tتہٕ امازیاہ کٔر پانس مضبوط، تہٕ کٔرٕن پنٕنـ̡ لُکھ نوٗنہٕ کِس وادی کُن تہٕ کورُن سیر سٕندِس دَہ ساس کِس شُرین ہٕندِس شُرِس مَنٛز۔\n12. تہٕ {باقٕے} دَہ ساس زِندٕ یہوداہ سٕندِ شُرِ نِتھ کٔنہِ کٔنہِ پیٹھٕ تہٕ ترٛٲوِکھ کنہِ پیٹھٕ تہٕ دِژٕکھ تِم سارِنٕے ٹُکرٕ ٹُکرٕ پٲٹھۍ۔\n13.\\tمگر لشکرٕکۍ سپاہ یُس امازیاہ ہن واپس سوزمُت، تاکہ تِم گژھن نہٕ أمِس سٍتـ̡ جنگس منز گژھن، لٔگِکھ یہوداہ کین شہرن پیٹھ، سامریہ پیٹھٕ بیتھورون تام تہٕ لٔگِکھ ترے ساس تہٕ نِیُکھ واریاہ لوُٹ۔ {فوجی...: ہیب۔ دی سنز آف دی بینڈ}\n14.\\tوۅنۍ سپد یہ سپدُن، ییلہ امازیہ ادومی ہٕندِس قتلہٕ سٍتـ̡ آو، سُہ أنۍ سیر کین بچن ہٕندِ دیوتا تہٕ تِم بنووُن پنہٕ نِس خداہس منز، تہٕ کٔرٕن تِمن برونہہ کُن سجُد، تہٕ دِژُن تِمن خٲطرٕ بخور زالُن۔\n15.\\tاَمہِ مۄکھٕ گۆو اَمزیاہس سٍتـ̡ خداوند سُند غصہٕ تہٕ تٔمِس نِش اکھ پیغمبر سوزمُت، یٔمۍ أمِس وَنُن زِ ژے کیازِ کٔر لُکن ہٕندِس دیوتاہن ہٕنز تلاش یِم نہٕ پنٕنـ̡ پنٕنـ̡ لُکن ہٕندِس اتھہٕ نِش نجات دِتھ ہیوٚک نہٕ؟\n16.\\tتہٕ ییلہ تٔمۍ أمِس سٍتۍ کتھ کٔرِتھ، {بادشاہ} ووٚن أمِس زِ ژٕ چھُکھ بادشاہ سٕندِس مشورس سٍتـ̡ بنیومُت؟ برداشت؛ ژیہ کیازِ گژھہِ مارُن؟ اَمہِ پَتہٕ ووٚن پیغمبرن تہٕ وونُن، مے چھے پتاہ زِ خداین چُھ ژے تباہ کرنُک ارادہ کورمُت، تکیازِ ژے چُھہ یہ کورمُت، تہٕ چُھکھ نہٕ میانہِ مشورٕ بوزمُت۔ {متعین: ہیب۔ مشورٕ}\n17. اَمہِ پَتہٕ کٔر یہوداہ کِس بادشاہ اَمزیاہ سُند مشورٕ تہٕ سوُزُن یہوہاز سٕندِس نیچوِس یہوآہاز سٕندِس نیچوِس یُس اسرٲیلِکِس بادشاہس سٍتـ̡ وُچھِو۔\n18.\\tتہٕ یُس اسرٲیلُک بادشاہ یوآش سوٗز یہوداہ کِس بادشاہ امازیہس نِش یہوداہ کِس بادشاہس نِش وونُن زِ یُس لبنان مَنٛز اوس، سُہ اوس دِودارس کُن یُس لبنان مَنٛز اوس، تہٕ ووٚن پَنٕنۍ کورِ میٲنِس نیچوِس زنانہِ دِنہٕ، تہٕ تَتہِ گٔیہِ اَکھ جنگلی جانور یُس لبنانس مَنٛز اوس، تہٕ لوٚگ کُنہِ۔ {تھیسٹل: یا، فرز بش، یا، کانٹ} {اکھ جنگلی...: ہیب۔ میدانُک اکھ جانور}\n19.\\tژے چُھہ ونان، لو، ژے چُھہ ادومی ہٕندِس مُتٲثِر کٔرِتھ۔ تہٕ تُہند دِل چُھ ژے فخر کرنہٕ خٲطرٕ تُلِتھ: وۅنۍ روزُن گَرِ منز؛ ژے کیازِ کٔرِو ژے ژے دَرٕ دِنہٕ خٲطرٕ، تہٕ یہوداہ تہٕ ژے سٍتـ̡ پۯاوٕنـ̡ تہٕ یہوداہ سٍتـ̡ پۯاوُن؟\n20. مگر امازیہ بوز نہٕ۔ تکیازِ یہِ اوس خدایہ سٕندِ طرفہٕ آمُت، یُس سُہ تِمن دُشمن ہٕندِس اتھس مَنٛز واتناوُن، تکیازِ تِم ٲسۍ ادوم کِس دیوتاہن ہٕندِس اتھس مَنٛز واتناوٕنۍ۔\n21. یِتھٕ پٲٹھـ̡ ووت اسرائیلُک بادشاہ یوآش۔ تہٕ تِمو وُچھ اَکھ أکِس بُتھِس مَنٛز، سُہ تہٕ یہوداہُک بادشاہ امازیہ، بیت شیمشس مَنٛز، یُس یہوداہ سٍتـ̡ چُھ۔\n22.\\tتہٕ یہوداہ آو اسرٲیلِس برونہہ کُن بدتر کرنہٕ، تہٕ تِم ژٔلِتھ پرٮ۪تھ أکِس شخصس پننِس خیمس کُن۔ سمیٹن}\n23.\\tتہٕ اسرائیلُک بادشاہ یوآش نِیوُن یہوداہ کِس بادشاہ یُس یہوہاز سُند نیچو یُس بیت شیمیشس مَنٛز نِتھ یُس یروشلم کِس دروازس پیٹھ ژۅن ہتھ ہاتھ دروازس تام پھُٹرٲوِتھ یروشلمُک دیوار پھُٹرٲوِتھ ژۅن ہتھ ہاتھ دروازس تام۔ {کون...: ہیب۔ امیک دروازہ یُس وچھان چھُ}\n24.\\tتہٕ تٔمۍ نِیُن سٲرٕے سۄنہٕ تہٕ رۄپھ، تہٕ تِم سارِنٕے بانہٕ یِم خدایہ سٕندِس گرس مَنٛز لبنہٕ آمٕتۍ ٲسۍ، تہٕ بادشاہ سٕندِس گرٕکۍ خزانہٕ، یرغمال تہِ، تہٕ واپس۔\n25.\\tتہٕ یہوداہ کِس بادشاہ یوآش سُند نیچو امازیاہ، یُس اسرائیلُک بادشاہ یہواہاز سُند نیچو یوآش سٕندِ مرنہٕ پتہٕ پندہ ؤری زندٕ۔\n26.\\tوۅنۍ چھہ امازیہ سٕندِ باقٕے اعمال گۅڈنچہ تہٕ ٲخری کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟\n27. وُنہِ ییلہ امازیاہَن خداوند سٕنزِ پیروی نِش پتھ کٔرِ، تِمو کٔر یروشلمس مَنٛز أمِس خلاف سٲزِش۔ تہٕ سُہ ژوٚل لاچِش کُن، مگر تِمو سوٗزُکھ أمِس پتہٕ لاچِش تہٕ مارُکھ سُہ تتہِ۔ {پیٹھ...: ہیب۔ پَتہٕ کَرنہٕ آمُت} {بَناونہٕ آمُت...: ہیب۔ سٲزِش کٔرٕکھ سٲزِش}\n28. تہٕ تِمو أنۍ سُہ گُرٮ۪ن پیٹھ تہٕ کوٚرُکھ یہوداہ شہرس مَنٛز پننین مٲلن سٍتـ̡ دفن۔ {یہوداہ: یعنی داؤد سُند شہر}","1. تمہ پتہ رٔٹ یہوداہ کیو سارِوٕے لوکو عزیاہ یُس شُراہ وُہُر اوس، تہٕ بنووُن سُہ پننِس مٲلِس امازیاہ سٕندِس کمرس مَنٛز بادشاہ۔ {عزیاہ: یا، عزریہ}\n2. تٔمۍ بنوو ایلوتھ، تہٕ یہوداہ کُن بَنووُن، تمہ پتہٕ گۆو بادشاہ پننین مٲلن سٍتـ̡ شۄنگنہٕ۔\n3.\\tشُراہ وُہُر عزیاہ ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز پنژاہ تہٕ زٕ وُہرۍ حکومت۔ تٔمۍ سٕنزِ ماجہ ہُند ناو تہِ اوس یروشلمُک یکولیاہ۔\n4. تہٕ تٔمۍ کٔر خداوند سٕندِ نظرِ سٍتـ̡ سُہ یُس تٔمۍ سٕندِس مٲلِس امازیاہ سٕندِ نظرِ سٍتـ̡ صحیح اوس۔\n5. تہٕ تٔمۍ کٔر زکریا سٕندِس دۅہس مَنٛز خدایہِ سٕندِس وژنس مَنٛز سمجُن، تہٕ یوتام سُہ خداوند سٕندِس خوابس مَنٛز سمجُن اوس، تہٕ یوتام سُہ خداوند سٕندِس سٍتـ̡ تلاش کٔرِتھ، خداین بنوو سُہ ترقی۔ {وژنن منز...: ہیب۔ خدایہ سٕندِس نظرس منز}\n6.\\tتہٕ سُہ دراو تہٕ فلسطینن سٍتـ̡ جنگ، تہٕ کٔرٕن گاتھٕچ دیوار، جبنی ہٕنز دیوار تہٕ اشدود سٕنز دیوار پھُٹرٲوِتھ تہٕ اَشدود سٕندِس أندۍ پٔکھۍ تہٕ فلسطینن مَنٛز بٔنِتھ شہر بٔنِتھ۔ {متعلق...: یا، اشدود کِس ملکس منز}\n7. تہٕ خداین کٔر أمِس فلسطینن تہٕ گربعلس مَنٛز روزن والٮ۪ن عربن تہٕ مہونیمن خلاف مدد۔\n8.\\tتہٕ عمونیو دِژ عزیاہس تحفہٕ، تہٕ تٔمۍ سُند ناو پھٲلیوو مصر کِس اژنس تام۔ تکیازِ تٔمۍ کٔر پانس سٮ۪ٹھاہ مضبوط۔ {پھٔلِو...: ہیب۔ گٔیہِ}\n9. امہِ علاوٕ کٔر عزیاہ ہن یروشلمس مَنٛز کونہٕ کِس دروازس پیٹھ، تہٕ وادی ہٕندِس دروازس پیٹھ تہٕ دیوارٕ کِس پھیرس پیٹھ تہٕ قلعہ بندی کٔرِتھ۔ {فورٹیفائڈ: یا، مرمت}\n10.\\tتٔمۍ بنوو ریگستانس مَنٛز مینار تہٕ کٔرِن واریاہ کۄرٕ، تکیازِ أمِس ٲسۍ واریاہ چاروۍ، بٔنِم مُلکس مَنٛز تہٕ مٲدٲنی علاقن مَنٛز: زمیندار تہٕ پہاڑن تہٕ کارملس مَنٛز، تِکیازِ أمِس اوس رچھُن خۅش کران۔ {کھٔنِتھ...: یا، واریاہ حوض ژٹِو} {کارمل: یا، پھلدار کھہ} {Husbandry: Heb. گراؤنڈ}\n11.\\tامہِ علاوٕ اوس عزیاہ ہس منز جنگجو نفرن ہُند لشکر، یِم تِہندِ حسابہٕ مُطٲبق یِمن ہٕندِس حسابس مُطٲبق یِمن ہٕندِس حسابس مُطٲبق یِمن ہٕندِس حسابس مُطٲبق یِمن ہٕندِ حنانیاہ سٕندِس اتھہٕ سٍتـ̡ بادشاہ سٕندِس کپتانن ہٕندِس اتھہٕ سٍتـ̡ جنگہٕ کرنہٕ آمُت۔\n12.\\tبہادر نفرن ہٕندِس مٲلن ہٕندِس سردارس ہُند کل تعداد اوس زٕ ساس شیہ ہتھ۔\n13.\\tتہٕ تِہندِس اتھس تل اوس اکھ لشکر، ترے لچھ ستھ ساس پانژھ ہتھ، یمۍ بادشاہس دشمنس خلاف مدتھ کرنہٕ خٲطرٕ زبردست طاقتہٕ سٍتۍ جنگ کٔر۔ {اکھ فوج: ہیب۔ فوجُک طاقت}\n14. تہٕ عزیاہ ہن کٔر تِہندِ خٲطرٕ سارِنٕے میزبانن ہٕندِ ڈھال، نیزہٕ، ٹوپی، تہٕ کمان، تہٕ کَنہٕ تراونہٕ خٲطرٕ تیار۔ {سلنگس...: ہیب۔ سلنگن ہندۍ پتھر}\n15.\\tتہٕ تٔمۍ بنوو یروشلمس مَنٛز یُس چالاک نفرو ایجاد کٔرِتھ، یُس برجن تہٕ بٔڈۍ کٔنِس پیٹھ ٲسِتھ تیر تہٕ بٔڈۍ کٔنہِ چلاونہٕ خٲطرٕ۔ تہٕ تٔمۍ سُند ناو پھٲلیوو دور تام ۔ تکیازِ تس آو حیرت انگیز طور مدد کرنہٕ، یوٚت تام سُہ مضبوط اوس۔ {سپریڈ: ہیب۔ برونٹھ کُن}\n16. مگر ییلہ سُہ مضبوط اوس، تٔمۍ سُند دِل تُلُن تُلُن، تکیازِ تٔمۍ کٔر خداوند سٕندِس خداہس خلاف خلاف ورزی تہٕ گوو خداوند سٕندِس مندرس مَنٛز بخور دِنہٕ خٲطرٕ۔\n17. تہٕ عزریاہ پادٕرۍ دراو أمِس پَتہٕ تہٕ أمِس سٍتـ̡ گٔیہِ خداوند سٕندِ ژور پادٕرۍ، یِم بہادر ٲسۍ۔\n18.\\tتہٕ تِمو کٔر عزیاہ بادشاہس مقابلہٕ تہٕ وونُن تٔمِس {یہِ چُھہ نہٕ ژےٚ عزیاہ، خداوند سٕندِ خٲطرٕ بخور زالنہٕ خٲطرٕ، بلکہ ہارون سٕندِس نیچوِس خٲطرٕ، یِم بخور زالنہٕ خٲطرٕ وقف کرنہٕ آمٕتۍ چھِ، پادٕرین خٲطرٕ، یِم بخور زالنہٕ خٲطرٕ وقف کرنہٕ آمٕتۍ چھِ، مقدس مقامہٕ منزٕ نیرِو۔ تکیازِ ژے چُھکھ خلاف ورزی کٔرمٕژ۔ نہ گژھہِ یہ خدایہ سٕندِ طرفہٕ تۅہہِ عزتہٕ خٲطرٕ آسُن۔\n19.\\tاَمہِ پَتہٕ گٔیہِ عزیاہ غصہٕ تہٕ اَتھَس مَنٛز اوس بخور زالنہٕ مۅکھہٕ اَتھَس مَنٛز، تہٕ یێلہِ سُہ پادٕرَن ہٕندِس گرس مَنٛز پادٕرَن ہٕندِس نِشتہٕ سٍتـ̡ تٔمِس ڈٮ۪کہٕ پٲٹھۍ۔\n20.\\tتہٕ عزریاہ بٔڈۍ پادٕرۍ تہٕ سارِوٕے پادٕرۍ کٔر أمِس وُچھان، تہٕ وُچھِتھ اوس أمِس ڈٮ۪کہٕ کُنہِ آ، پان تہِ نیبر نیرنس جلدی کٔرتھ، تکیازِ خداوندِ اوس تس مارمُت۔\n21. تہٕ عزیاہ بادشاہ اوس مرنہٕ دۅہہٕ کوڑھ تہٕ اوس واریاہن گھرن مَنٛز روزان، یُس کوڑھ اوس۔ تکیازِ سُہ اوس خداوند سٕندِس گرس نِش ژٹنہٕ آمُت: تہٕ یوتھم سُند نیچو اوس بادشاہ سٕندِس گرس پیٹھ، زمینہٕ کین لوکن ہُند فیصلہ کران۔ {واریاہ : ہیب۔ مُفت}\n22.\\tوۅنۍ چھہ عزیاہ سٕندِ باقٕے اعمال گۅڈنچہ تہٕ ٲخری کٲم آموز سٕندِ نیچو یسعیاہ پیغمبرن لیوکھمُت۔\n23.\\tتہ عزیاہ گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ تِمو دفن کٔرِتھ پننین مٲلن سٍتـ̡ تدفین کِس میدانس مَنٛز یُس بادشاہن سٍتـ̡ اوس۔ تِکیازِ تِمو ووٚن زِ سُہ چُھ کوڑھ تہٕ تٔمۍ سٕندِس نیچوِس یوتھمن کٔر أمِس بدلہٕ حکوٗمت۔","1. یوتھم اوس وُہُہ تہٕ پانٛژٕ وُہُر وُہُر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز شُراہ وُہُر حکومت۔ تٔمۍ سٕنٛزِ ماجہِ ہُنٛد ناو تہِ اوس یروشاہ، یۄس زادوک سٕنٛز کوٗر ٲس۔\n2. تہٕ یُس خداوند سٕندِس نظرِ سٍتـ̡ صحیح اوس، یُس تٔمۍ سٕندِس مٲلہِ عزیاہ سٕندِس مَنٛز دٲخل گوٚو۔ تہٕ لوکو کوٚر توتہٕ بدعنوانی سٔتۍ۔\n3. تٔمۍ بنوو خداوند سٕندِ گرُک تھوٚد دروازٕ، تہٕ اوفیل سٕندِس دیوارس پیٹھ بنوو واریاہ زیادٕ۔ {اوفیل: یا، ٹاور}\n4. امہِ علاوٕ بنٲو تٔمۍ یہوداہ کِس پہاڑن مَنٛز شہر تہٕ جنگلن مَنٛز بَنوو قلعہٕ تہٕ مینار۔\n5. تٔمۍ لوٚڑ عمونین ہٕندِس بادشاہس سٍتـ̡ تہٕ تِمن خلاف فتح حٲصل کٔرِتھ۔ تہٕ عمون سٕندٮ۪و شُرٮ۪و دِژ أمِس امی ؤرۍ یہِ ہتھ ٹیلنٹ رۄپہٕ، تہٕ داہ ساس کٕنٕک تہٕ داہ ساس جو۔ عمون سٕندٮ۪و شُرٮ۪و دِژ أمِس دٔیمِس تہٕ تریمہِ ؤریس منز تیوٗت معاوضہٕ۔ {تو...: ہیب۔ یہِ}\n6.\\tیێلہِ بنیوو یوتھم طاقتور، تکیازِ تٔمۍ کٔر خداوند پننِس خداہس برونہہ کُن پنٕنۍ وتھ تیار۔ {تیار: یا، قٲیم}\n7.\\tوۅنۍ چھہِ یوتھم سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِ سارِنٕے جنگہٕ تہٕ تٔمۍ سٕندِس طریقس سٍتـ̡ یِم اسرٲیلِہ تہٕ یہوداہ کِس بادشاہن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n8. سُہ اوس پانٛژٕ وُہُر وُہُر ییٚلہِ تٔمۍ حکوٗمت شروع کٔر، تہٕ یِمو کٔرٕن یروشلمس مَنٛز شُراہ ؤری حکومت۔\n9.\\tتہٕ یوتھم گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ تِمو دفن کٔرِتھ دفناونہٕ آمُت تہٕ تٔمۍ سُند نیچو اوس أمِس بدلہٕ بادشاہت کٔرمٕژ۔","1. احاز اوس وُہ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز شُراہ وُہُر حکومت، مگر تٔمۍ کٔر نہٕ خداوند سٕندِس نظرس منز صحیح یُس داؤد سٕندِس مٲلِس سٕندۍ پٲٹھۍ:\n2.\\tتکیازِ سُہ اوس اسرٲیلِکۍ بادشاہن ہٕنزِ وتہِ پٔکِتھ، تہٕ بعلیم سٕندِ خٲطرٕ بنٲوِن پگلہٕ مجسمہٕ تہِ۔\n3. امہِ علاوٕ زٲلِن تٔمۍ ہِنوم سٕندِس نیچوِس وادی مَنٛز بخور تہٕ پننین شُرٮ۪ن نارس مَنٛز زٲلِتھ یُس خداوند بنی اسرٲیلِس برونہہ کُن کڈمُت اوس۔ {دزنہٕ...: یا، قربانی پیش کٔر}\n4.\\tتٔمۍ کٔرٕن تھزرن جاین تہٕ بالن تہٕ پرٮ۪تھ سبز کُلِس تل تہٕ زالُن۔\n5. تێمہِ کِنۍ دیت خداوند تٔمۍ سٕندِس خداہن سُہ شام کِس بادشاہ سٕندِس اتھس مَنٛز۔ تہٕ تِمو دِژ أمِس مار، تہٕ تِمو نِکھ واریاہ بٔڑ قٲد، تہٕ أنِکھ دمشق ۔ تہٕ سُہ آو اسرٲیلِک بادشاہ سٕندِس اتھس منز تہِ حوالہٕ کرنہٕ، یٔمۍ أمِس سٮ۪ٹھاہ قتل عام کٔرِتھ۔ {دمشق: ہیب۔ دارمیسیک}\n6.\\tرِمالیاہ سٕندِ نیچِوِ پیکاہ سٕندِ خٲطرٕ مارۍ یہوداہ ہس مَنٛز أکِس دۅہس مَنٛز اکھ ہتھ تہٕ وُہ ساس ، یِم سٲری بہادر ٲسۍ۔ کیازِ تِمو اوس پننین مٲلن ہُند رب خدایہ ترٲومُت۔ {بہادر...: ہیب۔ بہادری ہٕنٛدۍ نیٚچو}\n7.\\tتہٕ زکری یُس افرائیم سُند اکھ طاقتور شخٕص اوس، مٲرِتھ بادشاہ سُند نیچو ماسیاہ تہٕ گرُک گورنر عزریکم تہٕ بادشاہس سٍتـ̡ الکانہ تہٕ یُس بادشاہس سٍتـ̡ اوس۔ {امہِ پتہٕ...: ہیب۔ دویم بادشاہس سٍتۍ}\n8.\\tتہٕ بنی اسرٲیلِو نِتھ پننین باین ہٕندِس زٕ لچھ ساس زنانہٕ، نیچوۍ تہٕ کورِ تہٕ تِمن نِش واریاہ غُنیمت تہٕ نِیُکھ غنیمت سامریہ۔\n9.\\tمگر خداوند سُند اکھ پیغمبر اوس، یٔمۍ سُند ناو اوس عودیس، تہٕ سُہ دراو سامریہ کِس لشکرس برونہہ کُن تہٕ تِمن وونُن، وُچھو، کیازِ تُہندین آباؤ اجدادن ہُند خداوند اوس یہوداہ سٍتـ̡ شرارت کٔرِتھ، تٔمۍ دِژ تِم تُہندس اتھس مَنٛز، تہٕ ژے مارۍ تِم غصہٕ سٍتـ̡ یُس آسمانس تام وٲتِتھ۔\n10. تہٕ وُنہِ چُھہ یہوداہ تہٕ یروشلم کِس شُرین سٍتـ̡ پانس سٍتـ̡ غلام تہٕ خادماتن ہٕندِس سٍتـ̡ تھاوُن: {مگر کیا چُھہ نہٕ توے سٍتـ̡ تہِ یێلہِ سٍتـ̡ خداوند پنُن خدایہ سٍتـ̡ گۅناہ کران چُھہ؟\n11. تێمہِ کِنۍ بوزو میٲنۍ تہٕ یِم قٲد دُبارٕ یِم تۅہہ پننین باین ہٕندِس قٲد کٔرۍمٕتۍ، تکیازِ خداوند سُند شدید غضب چُھہ توے پیٹھ۔\n12.\\tاَمہِ پَتہٕ گٔیہِ افرائیم سٕندٮ۪ن بچن ہٕندِس کلہٕ منزٕ کینہہ کلہٕ، عزریاہ یُس یوحنان سُند نیچو، میشیلموتھ سُند نیچو بریخیاہ تہٕ شالوم سُند نیچو یِہیزکیاہ تہٕ ہڈلائی سُند نیچو اماسا، جنگہٕ سٍتـ̡ یِمن ہٕندِس مقابلس منز کھڑا گٔیہِ۔\n13.\\tتہٕ وونُن تِمن زِ یێلہِ أسـ̡ یێلہِ أسـ̡ خداوند سٍتـ̡ گۅناہ تہٕ سٲنـ̡ گۅناہ تہٕ سانہِ گناہوں ہٕندِس سٍتـ̡ ہُرراوُن چُھہ، تێلہِ چُھہ سانہِ گۅناہ تہٕ سٲنـ̡ گۅناہ ہُند تہٕ سٍتـ̡\n14.\\tیێلہِ ترٲو ہتھیار بند نفرو قٲد تہٕ غنیمت شہزادن تہٕ سارنٕے جمٲژ برونہہ کُن۔\n15.\\tتہٕ یِمن نفرن ہُند ناو اوس دِنہٕ آمُت، تِمو کٔرِکھ قٲد، تہٕ لوُٹنہٕ سٍتـ̡ تِمن سارِنٕے نِش لٔگِتھ تہٕ لٔگِکھ کھٮ۪نہٕ تہٕ چیٚنہٕ خٲطرٕ، تہٕ دِتُکھ تِمن سارِنٕے کمزور گَرَن پیٹھ تہٕ أنِکھ یریحا کُن۔  کھجور کُلٮ۪ن ہُند شہر، پننین باین نِش: پتہٕ گٔیہ تِم سامریہ واپس۔\n16.\\tتمہِ وِزِ سوز بادشاہ احازن اَشِریہ کِس بادشاہس نِش تٔمِس مددٕ خٲطرٕ۔\n17. تکیازِ بییہِ اوس ادومی یِتھ یہوداہ ہُند مار دِژمُت تہٕ کٔرِکھ قٲد۔ {قیدی: ہیب۔ اکھ قید}\n18.\\tفلسطینیو اوس زیریں ملکٕکۍ تہٕ یہوداہ کِس جنوبس کِس شہرن پیٹھ تہِ حملہٕ کورمُت، تہٕ ٲسٕکھ بیت شیمیش، اجلون، تہٕ گیڈروتھ تہٕ شوچو یِمن ہٕندِس گامن سٍتۍ، تہٕ تِمن ہٕندِس گامس سٍتۍ، گِمزو تہٕ تِمن ہٕندِس گامس پیٹھ تہٕ تِم ٲسۍ اَتہِ روزان۔\n19.\\tکیازِ خداوند ہیوٚت یہوداہ اسرائیلُک بادشاہ آحاز سٕندِ وجہ سٍتـ̡ کمزور۔ تکیازِ تٔمۍ بنوو یہوداہ ننگہ، تہٕ کٔرٕن خداوند سٍتـ̡ زیادٕ۔\n20.\\tتہٕ اسیریاہُک بادشاہ تلگاتھپِلنیسر آو أمِس نِش، تہٕ تٔمِس دِژُن نہٕ تٔمِس مضبوٗط۔\n21.\\tتکیازِ احازن نِیوو خداوند سٕندِس گرُک تہٕ بادشاہ سٕندِس گرُک تہٕ شہزادن ہُند اکھ حصہٕ تہٕ دیتُن اشوریا کِس بادشاہس سٍتـ̡ مگر تٔمۍ کٔر نہٕ أمِس مدد۔\n22.\\tتہٕ مصیبت وِزِ کٔر تٔمۍ خداہس سٍتـ̡ بییہ زیادٕ: یہِ چُھہ بادشاہ آحاز۔\n23.\\tتکیازِ تٔمۍ کٔر دمشق کین دیوتاہن خٲطرٕ قربانی، یِمو أمِس مارٕ دِیُت، تہٕ تٔمۍ ووٚن، کیازِ شام کین بادشاہن ہٕندِ دیوتا چھِ تِمن مدد کران، {لہذا} بہٕ کٔرٕ تِمن خٲطرٕ قربانی، یُتھ تِم میانہِ مدتھ کٔرِتھ۔ مگر تِم گٔیہِ أمِس تہٕ سارِنٕے اِسرٲیلٕچ بربادی۔ {دمشق: ہیب۔ دارمیسیک}\n24.\\tتہٕ آحازن کٔر خدایہ سٕندِ گرٕکۍ بانہٕ جمع تہٕ ژٔٹِتھ ژٔٹِتھ خدایہِ سٕندِ گرٕکۍ بانہٕ تہٕ بنٛد کٔرِن خداوند سٕندِ گرٕکۍ دروازٕ تہٕ بنووُن یروشلیم کِس پریتھ کونس مَنٛز قربان گاہ۔\n25.\\tتہٕ یہوداہ کِس پریتھ شہرس مَنٛز بنوو تٔمۍ باقین دیوتاہن خٲطرٕ بخور زالنہٕ خٲطرٕ تھدِ جایہ، تہٕ کوٚرُن پننین مٲلن ہٕندِس خدایس شرارت کرنہٕ خٲطرٕ۔ {دزنہٕ خٲطرٕ: یا، پیش کرنہٕ خٲطرٕ}\n26.\\tوۅنۍ چھہِ تمۍ سٕندِ باقی اعمال تہٕ تٔمۍ سٕنزِ سارِنٕے وتہِ گۅڈنچہ تہٕ ٲخری وتہِ، یِم یہوداہ تہٕ اسرٲیلٕکۍ بادشاہن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n27.\\tتہٕ احاز گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ تِمو دفن کٔرِتھ شہرس مَنٛز، یێلہِ تہِ یروشلمس مَنٛز، مگر تِمو أنۍ نہٕ سُہ اسرٲیلِکۍ بادشاہن ہٕندِس قبرن مَنٛز تہٕ حزقیاہ ہٕندِس نیچوِس کٔر أمِس بدلہٕ بادشاہ۔","1.\\tحزقیاہ کٔر پانژِ وُہُر وُہُر وٲنسہِ وُہُر تہٕ تٔمۍ کٔر یروشلمس مَنٛز نَوُن وُہُن وُہُر حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس زکریا سٕنز کوٗر ابیجاہ۔\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز سُہ یُس تٔمۍ سٕندِس مٲلہِ سٕندِ دٔسۍ کرنہٕ آمُت اوس۔\n3. تٔمۍ کٔر پننہِ دورِ حکوٗمت کِس گۄڈنِکِس ؤریس مَنٛز، گۅڈنِکِس رٮ۪تس مَنٛز، خداوند سٕندِ گرٕکۍ دروازٕ کھولٕن، تہٕ کٔرٕن تِمن ہٕنز مرمت ۔\n4. تہٕ تٔمۍ أنۍ پادٕرۍ تہٕ لاوی تہٕ یِم جمع کٔرِتھ مشرقٕچ سڑکہِ مَنٛز،\n5. تہٕ وونُن تِمَن، اے لاو، بوزو، وۅنۍ کٔرِو پان پاک تہٕ پننین آباؤ اجدادن ہٕندِس خدایہِ سُند گرٕ پاک کٔرِو، تہٕ کٔرِو گندٕ پاکیزگی نِش نِش۔\n6. تکیازِ سانٮ۪و مٲلو چُھکھ غلطی کٔرمٕژ، تہٕ یُس خداوند سانہِ خدایہ سٕندِس نظرِ منز بُرٕ اوس، تہٕ چُھکھ أمِس ترٲومُت، تہٕ کٔرِکھ خداوند سٕندِ بستی نِش پنُن بُتھ پھیرِمُت، تہٕ پتھ پھیرِمُت۔ {پھیُر تِہُند...: ہیب۔ گردن دِنہٕ}\n7. یِمو چُھکھ دٲرِ دروازٕ بنٛد کٔرِتھ تہٕ چُھکھ شمعہٕ ژھوٚٹمُت، تہٕ چُھکھ نہٕ اگربتی زٲلِتھ تہٕ چُھکھ نہٕ اسرٲیلِکِس خدایہِ سٕندِس مُقدس مقامس مَنٛز زٲلِتھ نذرانہ پیش کٔرِتھ۔\n8. اَمہِ مۄکھٕ اوس خداوند سُند قہر یہوداہ تہٕ یروشلمس پیٹھ، تہٕ تٔمۍ دِژ تِم مصیبت، حٲرتن تہٕ پھیپھ دِنہٕ خٲطرٕ، یِتھ کٔنۍ تُہۍ پنٕنۍ أچھو سٍتـ̡ وُچھان چھِو۔ {پریشانی: ہیب۔ ہنگامہٕ}\n9. تکیازِ سانۍ مول چھہِ تلوار سٍتۍ مارۍمٕتۍ، تہٕ سانۍ نیچوۍ تہٕ سانۍ کورِ تہٕ سانۍ زنانہٕ چھِ اَمہ مۅکھہ قٲد کرنہٕ آمٕتۍ۔\n10. وۅنۍ چُھہ میٲنس دِلس منز زِ سُہ کرُن اسرٲیلِکِس خداوند خداہس سٍتـ̡ عہد کرُن، یُتھ تٔمۍ سُند شدید غضب اسہِ نِش پھیرِ۔\n11.\\tمیانہِ نیچو، وۅنۍ گژھ نہٕ لاپرواہ روزُن، تکیازِ خداوند چُھہ ژٲرمُت تہٕ تٔمِس سٍتـ̡ خدمت کرنہٕ خٲطرٕ، تہٕ تٔمِس سٍتـ̡ خدمت کرنہٕ خٲطرٕ، تہٕ بخور زالنہٕ خٲطرٕ۔ {نہ گژھُن...: یا، وۅنۍ گژھ نہ دھوکہٕ} {دزُن...: یا، قربانی پیش کٔرِو}\n12.\\tاَمہِ پَتہٕ گٔیہِ لاوی وُتھ، اماسایی سُند نیچو مہتھ تہٕ عزریاہ سُند نیچو یوایل، کوہاتی سٕندٮ۪ن نیچوین ہٕندِس نیچوِس تہٕ میراری سٕندِس نیچوِس کیش، عابدی سُند نیچو تہٕ عزریاہ سُند نیچو تہٕ گرشونیَن ہٕندِس نیچو۔ جوح زیمہ سُند نیچو تہٕ جوح سُند نیچو عدن:\n13. تہٕ الیزافان سٕندِس نیچوِس سٍتـ̡ ۔ شمری تہٕ جیئل: تہٕ آساف سٕندٮ۪ن نیچوین ہٕندِ۔ زکریا تہٕ متانیہ:\n14.\\tتہٕ ہیمان سٕندِس نیچوِس سٍتـ̡ ۔ جہیل، تہٕ شمیعی: تہٕ یدوتون سٕندِس نیچوۍ۔ شیمیہ تہٕ عزیل۔\n15.\\tتہٕ تِمو کٔرِکھ پَنٕنـ̡ بٲے جمع تہٕ کٔرٕکھ پنُن پان پاک، تہٕ بادشاہ سٕندِ حُکمہٕ مُطٲبِق آیہ خداوند سٕندِ کلامَس مُطٲبِق، خداوند سٕندِس گرس پاک کرنہٕ خٲطرٕ۔ {لفظن منز...: یا، رب سٕندِس کاربارس منز}\n16.\\tتہٕ پادٕرۍ گٔیہِ خداوند سٕندِس گرٕ کِس اندرمِس حصس مَنٛز، صاف کرنہٕ خٲطرٕ، تہٕ یُس سٲرِی ناپاکی یُس تِمو خداوند سٕندِس مندرس مَنٛز لبنہٕ آمُت اوس، نِش کٔرِکھ خداوند سٕندِس گرٕ کِس آنگنس مَنٛز۔ تہٕ لاویو نیو {یہ}، نیبر نیرنہٕ خٲطرٕ {یہ} نالہٕ کِدرنس منٛز۔\n17. وۅنۍ گٔیہِ تِمو گۄڈنِکہِ ریتہٕ کِس گۄڈنِکہِ دۅہہٕ پاکیزٕ کرنہٕ خٲطرٕ شروع، تہٕ ریتہٕ کِس ٲٹھمہِ دۅہہٕ آیہ تِم خداوند سٕندِس دٲرس مَنٛز۔ تہٕ گوڑنکہٕ ریتہٕ کس شُراہمہٕ دوہ گو تمو ختم۔\n18.\\tتێلہِ گٔیہِ تِم حزقیاہ بادشاہس نِش اژِتھ تہٕ وونُن، أسـ̡ چُھہ خداوند سُند سورُے گرٕ تہٕ دزنہٕ نذرانہٕ ہُند قربان گاہ، تہٕ تِمن ہٕندِس سارِنٕے بانن سٍتـ̡ تہٕ شیو روٹی ہُند دسترٕ تہٕ سارِنٕے بانن سٍتـ̡ صاف کٔرِمُت۔\n19.\\tتِم سٲری بانہٕ، یِم بادشاہ احاز سٕندِس دورس مَنٛز پننہِ سرکشی سٍتـ̡ پھیُر کٔرۍمٕتۍ، اسہِ چھِ تیار تہٕ پاک کٔرۍمٕتۍ، تہٕ وُچھِو تِم خداوند سٕندِس قربان گاہَس برونہہ کُن۔\n20. پتہٕ ووت حزقیاہ بادشاہ سُلہِ سُلہٕ، تہٕ شہرٕکۍ حکمران جمع کٔرِتھ ووت خداوند سٕندِس گرس تام۔\n21. تہٕ تِمو أنۍ سَتھ بیل، سَتھ مینڈٕ، سَتھ کٹہٕ تہٕ سَتھ ژھاوٕل، بادشٲہی خٲطرٕ، مقدس مقامہٕ خٲطرٕ تہٕ یہوداہ خٲطرٕ گۅناہ ہٕندِ قربانی خٲطرٕ۔ تہٕ تٔمۍ دِیُت ہارون سٕندِس نیچوِس پادٕرین حُکُم زِ تِم کٔرِن خداوند سٕندِس قربان گاہس پیٹھ پیش کرنہٕ۔\n22. یِتھٕ کٔنۍ تِمو مٲرِتھ بیل تہٕ پادٕرین روٚٹ خون، تہٕ دِژُکھ قربان گاہس پیٹھ خون، یِتھے پٲٹھۍ، یِتھٕ پٲٹھۍ، یِمو مٲرِتھ کٔرِکھ قربان گاہس پیٹھ خون۔\n23.\\tتہٕ تِمو کٔر بادشاہس تہٕ جمٲژ برونہہ کُن گۅنہٕ ہٕندِ نذرانہ خٲطرٕ۔ تہٕ تِمو تھوو تمن پیٹھ اتھہٕ: {فور: ہیب۔ نزدیک}\n24.\\tتہٕ پادٕریو کٔر تِم مٲرِتھ، تہٕ تِمو کٔر قربان گاہس پیٹھ پنُن خون، سارِنٕے اسرٲیلَن ہُند کفارہٕ دِنہٕ خٲطرٕ، کیازِ بادشاہن دِیُت حُکُم زِ سارِنٕے اسرٲیلِس خٲطرٕ گژھہِ دزنہٕ نذرانہ تہٕ گۅنہٕ نذرانہ کرنہٕ یُن۔\n25.\\tتہٕ تٔمۍ کٔر لاوی خداوند سٕندِس گرس مَنٛز داؤد سٕندِس حُکمس مُطٲبق تہٕ گاد بادشاہ سٕندِ حُکمہٕ مُطٲبق تہٕ ناتھن سٕندِ حُکمہٕ مُطٲبق رٔنگۍ تہٕ ہارپ سٍتـ̡ تھاونہٕ۔ {خداوند سُند حکم: ہیب۔ خداوند سٕندِ اتھہٕ سٍتـ̡ حُکُم} {by: Heb. اتھہٕ سٍتۍ }\n26. تہٕ لاوی گٔیہِ داؤد سٕندِس سازس سٍتـ̡ تہٕ پادٕرۍ بٔرِتھ کھڑا۔\n27. تہٕ حزقیاہ ہن دِیُت حُکُم زِ سُہ دِیہِ قربان گاہس پیٹھ دِنہٕ۔ تہٕ یێلہِ زٲلِتھ نذرانہ شروع گٔیہ، خداوند سُند گٮ۪وُن گۆو بُرِ سٍتـ̡ تہٕ اسرٲیلِکِس بادشاہ داؤد سٕندِ دٔسۍ مقرر کرنہٕ آمٕتـ̡ سازو سامان سٍتـ̡ شروع۔ {جب: ہیب۔ وقتس منز} {آلات: ہیب۔ آلاتٕکۍ اتھہٕ}\n28.\\tتہٕ سارِنٕے جمٲژ کٔر پوٗزا تہٕ گیون والیو گیوُن، تہٕ بُنڈرن ہٕندِ آوازٕ وُچھن: {تہٕ} سارِوٕے {یہِ جٲری} یوٚت تام زٲلِتھ نذرانہ مُکمل سپدِ۔ {گلوکار: ہیب۔ گیون}\n29. تہٕ ییٚلہِ تِمو نذرانہٕ ختم کٔرِتھ، بادشاہ تہٕ أمِس سٍتـ̡ موجود سارِوٕے کٔرٕکھ نمُن، تہٕ کٔرٕکھ پوجا کرنہٕ۔ {موجود: ہیب۔ لٔب}\n30. امہِ علاوٕ، حزقیاہ بادشاہ تہٕ شہزادن دِیُت لاوِین حکم زِ تِم کٔرِن داؤد سٕندِ کلامَو سٍتـ̡ خداوند سٕندِ حمد گٮ۪وُن۔ تہٕ تِمو گیوٚو خوشی سان تعریف، تہٕ تِمو کلہٕ نوٚم کٔرِتھ پوٗزا کٔرِتھ۔\n31. اَمہِ پَتہٕ حزقیاہ ہن دیُت جواب تہٕ وونُن، وُنہِ چُھہ تُہۍ خداوند سٕندِ خٲطرٕ پنُن پان مقدس کورمُت، یێلہِ یِو نِش تہٕ خداوند سٕندِس گرس مَنٛز قُربٲنی تہٕ شُکرٕ نذرانہٕ أنِو۔ تہٕ جماعت أنۍ قربانی تہٕ شکریہ ادا کرنٕچ پیشکش۔ تہٕ یوتاہ ٲسۍ مُفت دِل دزنہٕ آمٕتۍ نذرانہٕ۔ {مُقدس...: یا، بٔرِتھ پنُن اَتھ}\n32.\\tتہٕ یُس جمٲژ دِژ تِمن ہُند تعداد اوس تریہ تہٕ داہ بیل، اکھ ہتھ کۅکر، {تہٕ} زٕ ہتھ کۅکرِ بچہٕ: یِم سٲری ٲسۍ خداوند سٕندِ خٲطرٕ زالنہٕ خٲطرٕ۔\n33.\\tتہٕ مقدس چیز ٲسۍ شیہ ہتھ بیل تہٕ ترے ساس کٹہٕ۔\n34.\\tمگر پادٕرۍ ٲسۍ واریاہ کم، یێلہِ تِم ہیوٚک نہٕ سارِنٕے زٲلِتھ نذرانہ تُلِتھ، تێلہِ کٔر تِمن ہٕندِس بٲے لاویو تِمن مدد، یوتام کٲم سپدِ، تہٕ یوتام نہٕ باقٕے پادٕرۍ پان پاک کٔرِتھ، تکیازِ لاوی ٲسۍ پادٕرین ہٕندِ مقابلہٕ پنُن پان پاک کرنہٕ خٲطرٕ زیادٕ دِل دِل۔ {مدد کٔر...: ہیب۔ تِم کٔرِن مضبوٗط}\n35.\\tتہٕ سٍتـ̡ دزنہٕ آمٕژ نذرانہٕ سٍتـ̡ چنانچہ خداوند سٕنزِ گرٕچ خدمت آیہ ترتیب دِنہٕ۔\n36.\\tتہٕ حزقیاہ گۆو خۅش تہٕ سارِنٕے لُکھ خۅش زِ خداین اوس لُکھ تیار کورمُت، تکیازِ یہِ اوس اچانک سپدمُت۔","1. تہٕ حزقیاہ ہن سوُز سارنٕے اسرٲیلِس تہٕ یہوداہ، تہٕ لیکھِن افرائیم تہٕ منسیہس تہِ چِٹھہِ زِ تِم گژھن یروشلمس مَنٛز خداوند سٕندِس گرس مَنٛز یِن، یُس اسرٲیلِکِس خداوند سٕندِس خداہس سٍتـ̡ فسح مناون۔\n2. تکیازِ بادشاہن اوس تہٕ تٔمۍ سٕندِس شہزادن تہٕ یروشلمس مَنٛز سارنٕے جمٲژ ہُند مشورٕ دِژمُت زِ دٔیمِس رٮ۪تس مَنٛز فسح تھاونہٕ خٲطرٕ۔\n3. تِکیازِ تِم ہیوٚک نہٕ تَمہِ وِزِ یہِ برقرار تھٲوِتھ، تِکیازِ پادٕریو اوس نہٕ پنُن پان پوٗرٕ پٲٹھۍپاک کٔرِمُت، تہٕ لُکھ ٲسۍ نہٕ یروشلِمَس مَنٛز جمع گٔمٕتۍ۔\n4. تہٕ یہِ چیز گٔیہِ بادشاہ تہٕ سارِنٕے جمٲژ خۄش۔ {خوش...: ہیب۔ بادشاہ سٕنزِ نظرِ منز اوس صحیح}\n5. چنانچہ تمو کوٚر سارنٕے اسرٲیلِس منز، بیرشبع پیٹھٕ دانس تام اعلان کرنہٕ خٲطرٕ اکھ فرمان قٲیم زِ تِم گژھن یروشلمس مَنٛز اسرٲیلِس کِس خداہس سٍتـ̡ فسح کرنہٕ خٲطرٕ، کیازِ تِمو اوس نہٕ واریاہ کالہٕ سٍتـ̡ یُتھ یہِ لیکھنہٕ آمُت اوس۔\n6. یێمہِ سٍتـ̡ گٔیہِ بادشاہ تہٕ تٔمہِ سٕندِس شہزادن ہٕندِس چِٹھہِ سٍتـ̡ سٲرۍسٕے اسرٲیلِس تہٕ یہوداہ سٕندِس حُکمس مُطٲبِق، یێمہِ سٍتـ̡ بادشاہ سٕندِس حُکمس مُطٲبق وُچھِو، یێلہِ سُہ دُبارٕ ابراہیم، اسحاق تہٕ اسرٲیلِس کِس خداہس کُن پھیرِو۔ {از: ہیب۔ اتھہٕ پیٹھ}\n7. تہٕ گژھِو نہٕ پننین مٲلن ہٕندۍ پٲٹھۍ، تہٕ پننین باین ہٕندۍ پٲٹھۍ، یِمو پننین آباؤ اجدادن ہٕندِس خداہس خلاف زیادٕ جرم کٔر، یِمو تِمن ہٕندِس مٲلس سٍتـ̡ دِژمٕتۍ، یِتھ کٔنۍ تُہۍ وُچھان چھِو۔\n8. وۅنۍ گژھِو نہٕ پننین آباؤ اجدادن ہٕندۍ پٲٹھۍ، بٔلکہِ گژھِو خداوند سٕندِس مقدس مقامس مَنٛز اژُن، یُس تٔمۍ ہمیشہٕ خٲطرٕ پاک کورمُت چھُ، تہٕ خداوند پنُن خدایہ سٕنز عبادت کٔرِو، یُتھ تٔمۍ سٕندِس قہر ہُند شُمار ژٔلِتھ ژٔلِتھ روزِ۔ {بی یے...: ہیب۔ گردن نہ سختی کرُن} {یِلڈ...: ہیب۔ اتھہٕ دِیُو}\n9. یێلہِ یێلہِ تُہٕندِس بٲے تہٕ تُہٕندِس شُرِس سٍتـ̡ یێلہِ تِمن ہٕندِس بٲے تہٕ تُہٕندِس شُرِس سٍتـ̡ رحمت، یێلہِ تِم یێلہِ تُہٕندِس خداہس سٍتـ̡ دُبارٕ یِنہٕ سٍتـ̡ یێلہِ یێلہِ تُہُند خدا چُھہ مہربان تہٕ رحم کرُن، تہٕ یێلہِ تُہٕندِس کُن واپس یِو، تێلہِ گژھہِ نہٕ تُہٕندِس بُتھِس نِش پھیرِ۔\n10.\\tیێلہِ گٔیہِ عہدہ افرایم تہٕ منسیٰ کِس مُلکس مٔنزۍ شہرٕ بیٚیِس شہرس تام، حتیٰ کہ زبولونَس تام، مگر تِمو کٔر تِمن طنز کرنہٕ خٲطرٕ اَسُن، تہٕ تِمن ٹھٹھہٕ کٔرِتھ۔\n11.\\tبہر حال آشر تہٕ منسی تہٕ زبولون ہٕندیو غوطہٕ خورو کٔر پنُن پان عاجز تہٕ آیہ یروشلمس کُن۔\n12.\\tیہوداہَس مَنٛز اوس خدایہِ سُند اَتھٕ یِمن بادشاہ تہٕ شہزادن ہُند حکم دِنہٕ خٲطرٕ اکھ دِل دِنہٕ۔\n13.\\tتہٕ یورشلمس مَنٛز گٔیہِ واریاہ لُکھ جمع یُس دٔیمِس رٮ۪تس مَنٛز خمیرٕ روٚس روٹی ہُند عید مناونہٕ خٲطرٕ، یُس اکھ واریاہ بٔڈ جماعت اوس۔\n14.\\tتہٕ تِم ووٚتھٕ تہٕ نِیُکھ یِم یُس یروشلمس مَنٛز اوس، تہٕ اگربتی خٲطرٕ سارِنٕے قربان گاہ نِش نِتھ تہٕ ترٛٲوِکھ کِڈرونس کِس نالہِ مَنٛز۔\n15. پَتہٕ کٔر تِمو دٔیمِس رٮ۪تہٕ کِس ژۄدٲہِمِس دۅہہٕ فسح مٲرِتھ، تہٕ پادٕرۍ تہٕ لاوی گٔیہِ شرمندٕ، تہٕ کٔرٕکھ پان پاک، تہٕ أنِکھ خداوند سٕندِس گرس مَنٛز زٲلِتھ نذرانہٕ۔\n16.\\tتہٕ تِم کھٔڑۍ پننہِ جایہِ پٲٹھۍ، موسیٰ سٕندِ شریعت مُطٲبق خدایہ سٕندِ شخصہٕ سٕندِ شریعت مطٲبق: پادریو چھُکھ لاوی سٕندِ اتھہٕ سٍتـ̡ خوُن چھُکُن۔ {تہنز جاے: ہیب۔ تہنز حیثیت}\n17.\\tتِکیازِ جمٲژ مَنٛز ٲسۍ واریاہ یِم نہٕ پاک ٲسِمٕتۍ، تێمہِ مۅکھہٕ اوس لاوِین ہٕندِ خٲطرٕ پاسور مارنُک ذمہٕ دِنہٕ آمُت، یُس نہٕ پاک اوس، یُس خداوند سٕندِ خٲطرٕ پاک کرنہٕ آمُت۔\n18.\\tواریاہن لُکن ہٕندِس بٔڈِس سٍتـ̡ اوس نہٕ افریم تہٕ منسیہ، عیساخر تہٕ زبولون سٍتـ̡ پانہٕ پاک کورمُت، توتہِ اوس تِمو فسح لیکھنہٕ بجایہ کھیوٚمُت۔ مگر حزقیاہ ہن کٔر تِمن خٲطرٕ دُعا تہٕ وونُن، خداوند چُھ پریتھ کٲنسہِ معافی دِوان\n19. {یُس} چُھ پنُن دِل خدایہ سٕندِس خدایہِ سٕندِس سٍتـ̡ تلاش کرنہٕ خٲطرٕ تیار کران، یۆدوَے سُہ چُھہ نہٕ مقدس مقامہٕ کِس پاکیزگی مُطٲبق {پاک کرنہٕ}۔\n20. تہٕ خداوند کٔر حزقیاہ سٕنز کتھ بوزن، تہٕ لُکن کٔرٕن شفا۔\n21. تہٕ یُس یروشلمس مَنٛز موجود اوس، تِمو کٔر سَتَن دۅہن خمیرٕ روٚس روٹی ہُند عید سٮ۪ٹھاہ خوشی سان مناون: تہٕ لاوی تہٕ پادٕرۍ ٲسۍ دۅہہٕ دۅہہٕ خداوند سٕنز حمد کران، {بَڑِ سازو سٍت} گیوان ۔ {موجود: ہیب۔ لٔبِتھ} {بَڑ...: Heb. طاقتٕکۍ آلات}\n22. تہٕ حزقیاہ کٔر سارِنٕے لاوِین سٍتـ̡ آرام سان کتھ یِمو خداوند سُند اصل علم ہیچھناوُن: تہٕ تِمو کٔر سَتَن دۅہن کھٮ۪وان، صلح کٔرِتھ تہٕ کٔرٕکھ پننین مٲلن ہٕندِس خداہس سٍتـ̡ اقرار کرنہٕ۔ {آرام سان...: ہیب۔ سارنٕے ہٕندِس دلس تام}\n23.\\tتہٕ سارِنٕے مجلسن کٔر باقی سَتھ دۅہ تھاونُک مشورٕ، تہٕ تِمو تھوو سَتھ دۅہ خۄش گٔژھِتھ۔\n24. یہوداہ کِس بادشاہ حزقیاہ ہن دِژ جماعتس اکھ ساس بیل تہٕ ستھ ساس دانٛد۔ تہٕ شہزادو دِژ جماعتس اکھ ساس بیل تہٕ داہ ساس دانٛد: تہٕ واریہن پادٕرین کٔر پنُن پان پاک۔ {دِیُت: ہیب۔ تھوٚد، یا، پیش کرنہٕ} {دِنہٕ: ہیب۔ تُلِتھ، یا، پیش کٔرِتھ}\n25.\\tتہٕ یہوداہٕچ سارِنٕے جماعت تہٕ پادٕرین تہٕ لاوِین سٍتـ̡ تہٕ سارِنٕے جمٲژ یُس اسرٲیلِہ منزٕ نیران اوس، تہٕ یُس یہوداہ سٍتـ̡ روزان اوس، گٔیہِ خۅش۔\n26.\\tیێلہِ اوس یروشلمس مَنٛز واریاہ خوشی سپدان، تکیازِ یُس اسرٲیلُک بادشاہ داؤد سُند نیچو سلیمان سٕندِ زمانہٕ پیٹھٕ اوس نہٕ یروشلمس مَنٛز یِتھُے ہیوٗ آسان۔\n27.\\tپَتہٕ گٔیہِ پادٕرۍ لاوی ؤتھِتھ تہٕ لُکن دُعا دِژ تہٕ تِہٕنز آواز بوزنہٕ تہٕ تِہٕنز دُعا گٔیہِ تٔمۍ سٕندِس مقدس مکانس کُن، {حتیٰ کہ} جنتس تام۔ {تہند مقدس...: ہیب۔ تقدس سٕنز رہائش گاہ}","1. ییلہ یہ سورُے مُکمل سپدِ، سارِنٕے اِسرٲیل یُس موجودٕ اوس یہوداہ کِس شہرس کُن درٛاوُن، تہٕ ژٔٹِکھ یہوداہ تہٕ بنیامین منزٕ تھدِ جاے تہٕ قربان گاہ، یُس تِمو سارِنٕے تباہ کٔرِ۔ اَمہِ پتہٕ گٔیہِ سارِنٕے بنی اِسرٲیلِس پَنٕنـ̡ شہرن مَنٛز واپس۔ {موجود: ہیب۔ لٔب} {images: Heb. مجسمہٕ} {یوتام ...: ہیب۔ یوتام نہٕ ختم گژھُن}\n2. تہٕ حزقیاہ کٔر پادٕرین تہٕ لاوِین ہٕنزِ خدمتہٕ مُطٲبق، پادٕرۍ تہٕ لاوی زالنہٕ خٲطرٕ تہٕ امن ہٕندِ نذرانہ خٲطرٕ، خدمت کرنہٕ خٲطرٕ، تہٕ شُکر ادا کرنہٕ خٲطرٕ، تہٕ خداوند سٕندِس خیمن ہٕندِس دروازس مَنٛز تعریف۔\n3. {تٔمۍ کوٚر بادشاہ سُند حصہٕ تہٕ دزنہٕ خٲطرٕ، صبحس تہٕ شامٕچ دزنہٕ نذرانہ خٲطرٕ، تہٕ نوِ زونہٕ خٲطرٕ، تہٕ مقرر دعوتن خٲطرٕ، یِتھ کٔنۍ {یہ} خداوند سٕندِس قانونس مَنٛز لیکھنہٕ آمُت چھُ۔\n4. امہِ علاوٕ دِیُت تٔمۍ یروشلمس مَنٛز روزن والٮ۪ن لُکن ہُند حُکُم زِ تِم دِن پادٕرین تہٕ لاوِین ہُند حصہٕ، یُتھ تِمن ہٕندِس شریعتس مَنٛز حوصلہٕ افزٲیی کرنہٕ یِن۔\n5. یێلہِ یہِ حُکُم ووت بێبرِم، بنی اِسرٲیلِو اَن مکایہ، شراب، تیٖل تہٕ ماچھ ہٕندِ گۄڈنِکہِ پھلہٕ تہٕ سارِنٕے کھہَن ہٕندِ ہُند پھلہٕ۔ تہٕ سارِنٕے چیزن ہُند دسُہ دِنہٕ آمُت تِم وافر مقدار منز۔ {آو...: ہیب۔ بریک فورتھ} {ہنی: یا، تٲریخ}\n6. تہٕ یہوداہ کِس شہرن مَنٛز روزن وٲلِس بنی اسرٲیلِس تہٕ یہوداہ سٕندِس سٍتـ̡ تہٕ دِنہٕ آمُت تہٕ مُقدس چیزن ہُند حصہٕ تہٕ یُس خداوند پنہٕ نِس خداہٕ سٕندِ خٲطرٕ وقف کرنہٕ آمُت اوس، تہٕ دِژٕکھ تِمن ہٕندِس ڈھیرس سٍتـ̡ دِنہٕ۔ {by heaps: Heeb. ڈھیر، ڈھیر}\n7.\\tتریمہِ ریتس منز کٔر تِمو ڈھیرٕچ بُنیاد تراوُن شروع، تہٕ سٔتِمِس رٮ۪تس مَنٛز سپٕدۍ مُکمل کرنہٕ۔\n8. تہٕ ییلہ حزقیاہ تہٕ شہزادو آۓ تہٕ ڈھیر وُچھ، تِمو کٔر خداوند تہٕ تٔمۍ سٕندِس لُکہٕ اسرٲیلِس برکت۔\n9.\\tاَمہِ پتہٕ کٔر حزقیاہ پادٕرین تہٕ لاوِین سٍتـ̡ انبارن مُتعلِق پرژھہٕ۔\n10.\\tتہٕ زادوک گرُک سردار پادٕرۍ عزریاہ دیت أمِس جواب تہٕ وونُن، یێلہِ {لوکو} خداوند سٕندِس گرس مَنٛز نذرانہٕ انُن ہیوٚت، اسہِ چُھ سٮ۪ٹھاہ کھٮ۪نہٕ خٲطرٕ سٮ۪ٹھاہ کھٮ۪وان، تہٕ چُھکھ واریاہ زیادٕ تروومُت، کیازِ خداوند چُھ پننین لوکن برکت دِژمٕژ۔ تہٕ یُس باقٕے چُھ {سُہ} یہٕ عظیم دُکان۔\n11. پتہٕ حزقیاہ ہن دِیُت خداوند سٕندِس گرس مَنٛز خانہٕ تیار کرنُک حُکُم۔ تہٕ تِمو کٔر {تِم}، {چیمبرز: یا، ذخیرٕ} تیار\n12.\\tتہٕ أنِن نذرانہٕ تہٕ دہہٕ تہٕ وقف {چیز} وفاداری سان اَننہٕ: یتھ پیٹھ کونونیاہ لاوی {اوس} حکمران، تہٕ شیمی یُس تٔمۍ سُند بوے اوس۔\n13.\\tتہٕ یحییل، تہٕ عززیا، تہٕ ناحت، تہٕ اساہیل، تہٕ یرموتھ، تہٕ یوزآباد، تہٕ ایلیل، تہٕ اسماعیاہ، تہٕ مہاتھ، تہٕ بنیاہ ٲسۍ، کونیاہ تہٕ شمعی سٕندِس بٲے سٕندِس اتھس تل نگران، حزقیاہ بادشاہ سٕندِس حُکمس پیٹھ، تہٕ عزریاہ خدایہ سٕندِس گرٕ سٕندِس حُکمس پیٹھ۔ {انڈر ...: ہیب۔ اتھس پیٹھ}\n14.\\tتہٕ اِمنہ لاوی سُند نیچو، یُس مشرقس کُن قُلِب اوس، خدایہ سٕنزِ قربانی تہٕ مقدس چیزن بٲگراونہٕ خٲطرٕ اوس خدایہ سٕنزِ مرضی ہٕندِس نذرس پیٹھ۔\n15.\\tتہٕ أمِس پَتہٕ ٲسِس عدن، تہٕ منیامین تہٕ یشوعہ، تہٕ شمعیہ، امریہ تہٕ شیکانیاہ، پادٕرین ہٕندِس شہرس مَنٛز، تِمن ہٕندِس مُقرر عہدس مَنٛز، یِمن ہٕندِس بٲے سٍتـ̡ دِنہٕ خٲطرٕ، تہٕ بٔڈِس تہٕ لۄکٹِس تہِ: تٔمۍ سٕنٛدِس اتھس پیٹھ} {سیٹ...: یا، ٹرسٹ}\n16.\\tتِہٕندِس نسب سٍتـ̡ تریہ وُہرۍ پیٹھٕ تہٕ امہِ کھوتہٕ زیادٕ، یُس خداوند سٕندِس گرس مَنٛز دٲخل سپدان چُھ، تٔمِس سُند دوہ دِش چُھہ تِمن ہٕندِس عملس مُطٲبق تِمن ہٕنزِ خدمتہٕ خٲطرٕ تہندِس دۅہدُک حصہٕ۔\n17. پادٕرین ہٕندِس شجرس مُتلق تہٕ وُہن وُہُن وُہُر تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِس شجرس مُطٲبِق۔\n18.\\tتہٕ تِہندین سارنٕے لۄکٹٮ۪ن شُرین، تہنزِ زنانہٕ، تہٕ تِہندین نیچوین تہٕ تِہنزن کورین ہٕندِس شجرس سٍتـ̡ سارِنٕے جمٲژ سٍتـ̡ تکیازِ تِمو کٔر پننِس مُقرر عہدس مَنٛز پاکیزگی سٍتـ̡\n19.\\tہارون سٕندِس نیچوِس سٍتـ̡ پادٕرۍ، {یِم پَنٕنـ̡ شہرن ہٕندِس مضافاتن مَنٛز، پرٮ۪تھ أکِس شہرس مَنٛز، تِمن نفرن ہُند اظہار اوس ناوٕ سٍتـ̡ کرنہٕ آمُت، تہٕ سارِنٕے نَرَن ہُند حِصہٕ دِنہٕ خٲطرٕ، تہٕ سارِنٕے یِمن ہٕندِس شجرس مَنٛز شمار کرنہٕ آمُت اوس۔\n20. تہٕ یِتھٕ پٲٹھـ̡ کٔر حزقیاہ سٲرِسٕے یہوداہَس سٍتـ̡ تہٕ کٔرٕن خداوند سٕندِس خداہس برونہہ کُن نیکی تہٕ صحیح۔\n21. تہٕ پریتھ کامہِ سٍتـ̡ یُس تٔمۍ خدایہِ سٕندِس گرٕ سٕنزِ خدمتہٕ مَنٛز شروع کٔر، تہٕ شریعت تہٕ حُکمن مَنٛز، پَنُن خدایہ سٕندِ سٍتـ̡ حٲصِل کرنہٕ خٲطرٕ کٔرٕن سٍتـ̡ تہٕ کٔرٕن سٍتـ̡ سٍتـ̡ پنہٕ نـ̡","1.\\tیِمو چیزو پتہٕ تہٕ یِمن ہٕندِس قیام پتہٕ، آو اسیریُک بادشاہ سیناچریب، تہٕ یہوداہَس مَنٛز ژاو تہٕ لٔگِتھ لٔگِتھ شہرن خلاف ڈیرٕ ترٲوِتھ تہٕ سونچُن زِ تِم کرِ پانس خٲطرٕ۔ {زیننہٕ خٲطرٕ...: ہیب۔ تمن پھٹراونہٕ خٲطرٕ}\n2. تہٕ ییلہ حزقیاہ وُچھ زِ سینخریب آو آمُت، تہٕ سُہ اوس یروشلمس خلاف جنگ کرنُک ارادٕ تھاوان، {سُہ اوس...: ہیب۔ تٔمۍ سُنٛد بُتھ اوس جنگہٕ خٲطرٕ}\n3.\\tتٔمۍ کٔر پننین شہزادن تہٕ پننین طاقتور نفرن سٍتۍ مشورٕ زِ تِم کٔرِن چشمن ہُند آب رُکاونہٕ خٲطرٕ، یُس شہرٕ ورٲے اوس، تہٕ تِمو کٔر أمس مدد۔\n4.\\tیێمہِ سٍتـ̡ گٔیہِ واریاہ لُکھ جمع یِمو سارِنٕے چشمہٕ تہٕ نالہٕ رُکٲوِتھ یُس زمینس منز وسان اوس، یہِ ونُن زِ اسریاہٕکۍ بادشاہ کیازِ یِن تہٕ واریاہ آب ژھٲنڈِن؟ {ران: ہیب۔ اوور فلو}\n5.\\tتٔمۍ کٔرٕن پانس مضبوط، تہٕ سُہ سورُے دیوار بنٲوِتھ یُس پھُٹمُت اوس، تہٕ تُلِن مینار تہٕ بیاکھ دیوار تہٕ داؤد سٕندِس شہرس مَنٛز کٔرٕن مِلوٕچ مرمت تہٕ بَنووُن وارِیاہ ڈارٕ تہٕ ڈھال۔ {ڈارٹ: یا، تلوار، یا، ہتھیار}\n6.\\tتہٕ تٔمۍ کٔرٕن لُکن ہٕندِس دروازس پیٹھ جنگٕکۍ سردار مقرر تہٕ تِم جمع کٔرِتھ شہر کِس دروازس پیٹھ پانس نِش جمع تہٕ تِمن سٍتـ̡ آرام سان کتھ کٔرِتھ وونُن، {سپک...: ہیب۔ تٔمۍ کٔر تہندِس دلس سٍتۍ کتھ کرنہٕ}\n7. مضبوٗط تہٕ بہادر روزُن، اسریاک بادشاہس سٍتـ̡ گژھ نہٕ خوفزدہ تہٕ نہ خوفزدہ گژھُن، تہٕ نہ گژھ تٔمِس سٍتـ̡ سارِنٕے بٔڈِس سٍتـ̡ یُس أمِس سٍتـ̡ چُھہ زیادٕ:\n8. أمِس سٍتـ̡ چُھہ مازُک نٔر مگر اسہِ سٍتـ̡ چُھہ خداوند سُند خدا یُس اسہِ مدد کرِ، تہٕ سانہِ جنگہٕ لڑنہٕ خٲطرٕ۔ تہٕ لُکھ کٔر یہوداہ کِس بادشاہ حزقیاہ سٕندِس کلامَس پیٹھ آرام ۔ {آرام کٔرِتھ...: ہیب۔ جھکُن}\n9. اَمہِ پَتہٕ سوٗزُن اَشوریا کِس بادشاہ سَناخرِبَن پَنٕنٕنـ̡ خادم یروشلمس کُن، (مگر تٔمۍ کٔر پانہٕ لکیشس تہٕ تٔمِس سٍتـ̡ یُس یہوداہ کِس بادشاہس نِش تہٕ یُس یروشلمس مَنٛز اوس، یہوداہ کِس بادشاہس نِش تہٕ سارِنٕے یہوداہ ہس نِش یُس {طاقت: ہیب}۔ ڈومینین}\n10.\\tیِتھے پٲٹھۍ چُھ اسریاہُک بادشاہ سیناچرب ونان زِ یورشلیم کِس محاصرس منز روزُن کتھ چُھہ تۅہہِ پژھہٕ تھاوان؟ {محاصر: یا، مضبوط ہولڈ}\n11. کیا حزقیاہ چُھہ نہٕ ژیہ قحط تہٕ پیاسہٕ سٍتـ̡ مرنہٕ خٲطرٕ پانس دِنہٕ خٲطرٕ آمادہ کران تہٕ یہِ ونان زِ خداوند سون خدا کرِ اسہِ اسہِ اشوریا کِس بادشاہ سٕندِ اتھہٕ نِش نجات دِنہٕ؟\n12. کیا یێہے حزقیاہ ہن تٔمۍ سٕنزِ تھدِ جایہِ تہٕ قربان گاہ نِش نِتھ یہوداہ تہٕ یروشلمس حکم دِتھ وونُن زِ تُہۍ کٔرِو أکِس قربان گاہَس برونہہ کُن عبادت تہٕ اَتھ پیٹھ بخور زالُن؟\n13.\\tژیہ چھے نہٕ پتاہ زِ میہ تہٕ میانیو مٲلیو کیا کوٚر باقین ملکن ہٕندِس سارنٕے لُکن سٍتۍ؟ کیا تمن زمینن ہندین قومن ہندۍ دیوتا چھا کنہِ تہِ طریٖقہٕ پنن زمین میانہِ اتھہ نِش نِش واتناونس منز ہیوٚک؟\n14. تِمن قومن ہٕندِس سارِنٕے دیوتاہن مَنٛز کُس اوس یُس میانیو مٲلیو پوٗرٕ پٲٹھـ̡ تباہ کٔرِتھ، یُس پننین لوکن میانہِ اتھہٕ نِش بچٲوِتھ، یُس تُہند خدا میانہِ اتھہٕ نِش نجات دِتھ ہێکہِ ہێکہِ؟\n15. تێمہِ کِنۍ گژھہِ نہٕ حزقیاہ ژےٚ دھوکہٕ دِتھ، تہٕ نہ کرِ تۅہہِ اَتھ پٲٹھۍ، تہٕ نہٕ وُنہِ تہِ پژھ کٔرِتھ، تکیازِ کُنہِ تہِ قومُک یا سلطنتُک کانہہ تہِ خدا ہیوٚک نہٕ پننین لوکن میانہِ اتھہٕ نِش تہٕ میانین آباؤ اجدادن ہٕندِ اتھہٕ نِش بچٲوِتھ، تێلہِ ہیوٚک نہٕ تُہند خدا میانہِ اتھہٕ نِش بچٲوِتھ؟\n16.\\tتہٕ تٔمۍ سٕندِس خادمَو کٔر خداوند خدایہ سٕندِس تہٕ تٔمۍ سٕندِس بندس حزقیاہ سٕندِس خٕلافس سٍتـ̡ کتھ کرنہٕ۔\n17.\\tتٔمۍ لیکھۍ چِٹھۍ تہِ زِ یێلہِ چُھہ نہٕ اسرٲیلِکِس خداہس سٍتـ̡ تہٕ أمِس خلاف کتھ کرنہٕ خٲطرٕ، یِتھٕ پٲٹھـ̡ چُھہ نہٕ باقین ملکن ہٕندِیو دیوتاہن پَنٕنـ̡ لُکھ میانہِ اتھہٕ نِش نجات دِژمٕژ، تِتھے پٲٹھـ̡ کرِ نہٕ حزقیاہ سُند خدا پَنٕنـ̡ لُکھ میانہِ اتھہٕ نِش بچاونہٕ۔\n18.\\tتمہِ پتہ کٔر تِمو یہودین ہٕندِس کلامس مَنٛز بَڑِ آوازٕ سٍتـ̡ یِم دیوارس پیٹھ ٲسۍ، تِمن خوفزدہ کرنہٕ خٲطرٕ تہٕ تِمن پریشان کرنہٕ خٲطرٕ۔ تاکہ تم شہر نِتھ۔\n19.\\tتہٕ تِمو کٔر یروشلم کِس خداہس خٕلاف، یِتھ کٔنۍ زٔمیٖنہٕ کین لوکن ہٕندِس دیوتاہن خٕلاف، {یِم انسانہٕ سٕندِ اتھن ہٕنز کٲم ٲسۍ۔\n20.\\tتہٕ اَمہ مۅکھہٕ کٔر حزقیاہ بادشاہ تہٕ اموزُک نیچو یسعیاہ پیغمبرن دُعا تہٕ جنتس کُن دُعا کٔرِتھ۔\n21.\\tتہٕ خداوند سوٗز اکھ فرشتہٕ، یٔمۍ سارِنٕے بہادر نفر تہٕ اسریہٕ کِس بادشاہ سٕندِس خٲمس مَنٛز رہبر تہٕ سردار ژٹِتھ ژٔٹۍ۔ چنانچہ سُہ آو شرمندگی ہٕندِس بُتھِس سٍتۍ پننِس زمینس کُن واپس۔ تہٕ ییلہ سُہ پننِس خدایہ سٕندِس گرس منز آو، یِمو تٔمۍ سٕندِس پنہٕ نِس أنٛدرٕ منزٕ نیبر نیرِتھ مارُکھ سُہ تلوار سٍتـ̡ ۔ {سلیو...: ہیب۔ سُہ پیوٚو سُہ پیوٚو}\n22. یِتھٕ پٲٹھـ̡ بچٲو خداوند حزقیاہ تہٕ یروشلمٕکۍ بسکین، یُس اسریاہُک بادشاہ سناخریب سٕندِ اتھہٕ نِش تہٕ سارِنٕے {باقی} سٕندِ اتھہٕ نِش بچٲوِتھ تہٕ تِمن ہٕنز رہنُمٲیی کٔرٕنـ̡ ۔\n23.\\tتہٕ واریاہ لوگ أنۍ خداوند سٕندِ خٲطرٕ یروشلمس مَنٛز تحفہٕ، تہٕ یہوداہ کِس بادشاہ حزقیاہ سٕندِس خٲطرٕ تحفہٕ، یُتھ سُہ تَمہِ پتہٕ سارنٕے قومن ہٕندِس نظرس منز بڑاونہٕ آو۔ {پیش کران: ہیب۔ قیمتی چیز}\n24.\\tتِمن دۅہن اوس حزقیاہ مرنس تام بیمار تہٕ کٔرٕن خداہس سٍتـ̡ دُعا تہٕ تٔمِس کٔرٕن أمِس سٍتـ̡ کتھ تہٕ دِژ أمِس اکھ نشانہٕ۔ {دِیُت...: یا، أمِس خٲطرٕ کٔرُن اکھ معجزہٕ}\n25.\\tمگر حزقیاہ ہُند دُبارٕ دِیُت نہٕ أمِس فٲیدٕ مُطٲبق۔ تکیازِ تٔمۍ سُند دِل اوس تُلنہٕ آمُت، تێمہِ کِنۍ اوس أمِس تہٕ یہوداہ تہٕ یروشلمس پیٹھ غصہٕ۔\n26. حزقیاہ کٔر پننِس دِلہٕ کِس غرورٕ خٲطرٕ عاجزی کٔرِتھ، یُتھ زن حزقیاہ سٕندِس دۅہَس مَنٛز خداوند سُند قہر ووت نہٕ۔ {فخر: ہیب۔ تُلُن}\n27.\\tتہٕ حزقیاہ ہس ٲس واریاہ دولت تہٕ عزت، تہٕ تٔمۍ بنوو پانس رۄپہٕ تہٕ سۄنہٕ خٲطرٕ، تہٕ قیمتی پتھرن خٲطرٕ، مصالحہٕ خٲطرٕ، تہٕ ڈھالن خٲطرٕ تہٕ پرٮ۪تھ قٕسمٕک خۄشگوار جواہرات خٲطرٕ خزانہٕ۔ {خوشگوار...: ہیب۔ خواہشکۍ آلات}\n28. مکایہ، شراب تہٕ تیلٕچ اضافہٕ خٲطرٕ تہٕ ذخیرٕ۔ تہٕ پرٮ۪تھ قٕسمٕک درندَن ہٕندِ خٲطرٕ دُکان، تہٕ کھورِ ہٕندِ خٲطرٕ کُٹھ۔\n29.\\tامہِ علاوٕ دِژ تٔمِس شہر، تہٕ ریوڑ تہٕ چارٕچ جایداد وافر زیادٕ، تکیازِ خداین اوس أمِس واریاہ چیز دِژمُت۔\n30.\\tامی حزقیاہ ہن رُکٲوُن گیہونُک پیٹھم آبہٕ تہِ تہٕ أنِن سیوٚدُے داؤد شہر کِس مغربس کُن۔ تہٕ حزقیاہ کٔر پننین تمام کامین منز کامیاب۔\n31.\\tبابل کین شہزادن ہٕندِس سفیرن ہٕندِس کاربارس منز، یِمو أمِس نِش زمینس مَنٛز سپدن وٲلِس عجائب سٍتـ̡ پرژھہٕ گٲر کرنہٕ خٲطرٕ سوزمُت، خداین تروو أمِس آزماونہٕ خٲطرٕ، یُس تٔمِس دِلس مَنٛز سارِنٕے چیٖز زانہِ۔ {سفیر: ہیب۔ ترجمان}\n32.\\tوۅنۍ چھِ حزقیاہ سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕنزِ نیکی یِسعیاہ سٕندِس وژنس مَنٛز لیکھنہٕ آمٕژ، یُس اموز سُند نیچو چھُ، {تہٕ} یہوداہ تہٕ اسرٲیلٕکۍ بادشاہن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت۔ {نیکی: ہیب۔ مہربانی }\n33.\\tحزقیاہ گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ تِمو کٔر سُہ داؤد سٕندِس نیچوین ہٕندِس قبرس مَنٛز دفن تہٕ سارِوٕے یہوداہ تہٕ یروشلم کین بسکینو کٔر أمِس مرنہٕ وِزِ احترام۔ تہٕ تٔمۍ سٕندِس نیچوِس منسیٰ سٕندِ بدلہٕ کٔر حکومت۔ {چیفیسٹ: یا، تھزر}","1. منسیٰ اوس بَہہ وُہُر ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز پنژاہ تہٕ پانژاہن ؤرین ہٕنز حکومت۔\n2. مگر یُس خداوند سٕندِس نظرس منز بُرٕ اوس، یِتھٕ پٲٹھۍ، یُس خداوند بنی اسرٲیلِس برونہہ کُن کڈمُت اوس۔\n3. تکیازِ تٔمۍ کٔر تِم تھدِ جایہِ یِم حزقیاہ تٔمۍ سٕندِس مٲلہِ سٕندِس مٲلہِ سٍتـ̡ پھُٹرٲومٕژ ٲس، تہٕ تٔمۍ کٔرٕن بعلیم خٲطرٕ قربان گاہ تہٕ باغہٕ بنووُن تہٕ کٔرٕن جنتٕچ سارِنٕے لشکرٕچ پوجا تہٕ تِہنز خدمت کٔرٕن۔ {تم بنوو...: ہیب۔ سُہ آو واپس تہٕ تعمیر کٔر}\n4. تٔمۍ بنوو خداوند سٕندِس گرس مَنٛز قربان گاہ، یَتھ مَنٛز خداوند اوس ووٚنمُت، یروشلمس مَنٛز گژھہِ میون ناو ہمیشہٕ خٲطرٕ۔\n5. تہٕ تٔمۍ بنوو خداوند سٕندِس گرٕ کِس دۄن آنگنن مَنٛز جنتٕہ کِس سارنٕے فوجہٕ خٲطرٕ قربان گاہٕ۔\n6. تہٕ تٔمۍ کٔر پننین شُرین ہِنوم سٕندِس نیچو سٕنزِ وادی مَنٛز نارس مَنٛز۔ تہٕ تٔمۍ کٔر زمانہٕ وُچھن، تہٕ جادوگری ہُند استعمال تہٕ جادوگری ہُند استعمال، تہٕ أکِس مانوس روحس سٍتـ̡ تہٕ جادوگرن سٍتـ̡ سٍتـ̡ سٍتـ̡ کٔرٕن سٍتـ̡ بد کار سپدان۔\n7. تہٕ تٔمۍ بنوو اکھ نقش و نگار مجسمہٕ، یُس تٔمۍ خدایہ سٕندِس گرس مَنٛز بنوومُت اوس، یُس خدایہ داؤدس تہٕ تٔمۍ سٕندِس نیچوِس سلیمانس وونمُت اوس، یتھ گرس مَنٛز، تہٕ یروشلمس منز، یُس میہ سارِنٕے اسرٲیلِس قبیلن برونہہ کُن ژٲرمُت چُھ، بہٕ تھاوٕ پنُن ناو ہمیشہٕ خٲطرٕ:\n8. بہٕ کٔرٕ نہٕ وُنہٕ تِمن زمینہٕ منزٕ یُس میہ چُھہ تہندٮ۪ن مٲلن ہٕندِ خٲطرٕ مقرر کورمُت چھُ۔ یُتھ زن تِم موسیٰ سٕندِ اتھہٕ سٍتـ̡ پوٗرٕ قونوٗن تہٕ قونونن تہٕ احکامَن مُطٲبِق تِمن سُند حُکُم دِنہٕ آمُت چھُ۔\n9.\\tیێوَن بنوو یہوداہ تہٕ یروشلم کین بسکینن غلطی کرنہٕ، تہٕ بێیہِ بێیہِ بێسٍتـ̡ بدتر کٲم کرنہٕ خٲطرٕ، یُس خداوند بنی اسرٲیلـ̡ برونہہ کُن تباہ کورمُت اوس۔\n10.\\tتہٕ خداوند کٔر مناسی تہٕ تٔمۍ سٕندِس لُکن سٍتـ̡ کتھ مگر تِمو بوز نہٕ۔\n11. تێمہِ کِنۍ اوٚن خداوند تِمن پیٹھ اَسِریاہٕکۍ بادشاہ سٕندِ لشکرٕکۍ کپتان، یِمو منسیٰ کِس کانٹَن مَنٛز نِیُن تہٕ زنجیر لٲگِتھ تہٕ نِن سُہ بابل کُن۔ {بادشاہ سٕندِس: ہیب۔ کُس بادشاہ سٕندِس {زنجیرٕ: یا، زنجیر}\n12. تہٕ یێلہِ سُہ مُصیبت اوس، تٔمۍ کٔر خداوند پنُن خدا، تہٕ کوٚرُن پننین مٲلن ہٕندِس خداہس برونہہ کُن پنُن پان سٮ۪ٹھاہ عاجزی،\n13.\\tتہٕ کٔرٕن أمِس دُعا دعا، تہٕ أمِس کٔرٕن أمِس نِش گُزٲر تہٕ تٔمۍ سٕنز دُعا بوٗزِتھ تہٕ أنِن سُہ دُبارٕ یروشلم پنہٕ نِس سلطنتس مَنٛز۔ امہ پتہ اوس مناسی پتہ زِ خداوند چھہ خدا۔\n14.\\tامہ پتہ بنوو تٔمۍ داؤد شہرٕ ورٲے، گیہون کِس مغربس کُن، وادی منز، گاڈٕ دروازس تام تہِ اکھ دیوار، تہٕ اوفیلس اندۍ پٔکھۍ تھزر، تہٕ تھووُن واریاہ تھزر، تہٕ تھووُن یہوداہ کین سارنٕے تارن منز جنگٕکۍ کپتان۔ {اوفیل: یا، ٹاور}\n15. تہٕ تٔمۍ نِن عجیب دیوتا، تہٕ بُت خداوند سٕندِ گرٕ منز، تہٕ تِم سٲری قربان گاہ یِم تٔمۍ خداوند سٕندِس گرٕ کِس پہاڑس مَنٛز تہٕ یروشلمس مَنٛز بنٲومٕتۍ ٲسۍ، تہٕ کٔرِن شہرٕ منزٕ کٔرِتھ۔\n16.\\tتہٕ تٔمۍ کٔر خداوند سٕندِ قربان گاہٕچ مرمت تہٕ اَتھ پیٹھ کٔرٕن امن ہٕنز قربانی تہٕ شُکریہ ادا کرنُک حُکُم۔\n17. بہر حال لوکو کٔر وُنہِ تہِ تھدٮ۪ن مقامن پیٹھ قربانی، {توتہِ} خداوند سٕندِ خدایہ سٕندِ خٲطرٕ۔\n18.\\tوۅنۍ چُھہ مانسیہ سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِس خدایہ سٕندِس خداہس سٍتـ̡ دُعا تہٕ یِمن ہٕندِس خدایہِ سٕندِس ناوٕ سٍتـ̡ أمِس سٍتـ̡ کتھ کرنہٕ آمٕژ چھِ، وُچھِو یِم اسرٲیلِکۍ بادشاہن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n19.\\tتٔمۍ سٕندِس دُعا سٍتـ̡ تہٕ کِتھہ پٲٹھـ̡ خدایہِ سٕندِس سٍتـ̡ پى۪ٹھـ̡ {دی سیئرز: یا، ہوسائی}\n20. یێمہِ کِنۍ شوٚنگُن پننِس مٲلِس سٍتـ̡ تہٕ تِمو کٔر أمِس پننِس گَرَس مَنٛز دفن۔\n21.\\tامون اوس زٕ وُہُر وُہُر ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ یروشلمس مَنٛز کٔرٕن دۄن ؤرین ہٕنز حکومت۔\n22.\\tمگر تٔمۍ کٔر خداوند سٕندِس نظرس منز یُس بُرٕ اوس، یِتھٕ کٔنۍ تٔمۍ سٕندِس مٲلِس منسیٰ سٕندِس مٲلِس سٍتـ̡ بٔنِتھ تہٕ کٔرٕن تِمن ہٕنزِ خدمت۔\n23.\\tتہٕ کٔرٕن نہٕ خداوند سٕندِس برونہہ کُن پنُن پان عاجز کٔرِتھ، یِتھ کٔنۍ تٔمۍ سٕندِس مٲلہِ منسیٰ سٕندِس مٲلِس سٍتـ̡ عاجزی کٔرمٕژ۔ مگر ایمون اوس زیادٕ کھۅتہٕ زیادٕ ناجائز قبضہ کران۔ {زیادٕ کھوتہٕ زیادٕ: ہیب۔ ضرب شدہ تجاوز}\n24.\\tتہٕ تٔمۍ سٕندٮ۪و نوکرو کٔر أمِس خلاف سٲزِش، تہٕ مارُکھ سُہ پننِس گرس منٛز۔\n25.\\tمگر زمینہٕ کیو لوکو مارۍ تِم سٲری یِمو بادشاہ آمونس خلاف سٲزش ٲس کٔرمٕژ۔ تہٕ زمینہٕ کیو لوکو بنوو یوسیاہ سٕندِ بدلہٕ پنُن نیچو بادشاہ۔","1. یوشیا اوس ٲٹھ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز اکھ ترہ ؤری حکومت۔\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرِ سٍتـ̡ صحیح، تہٕ پٔکِن پننِس مٲلہِ داؤد سٕنزِ وتہِ پى۪ٹھ، تہٕ دٔچھنِس کُن تہٕ کھوورِ طرفہٕ انکار کٔرُن۔\n3. تکیازِ پننہِ حکومتہٕ کِس ٲٹھمِس ؤریس منز، ییلہ سُہ جوان اوس، تٔمۍ ہیوٚت پننِس مٲلس داؤد سٕندِس خداہس سٕنز تلاش کرٕنۍ، تہٕ بٔہمہِ ؤریس مَنٛز کٔر تٔمۍ یہوداہ تہٕ یروشلم تھزرو جاین تہٕ باغو نِش صاف کرُن شروع۔\n4.\\tتہٕ تِم چھِ أمِس سٕندِس حضورس منز بعلِم کِس قربان گاہَس پھُٹراوان ۔ تہٕ تِم تصویرٕ، یِم {ٲس} تِمن پیٹھٕ تھزرس پیٹھ، تٔمۍ ژٔٹۍ۔ تہٕ باغ، تہٕ کھنمٕژ تصویرٕ، تہٕ پگھلِمٕژ تصویرٕ، تٔمۍ کٔر ٹُکرٕ ٹُکرٕ تہٕ تِمن ہٕنزِ قبرن پیٹھ لٔگِتھ یِمو تِمن خٲطرٕ قربانی دِژمٕژ ٲس۔ {تصویر: یا، آفتاب تصویر} {قبر: ہیب۔ قبرن ہند بُتھ}\n5. تہٕ تٔمۍ زٲلِن پادٕرین ہٕنزِ أڈجہِ تہٕ یہوداہ تہٕ یروشلم پاک کٔرِتھ۔\n6. تہٕ یِتھے کٔرِتھ اوس منسیہ، افرائیم تہٕ شمعون شہرن مَنٛز، حتیٰ کہ نفتالی تام تہٕ تِمن ہٕندِس چٹخس اندۍ پٔکھۍ۔ {میٹاکس: یا، مولز}\n7. تہٕ ییلہ تٔمۍ قربان گاہ تہٕ باغہٕ پھُٹرٲوِتھ تہٕ کھٔنِتھ بُتٕہ ژٔٹِتھ تہٕ سارِنٕے سرزمینس منز سارِنٕے بُت ژٹِتھ ژٔٹِتھ دِژٕن، سُہ آو یروشلمس کُن واپس۔ {into...: Heb. پاؤڈر بناونہٕ خٲطرٕ}\n8.\\tپننہِ بادشاہی ہٕندِس اردٲہمہِ ؤریس منز، ییلہ تٔمۍ زمینہٕ تہٕ گرٕ صاف کٔرۍ، تٔمۍ سوٗزُن عزالیہ سُند نیچو شافان، تہٕ شہرُک حاکم ماسییاہ تہٕ جوہاز سُند نیچو، خداوند سُند خدایہ سُند گرٕ مرمت کرنہٕ خٲطرٕ۔\n9.\\tییلہ تِم ہلکیاہ کِس پادٕرس نِش وٲتۍ، تِمو واتنوو سُہ پونسہٕ یُس خدایہ سٕندِس گرس مَنٛز اننہٕ اوس آمُت، یُس دروازٕ رٲچھ کرن والیو منسی تہٕ افرائیم سٕندِ اتھہٕ سٍتـ̡ تہٕ سارِنٕے یہوداہ تہٕ بنیامین سٕندِ اتھہٕ سٍتـ̡ جمع کورمُت۔ تہٕ تِم آیہ یروشلم واپس۔\n10.\\tتہٕ تِمو تھووُکھ تِمن کامگارن ہٕندِس اتھس مَنٛز یِم خداوند سٕندِس گرس پیٹھ نظر تھاوان ٲسۍ، تہٕ تِمو دِژ تِمن کامگارن یِم خداوند سٕندِس گرس مَنٛز کٲم کران ٲسۍ، گرٕچ مرمت تہٕ ترمیم کرنہٕ خٲطرٕ۔\n11. حتیٰ کہ کاریگرو تہٕ معمارو تہِ دِژ تِم ژٔٹِتھ کٔنہِ تہٕ جوڑنہٕ خٲطرٕ لٔکٕر مٔلۍ ہینہٕ خٲطرٕ، تہٕ تِم مکانہٕ یِم یہوداہ کٮ۪و بادشاہو تباہ کٔرۍمٕتۍ ٲسۍ۔ {فرشس پیٹھ: یا، رافٹر کُن}\n12.\\tتہٕ مردو کٔر وفاداری سان کٲم تہٕ یِمن ہٕندِس نگراں ٲسۍ جہاد تہٕ عوبدیہ، یُس میراری ہٕندٮ۪ن نیچوین ہٕندِس لاوی ٲسۍ۔ تہٕ زکریا تہٕ مشولم، کوہثین ہٕندٮ۪ن نیچوین سٍتۍ، برونہہ کُن تھاونہٕ خٲطرٕ۔ تہٕ {باقٕے} لیوی، یم سٲری موسیقی ہٕندِس آلاتس ہٕنز مہارت ہٲوِتھ۔\n13.\\tتہِ ٲسۍ {تِم} بوجھ تُلنہٕ والٮ۪ن تہٕ سارِنٕے سارِنٕے کُنہِ تہِ طریقس مَنٛز کٲم کَرن وٲلِس نگران، تہٕ لاوِین ہٕندِس سٍتـ̡ ٲسۍ کاتب، افسر تہٕ قلی آسان۔\n14.\\tتہٕ ییلہ تِمو پٲنسہٕ کٔڈِتھ یُس خداوند سٕندِس گرس مَنٛز اننہٕ اوس آمُت، حِلکیا پادٕرۍ وُچھ موسیٰ سٕندِ دٔسۍ خداوند سٕنزِ شریعت ہٕنز اکھ کتاب ۔ {by: Heb. اتھہٕ سٍتۍ }\n15.\\tتہ حلقیہ دیت جواب تہ وونُن شافانس کاتب زِ میہ لوٚب شریعتچ کتاب خداوند سٕندِس گرس منز۔ تہٕ حلکیہ واتنوو کتاب شافنس تام۔\n16.\\tتہٕ شافان واتنوو کتابہ بادشاہس نِش، تہٕ وونُن بادشاہ سُند کلام واپس تہٕ وونُن زِ یُس سٲری چُھہ تہندٮ۪ن خدمتگارن سٍتـ̡ دِنہٕ آمُت، سُہ چُھ تِم کران۔ {تُہٕندِس کُن...: ہیب۔ اتھس تام، وغیرہ}\n17. تہٕ تِمو چُھ خداوند سٕندِس گرس مَنٛز لبنہٕ آمُت پٲنسہٕ جمع کٔرِتھ، تہٕ چُھکھ نگرانن ہٕندِس اتھس تہٕ کامگارن ہٕندِس اتھس تام واتنوومُت۔ {جمع گٔیہِ: ہیب۔ نیبر کٔرتھ، یا پگھلۍ}\n18.\\tپتہٕ ووٚن شافان کاتب بادشاہس زِ ہلکیا پادٕرۍ چھے مے اکھ کتاب دِژمٕژ۔ تہٕ شافانن پٔر یہ بادشاہس برونہہ کنہِ۔ {یہ: ہیب۔ اتھ منز}\n19.\\tتہٕ ییلہ بادشاہن شریعت ہٕنز کتھ بوز، سُہ کٔرِن پَنٕنۍ پَلَو کٔرِتھ۔\n20.\\tتہٕ بادشاہن دِیُت حلقیاہ، تہٕ شافان سُند نیچو احیکام، تہٕ میکاہ سُند نیچو عبدون تہٕ شافان کاتب تہٕ عسیاہ بادشاہ سٕندِس نوکر سُند حُکُم دِتھ وونُن، {عبدون: یا، اچبور}\n21. گژھ، میانہِ خاطرہ تہٕ یُس اسرائیلس تہٕ یہوداہَس مَنٛز باقٕے روزان چھِ، یُس کتابہ ہٕندِس کلامس مُتلق پرژھہِ: یُس اسہِ پیٹھ وُچھمُت چُھ، کیازِ سانٮ۪و آباؤ اجدادو چُھنہٕ خداوند سُند کلام برقرار تھاونہٕ آمُت، یُس اتھ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ۔\n22.\\tتہٕ ہلکیاہ، تہٕ {تِم} یُس بادشاہن {مقرر کورمُت}، گٔیہٕ حلدہ پیغمبرن نِش، یُس شلوم سٕنز زنانہٕ، یُس تِکواتھ سُند نیچو اوس، یُس ہسرہ سُند نیچو اوس، یُس المارِ ہُند رٲچھ کرن وول اوس۔ (وۅنۍ ٲس سۅ یروشلمس منز کالجس منز روزان:) تہٕ تمو کٔر أمس سٍتۍ اتھ {اثر} پیٹھ کتھ کرنہٕ۔ {حسرہ: تہِ ونان چھہِ ہرہاس} {وارڈروب: ہیب۔ لباس} {کالجس منز: یا، سکولس منز، یا، دوٚیمس حصس منز}\n23. تہٕ تٔمۍ دیُت تِمن جواب، یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند وَنُن وَنُن یُس ژے میانہِ نِش سوزمُت چھُ،\n24. یِتھٕ پٲٹھـ̡ چُھہ خداوند فرماوان، وُچھِو بہٕ یَتھ جایہِ تہٕ اَتھ کِس بسکینس پیٹھ تہٕ تِمن سارِنٕے لعنتَن ہُند یُس تِمو یہوداہ کِس بادشاہس برونہہ کُن پٔرِمُت چُھ، یُس تِمو کِس کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، یُس تِمو یہوداہ کِس بادشاہس برونہہ کُن پٔرِمُت چھُ:\n25. کیازِ تِمو چُھ مے ترٲومُت، تہٕ باقین دیوتاہن خٲطرٕ چُھکھ بخور زٲلمُت، یُتھ زن تِم پنہٕ نِس سارِنٕے کامہِ سٍتـ̡ مے شرارت ہُند شکار کٔرِتھ۔ تَمہِ کِنۍ گژھہِ میون قہر یَتھ جایہِ تراونہٕ، تہٕ یِیہِ نہٕ ژھٹنہٕ۔\n26.\\tیێلہِ یہوداہ کِس بادشاہس سٍتـ̡ یُس تۅہہِ خداوند سٕندِس سٍتـ̡ پرژھہٕ گٲر کرنہٕ خٲطرٕ سوزمُت چُھ، تِتھٕ پٲٹھـ̡ چُھہ تٔمِس وَنُن یِتھٕ پٲٹھـ̡ اسرٲیلُک خداوند خداوند چُھہ تِمن کلامَن مُتلق یُس ژے بوزمُت چُھہ ۔\n27.\\tتکیازِ تُہند دِل اوس نرم تہٕ ژے کٔرٕکھ خدایہِ سٕندِس برونہہ کُن عاجزی، یێلہِ ژے یێمہِ جایہ تہٕ یێمہِ ہٕندِس بسکینس خٕلاف تٔمۍ سٕنز کتھ بوز، تہٕ کٔرٕکھ میانہِ برونہہ کُن پنُن پان عاجز تہٕ پَنُن پلو ژٔٹِتھ تہٕ روُن میانہِ برونہہ کُن۔ خداوند چُھ ونان زِ مے چُھ {تُہہ} تہِ بوزمُت۔\n28. وچھ بہٕ ژے پننین مٲلن نِش جمع کٔرِتھ، تہٕ ژٕ گژھ امن سان پننہِ قبرِ تام جمع کرنہٕ، تہٕ نہ گژھ چانہِ أچھ وُچھن سٲرِی بُرٲیی یُس بہٕ یَتھ جایہِ تہٕ اَمہ کِس روزن والٮ۪ن پیٹھ اَننہٕ یِوان۔ چنانچہ تِمو اوٚن بادشاہ سُند لفظ بییہِ۔\n29. پتہٕ سوٗزۍ بادشاہن یہوداہ تہٕ یروشلمٕکۍ سٲری بزرگ جمع کٔرِتھ۔\n30. تہٕ بادشاہ ووت خداوند سٕندِس گرس مَنٛز، تہٕ یہوداہٕکۍ سارِنٕے مرد، یروشلمٕکۍ بسکین، تہٕ پادٕرۍ، لاوی تہٕ سارِنٕے لُکھ بٔڈۍ تہٕ لۄکٕٹۍ، تہٕ تٔمۍ پٔرِن تِہندین کنن مَنٛز عہد کِس کتابہِ ہٕندۍ سٲری لفظ یُس خداوند سٕندِس گرس مَنٛز لبنہٕ آو۔ {عظیم...: ہیب۔ بڈِ پیٹھہ لۅکٹۍ تام تہِ}\n31. تہٕ بادشاہ کٔر پننہِ جایہِ کھڑا تہٕ کوٚرُن خداوند سٕندِ برونہہ کُن اکھ عہد زِ سُہ کرِ خداوند سٕندِ پتہٕ پَکُن، تہٕ تٔمۍ سٕندِس حکمس تہٕ گوٲہی تہٕ پنٕنـ̡ قونونن ہٕندِس پوٗرٕ دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ یِم اتھ کتابہِ منز لیکھنہٕ آمٕتۍ چھِ۔\n32.\\tتہٕ تٔمۍ کٔر یروشلمس تہٕ بنیامین سٍتـ̡ سارِنٕے موجودٕ سٍتـ̡ کھڑا کرنہٕ۔ تہٕ یروشلم کین بسکینو کٔر خدایہ سٕندِس معاہدس مطٲبق، یُس پننین مٲلن ہُند خدا۔ {موجود: ہیب۔ لٔب}\n33.\\tتہٕ یوسیاہ کٔر سارِنٕے مُلکو منزٕ سارِنٕے مُلکو نِش یِم بنی اسرٲیلِس سٍتـ̡ ٲسٕن، تہٕ بنووُن سارِنٕے یُس اسرٲیلِس مَنٛز موجود اوس، یێمہِ سٍتـ̡ خداوند سٕندِس خدایہِ سٕنز خدمت کرنہٕ مۅکھہٕ۔ {تہٕ} تٔمۍ سٕندِس سارِنٕے دۅہس منز رودۍ نہٕ تِم پننین مٲلن ہٕندِس خدایہِ سٕنزِ پیروی کرنہٕ نِش۔ {موجود: ہیب۔ لبنہٕ آمُت} {منز...: Heb. پتہٕ پیٹھ}","1. امہِ علاوٕ تھوو یوسیاہ یروشلمس منز خداوند سٕندِ خٲطرٕ فسح تہٕ تِمو کوٚر گۄڈنِکِس رٮ۪تہٕ کِس ژۄدٲہمہِ دۅہہٕ فسح مٲرِتھ۔\n2. تہٕ تٔمۍ کٔرٕن پادٕرۍ تِمن ہٕندِس اِنتِظامس مَنٛز تہٕ دِژٕن خداوند سٕندِس گرٕ سٕنزِ خدمتہٕ خٲطرٕ حوصلہٕ افزٲیی۔\n3.\\tتہٕ وونُن لاوِین یِمو سارِنٕے اسرٲیلِس ہیچھناوُن، یُس خداوند سٕندِ خٲطرٕ پاک اوس، تِم تھٲوِن تتھ گرس مَنٛز یُس سُلیمان، یُس اسرٲیلِکِس بادشاہ داؤد سٕندِس نیچوِس سُلیمانن بنوومُت اوس۔ {یہِ} گژھِ نہٕ {پننِس پھیکس پیٹھ} بوج: وۅنۍ کرو خداوند پنُن خدا، تہٕ تٔمۍ سٕندِس قومس اسرٲیلٕچ خدمت،\n4. تہٕ پَنٕنـ̡ پۯاوٕنـ̡ پى۪ٹھـ̡ پى۪ٹھ، اسرٲیلِکِس بادشاہ داؤد سٕندِس تحریرس مُطٲبق تہٕ تٔمۍ سٕندِس نیچوِس سُلیمان سٕندِس تحریرس مُطٲبق کٔرِو پَنٕنـ̡ پَنٕنـ̡ پى\n5. تہٕ پَنٕنـ̡ بٲے سٕندِس باپَن ہٕندِس خاندانن ہٕنزِ تقسیمہٕ مُطٲبق تہٕ لاوِین ہٕندِس خاندانن ہٕنزِ تقسیمہٕ مُطٲبق رٔٹِو مُقدس۔ {بابن ہٕندِ خاندان: ہیب۔ فادرن ہُند گرٕ} {لوک: ہیب۔ عوامک نیچو}\n6. تێمہِ پٲٹھـ̡ کٔرِو فسح تہٕ پان پاک کٔرِو، تہٕ پَنٕنـ̡ بٲے تیار کٔرِو، یُتھ {تِم} موسیٰ سٕندِ اتھہٕ سٍتـ̡ خداوند سٕندِ کلامَس مُطٲبق کٔرِتھ۔\n7. تہٕ یوسیاہ ہن دِیُت لُکن تہٕ کۅکرِ ہٕندِس لُکن تہٕ بچہٕ، سارِنٕے سارِنٕے ساس تہٕ ترٚے ساس بیلن ہٕندِس تعدادس تام۔ {دِیُت: ہیب۔ پیش کٔرِتھ}\n8. تہٕ تٔمۍ سٕندٮ۪و شہزادو دِژ پننہِ مرضی سٍتـ̡ لوکَن، پادٕرین تہٕ لاوِین دِژٕن: حِلکیا تہٕ زکریا تہٕ یہیل، یِم خدایہِ سٕندِ گرٕکۍ حُکُمران ٲسۍ، دِژ پادٕرین زٕ ساس شیہ ہتھ تہٕ ترے ہتھ بیل۔ {رضامندی سان دِژمُت: ہیب۔ پیش کٔرِتھ، وغیرہ}\n9.\\tکونیاہ تہٕ شمعیاہ تہٕ نیتھانیل، تٔمۍ سٕندِس بٲے تہٕ حشبیاہ تہٕ جیئل تہٕ یوزآباد، یُس لاوِین ہُند سردار اوس، دِژ لاوِین پانژھ ساس تہٕ پانژھ ہتھ بیل۔ {دِیُت: ہیب۔ پیش کٔرِتھ}\n10. یێمہِ کِنۍ گٔیہِ خدمت تیار تہٕ پادٕرۍ گٔیہِ پننہِ جایہِ تہٕ لاوی گٔیہِ بادشاہ سٕندِ حُکمہٕ مُطٲبِق۔\n11. تہٕ تِمو مٲرِتھ فسح تہٕ پادٕریو چھُکھ پننیو اتھو سٍتـ̡ خوُن، تہٕ لاویو کٔر تِمن کھال۔\n12.\\tتہٕ تِمو کٔر دزنہٕ آمٕژ نذرانہٕ، یُتھ زن تِم لُکن ہٕندِس خاندانن ہٕندِس تقسیمہٕ مُطٲبق خداوند سٕندِ خٲطرٕ پیش کرنہٕ خٲطرٕ دِنہٕ یِتھ، یِتھ کٔنۍ زَن موسیٰ سٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ۔ تہٕ یِتھے پٲٹھۍ کٔر تِمو بیلن سۭتۍ۔\n13.\\tتہٕ تِمو کٔرٕکھ فسح نارٕ سٍتـ̡ {تقسیم...: ہیب۔ تِمَن دِیُن دِیُت}\n14. تہٕ امہِ پتہٕ کٔر تِمو پانس تہٕ پادٕرین ہٕندِ خٲطرٕ تیار، تکیازِ ہارون سٕندِ نیچوۍ ٲسۍ رٲژ تام دزنہٕ نذرانہ تہٕ چربی پیش کرنس منز آوٕر۔ تێمہِ کِنۍ کٔر لاویو پانس تہٕ کاہنن ہٕندِ خٲطرٕ ہارون سٕندِ نیچوۍ تیار۔\n15.\\tتہٕ داؤد سٕندِ حُکمہٕ مُطٲبق گٔیہِ آصاف سٕندِ نیچو تہٕ یدوتون بادشاہ سٕندِ حُکمس مُطٲبق تہٕ یدوتون سٕندِ حُکمس مُطٲبق۔ تہٕ پورٹر ٲسۍ پرٮ۪تھ دروازس پیٹھ پیاران۔ تِم ہیکن نہٕ پننہِ خدمتہٕ نِش نیرِتھ۔ پننین باین ہٕندِ خٲطرٕ کٔر لاویو تِہندِ خٲطرٕ تیار۔ {جاے: ہیب۔ سٹیشن}\n16. یێمہِ دۅہہ آیہ خداوند سٕنز سورے خدمت تیار کرنہٕ، فسح تھاونہٕ خٲطرٕ، تہٕ بادشاہ یوسیاہ سٕندِ حُکمہٕ مُطٲبق خداوند سٕندِس قربان گاہَس پیٹھ زالنہٕ خٲطرٕ پیش کرنہٕ خٲطرٕ۔\n17. تہٕ بنی اسرٲیلِیو یُس اَمہِ وِزِ موجود اوس، فسح تہٕ سَتھ دۅہہٕ خمیرٕ روٚس روٹی ہُند عید منوو۔ {موجود: ہیب۔ لٔب}\n18. تہٕ سموئیل پیغمبر سٕندِ دۅہہٕ پیٹھٕ اوس نہٕ اسرٲیلِس مَنٛز تھاونہٕ آمُت۔ نۂ کٔر اسرٲیلٕکۍ سارِوٕے بادشاہو یُتھ فسح یُس یوسیاہ ہُند مناونہٕ آو، تہٕ پادٕرۍ تہٕ لاوی تہٕ سارِنٕے یہوداہ تہٕ اسرٲیلِس یُس حٲضِر اوس، تہٕ یروشلمٕکۍ روزن وٲلۍ۔ {موجود: ہیب۔ لٔب}\n19. یوسیاہ سٕندِ دورِ حکومتہٕ کِس اردٲہمہِ ؤریس مَنٛز آو یہِ فسح تھاونہٕ۔\n20.\\tیێمہِ سارِوٕے پَتہٕ ییلہ یوسیاہ ہن مندر تیار کٔر، مصرُک بادشاہ نیکو آو فرات کہِ طرفہٕ کارکمیشس خلاف لڑنہٕ خٲطرٕ، تہٕ یوسیاہ دراو أمِس خٕلاف۔ {مندر: ہیب۔ ہاؤس}\n21.\\tمگر تٔمۍ سوٗزۍ تس نِش سفیر تہٕ وونُن زِ یہوداہُک بادشاہ، مے کیا چُھہ ژے سٍتـ̡ واٹھ دِنہٕ۔ {بہٕ چُھس} نہٕ از ژے خٕلاف، بلکہ تتھ گرس خلاف یتھ سٍتۍ بہٕ جنگ چُھ، کیازِ خداین چُھ مے جلدی کرنُک حُکُم دِتمُت: خدایہ سٕندِس سٍتـ̡ {مداخلت} کرنہٕ نِش رُکٲوِتھ یُس میہ سٍتـ̡ چُھ، یُس نہٕ ژے تباہ کرُن۔{گرٕ...: Heb. میانہِ جنگُک گھر}\n22.\\tبہر حال یوسیاہ ہیوٚت نہ پانس نِش بُتھ پھیُر، بلکہ لوٚگ پان پوش، یُتھ زن سُہ أمِس سٍتـ̡ لڑایہِ، تہٕ بوزُن نہٕ خدایہ سٕندِ زبانہِ سٍتـ̡ نیکو سٕندِس کلامَس سٍتـ̡ تہٕ آو میگیڈو کِس وادی مَنٛز لڑنہِ۔\n23.\\tتہٕ تیر اندازو لٔگۍ بادشاہ جوشیاہس کُن گولہِ۔ تہٕ بادشاہن ووٚن پننین خادمَن ، مے کٔرِو دور۔ تکیازِ بہٕ چُھس دگ زخم۔ {زخمی: ہیب۔ بیمار بنیومُت}\n24.\\tتٔمۍ سٕندِس نوکرَو کٔر سُہ اَمہِ رتھٕ منزٕ نیبر تہٕ تھووُن أمِس دوٚیمِس رتھَس منٛز۔ تہٕ تِمو أنۍ سُہ یروشلم، تہٕ سُہ موٗد تہٕ سُہ آو پننین مٲلن ہٕندِس قبرس مَنٛز دفن کرنہٕ۔ تہٕ سارِوٕے یہوداہ تہٕ یروشلم کٔر یوسیاہ سٕندِ خٲطرٕ ماتم ۔ {اکس منز...: یا، قبرن منز}\n25.\\tتہٕ یرمیاہ کٔر یوسیاہ سٕندِ خٲطرٕ ماتم تہٕ سارِوٕے گٮ۪ون وٲلۍ مرد تہٕ گٮ۪ون واجنہِ زنانہٕ از تام پننین ماتم مَنٛز یوسیاہ سٕنز کتھ کٔرِتھ، تہٕ بنووُکھ تِمن اسرٲیلِس مَنٛز اکھ حکم۔\n26.\\tوُنہِ یُسیاہ سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕنزِ نیکی مُطٲبق یُس خداوند سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت چھُ، {نیکی: حب۔ مہربانی }\n27. تہٕ تٔمۍ سٕندِ اعمال چِھہ گۅڈنچہ تہٕ ٲخری کِس کتابس مَنٛز لیکھنہٕ آمٕتۍ۔","1. پَتہٕ رٔٹِتھ کٔر یُسیاہ سُند نیچو یہواحاز، تہٕ بنووُکھ یروشلمس مَنٛز پننِس مٲلہِ سٕندِ بدلہٕ بادشاہ۔\n2. یہوہاز اوس وُہُہ تہٕ تریہ وُہُر وُہُر ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز تریہ ریتن ہٕنز حکومت۔\n3. تہٕ مصرٕکۍ بادشاہن ترٛوو سُہ یروشلمس مَنٛز، تہٕ ہتھ رۄپہٕ تہٕ سۄنہٕ سٕندِس ٹیلنٹ سٍتـ̡ دِژ زمینٕچ مذمت۔ {پُٹ...: ہیب۔ ہٹٲوِتھ ہٹٲوِتھ\n4. تہٕ مصرٕکۍ بادشاہن بنوو الیاقیم پنُن بوے یہوداہ تہٕ یروشلمس پیٹھ بادشاہ، تہٕ بنووُن تٔمۍ سُند ناو یہویاکیم۔ تہٕ نیکو نیو پنُن بوے یہواہاز تہٕ نِیوو مصر۔\n5.\\tیہویاقیم اوس وُہن وُہُن وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز کاہ وُہُر حکومت: تہٕ تٔمۍ کٔر خداوند پننِس خدایہ سٕندِس نظرس مَنٛز بد کار۔\n6.\\tأمِس خٕلاف آو بابلُک بادشاہ نبوکدنضر، تہٕ کوٚرُن سُہ بابل نِنہٕ خٲطرٕ زنجیر لٲگِتھ۔ {زنجیر: یا، زنجیر}\n7. نبوکدنضرن نِش تہِ نِیہِ خداوند سٕندِ گرٕکۍ بانہٕ بابل تہٕ تھووُن بابل کِس مندرس مَنٛز۔\n8.\\tوُن یہویاقیم سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕنزِ مکروہ کامہِ یُس أمِس کٔرِتھ تہٕ یُس أمِس مَنٛز لبنہٕ آو، وُچھِو تِم چھِ اسرٲیلِس تہٕ یہوداہ کِس بادشاہن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ، تہٕ یہویاکین سٕندِ نیچوِس کٔر أمِس بدلہٕ حکومت۔ {یہویاچن: یتھ جیکونیا، یا کونیاہ تہِ ونان چھِ}\n9.\\tیہویاکین اوس ٲٹھ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز تریہ ریتن تہٕ دہن دۅہن حکومت۔\n10. تہٕ ییلہ ؤری مۄکلیوو، بادشاہ نبوکدنضرن سوٗز، تہٕ أنِن سُہ خداوند سٕندِ گرٕ سٕندِ نیک بانہٕ ہیتھ بابل تہٕ بنووُن صدیقیاہ پَنُن بوے یہوداہ تہٕ یروشلمس پیٹھ بادشاہ۔ {ییلہ...: ہیب۔ ؤری کس واپسی} {گُڈلی...: ہیب۔ خواہشُک برتن} {صدقیہ...: یا، متانیا، تٔمۍ سٕندِس مٲل سُند بوے }\n11. صدیقیاہ اوس اَکھ وُہُر وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ یِمو کٔرٕن یروشلمس مَنٛز کاہ ؤری حکومت۔\n12.\\tتہٕ یُس خداوند پننِس خدایہ سٕندِس نظرس منز بد کار اوس، {تہٕ} کٔرٕن نہٕ یرمیاہ نبی سٕندِس برونہہ کُن پان عاجز۔\n13. تہٕ تٔمۍ کٔر بادشاہ نبوکدنضرس خلاف تہِ بغاوت، یٔمۍ أمِس خدایہِ سُند قسم اوس دِژمُت، مگر تٔمۍ کٔر گردن مضبوط، تہٕ کوٚرُن پنُن دِل اسرٲیلِکِس خدایہِ سٕندِس خداہس کُن پھیرنہٕ نِش سخت۔\n14.\\tامہِ علاوہ کٔر سارِوٕے پادٕرین تہٕ عوامس سٍتـ̡ کافرن ہٕنزِ تمام بدکاریو پتہٕ واریاہ زیادٕ۔ تہٕ کٔرٕن خداوند سُند گرٕ آلودہ یُس تٔمۍ یروشلمس مَنٛز مقدس اوس کوٚرمُت۔\n15.\\tتہٕ تِمن ہٕندِس آباؤ اجداد سُند خدا، یُس تِمن نِش پننین رسولن ہٕندِ طرفہٕ سوزمُت اوس، سُہ وُچھِتھ تہٕ سوزُن۔ تکیازِ تس اوس پننین لوکن پیٹھ تہٕ پننس مکانس پیٹھ رحم کران: {by: Heb. اتھہٕ سٍتۍ} {betimes: یعنی مسلسل تہٕ احتیاط سان}\n16.\\tمگر تِمو کٔر خدایہ سٕندِس رسولن سٍتـ̡ طنز تہٕ تٔمۍ سٕندِس کلامَس حقارت کٔرِتھ تہٕ تٔمۍ سٕندِس پیغمبرن ہُند غلط استعمال کٔرِتھ، یوتام نہٕ خداوند سُند قہر تٔمۍ سٕندِس لُکن پیٹھ ووٚتھ، یوتام نہٕ کانہہ علاج سپدِ۔ {علاج: ہیب۔ شفا بخش}\n17.\\tتێلہِ اوٚن تِمن پیٹھ کلدین ہُند بادشاہ، یٔمۍ تِہندِ جوان تلوار سٍتـ̡ مارِ، تہٕ أمِس اوس نہٕ جوان یا کورِس، بُزرگ، یا وٲنسہِ ہٕندِس سٍتـ̡ دِژُن نہٕ رحم۔\n18. تہٕ خدایہ سٕندِ گرٕکۍ سارِنٕے بانہٕ، بٔڈ تہٕ لۄکٕٹۍ، تہٕ خداوند سٕندِ گرٕکۍ خزانہٕ، تہٕ بادشاہ سٕندِ تہٕ تٔمۍ سٕندِس شہزادن ہٕندِ خزانہٕ۔ یم سٲری {یِم} أنۍ تم بابل منٛز۔\n19. تہٕ تِمو زٲلِکھ خدایہ سُند گر، تہٕ یروشلمُک دیوار پھُٹرٲوِتھ تہٕ اَمہ کِس سارِنٕے محل زٲلِکھ نارٕ سٍتـ̡ تہٕ تِمن ہٕندِس سارِنٕے نیک بانہٕ تباہ کٔرِتھ۔\n20. تہٕ یُس تلوار نِش ژلِتھ ژٔلِتھ سُہ نِش بابل کُن نِتھ۔ ییتہ تم فارس کس بادشاہت کس دورس تام أمس تہٕ تٔمۍ سٕنٛدین نیچوین ہٕندۍ خادم ٲسۍ: {تِم...: ہیب۔ تلوار پیٹھہٕ باقی}\n21.\\tیورمیاہ سٕندِ زبانہِ سٍتـ̡ خداوند سُند کلام پورٕ کرنہٕ خٲطرٕ، یوتام نہٕ زمینہٕ تسٕندِس سبت دۅہہٕ سٍتـ̡ لُطف دِنہٕ خٲطرٕ: {کیازِ} یوتام سُہ ویران روزِ، توٚت تام ٲس سبت تہٕ تریہ تہٕ داہ ؤری پوٗرٕ کرنہٕ خٲطرٕ۔\n22.\\tوۆن فارس کِس بادشاہ سائرس سٕندِس گۄڈنِکِس ؤریس مَنٛز، یُس یرمیاہ سٕندِ واتنہٕ سٍتـ̡ خداوند سُند کلام پورٕ سپدِ، خداوند کٔر فارس کِس بادشاہ سائرس سُند روح ہُریل، زِ تٔمۍ کٔر پنہٕ نِس سٲرِسٕے سلطنتس مَنٛز اعلان تہٕ لیکھِتھ تہِ وونُن،\n23. یِتھٕ پٲٹھۍ چُھ فارس کِس بادشاہ سائرس ونان زِ زمینہٕ کِس سارنٕے بادشاہتن چُھ اسمانُک خداوند دِژمُت۔ تہٕ تٔمۍ چُھ مےٚ یروشلمس مَنٛز اکھ مکانہٕ بناونُک حکم دِژمُت، یُس یہوداہَس مَنٛز {چُھ}۔ تٔمۍ سٕندِس سارِنٕے لوٗکَن مَنٛز کُس چُھ؟ خداوند پنُن خدایہ آسُن أمِس سٍتـ̡ تہٕ دِیُن سُہ ہیوٚر کھسُن۔"];
